    #[test]
    fn test_memory_intrinsic_helper_call_encodes_relocatable_call_fixup() {
        let mut func = minimal_func("memory_intrinsic_helper_call");
        func.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::Call,
                vec![X86ISelOperand::Symbol("memcpy".to_string())],
            ),
        );
        let pipeline = raw_no_frame_x86_pipeline();

        let (code, cp_fixups, call_fixups, global_ref_fixups) = pipeline
            .encode_function_with_all_fixups(&func, &HashMap::new())
            .unwrap();

        assert_eq!(code, vec![0xE8, 0, 0, 0, 0]);
        assert!(cp_fixups.is_empty());
        assert!(global_ref_fixups.is_empty());
        assert_eq!(call_fixups.len(), 1);
        assert_eq!(call_fixups[0].offset, 1);
        assert_eq!(call_fixups[0].callee, "memcpy");
    }

