    #[test]
    fn test_v4i32_mask_extract_bitpack_formula_covers_all_lane_masks() {
        for lane_mask in 0_u32..16 {
            let mut pmovmskb = 0_u32;
            for lane in 0..4 {
                if lane_mask & (1 << lane) != 0 {
                    pmovmskb |= 0x0f << (lane * 4);
                }
            }

            let packed = ((pmovmskb * 39) >> 9) & 0x0f;
            assert_eq!(
                packed, lane_mask,
                "PMOVMSKB lane sign bits {pmovmskb:#06x} must compact to {lane_mask:#x}"
            );
        }
    }

    #[test]
    fn test_v16i8_mask_extract_bitpack_formula_covers_all_lane_masks() {
        for lane_mask in 0_u32..=0xffff {
            let mut pmovmskb = 0_u32;
            for lane in 0..16 {
                if lane_mask & (1 << lane) != 0 {
                    pmovmskb |= 1 << lane;
                }
            }

            let packed = pmovmskb & 0xffff;
            assert_eq!(
                packed, lane_mask,
                "PMOVMSKB byte sign bits {pmovmskb:#06x} must compact to {lane_mask:#06x}"
            );
        }
    }

    #[test]
    fn test_v8i16_mask_extract_bitpack_formula_covers_all_lane_masks() {
        for lane_mask in 0_u32..256 {
            let mut pmovmskb = 0_u32;
            for lane in 0..8 {
                if lane_mask & (1 << lane) != 0 {
                    pmovmskb |= 0x03 << (lane * 2);
                }
            }

            let mut packed = pmovmskb & 0x5555;
            packed = (packed | (packed >> 1)) & 0x3333;
            packed = (packed | (packed >> 2)) & 0x0f0f;
            packed = (packed | (packed >> 4)) & 0x00ff;
            assert_eq!(
                packed, lane_mask,
                "PMOVMSKB word sign-bit pairs {pmovmskb:#06x} must compact to {lane_mask:#04x}"
            );
        }
    }

    #[test]
    fn test_v2i64_mask_extract_bitpack_formula_covers_all_lane_masks() {
        for lane_mask in 0_u32..4 {
            let mut pmovmskb = 0_u32;
            for lane in 0..2 {
                if lane_mask & (1 << lane) != 0 {
                    pmovmskb |= 0xff << (lane * 8);
                }
            }

            let packed = (pmovmskb >> 7) & 0x03;
            assert_eq!(
                packed, lane_mask,
                "PMOVMSKB lane sign bits {pmovmskb:#06x} must compact to {lane_mask:#x}"
            );
        }
    }

