    #[test]
    fn test_pipeline_rejects_malformed_v4i32_mask_extract() {
        let mut func = minimal_func("v4i32_mask_extract_bad_operands");
        func.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::V4I32MaskExtract,
                vec![X86ISelOperand::PReg(XMM0), X86ISelOperand::PReg(XMM1)],
            ),
        );
        let pipeline = raw_no_frame_x86_pipeline();

        let err = pipeline
            .compile_function(&func)
            .expect_err("malformed V4I32MaskExtract must fail closed");
        match err {
            X86PipelineError::ISel(msg) => assert!(
                msg.contains("V4I32MaskExtract requires dst_gpr32 and src_xmm"),
                "unexpected diagnostic: {msg}"
            ),
            other => panic!("expected ISel fail-closed error, got {other:?}"),
        }
    }

