    #[test]
    fn test_three_address_rm_alu_isel_shapes_fail_closed() {
        let pipeline = raw_no_frame_x86_pipeline();

        for opcode in [X86Opcode::AddRM, X86Opcode::SubRM, X86Opcode::ImulRM] {
            let mut func = minimal_func("three_address_rm_alu_fail_closed");
            let dst = VReg::new(0, RegClass::Gpr64);
            let lhs = VReg::new(1, RegClass::Gpr64);
            let base = VReg::new(2, RegClass::Gpr64);
            func.next_vreg = 3;

            func.push_inst(
                Block(0),
                X86ISelInst::new(
                    opcode,
                    vec![
                        X86ISelOperand::VReg(dst),
                        X86ISelOperand::VReg(lhs),
                        X86ISelOperand::MemAddr {
                            base: Box::new(X86ISelOperand::VReg(base)),
                            disp: 8,
                        },
                    ],
                ),
            );

            match pipeline.compile_function(&func) {
                Err(X86PipelineError::ISel(msg)) => {
                    assert!(
                        msg.contains("three-address RM ALU ISel operands are not supported"),
                        "unexpected {opcode:?} fail-closed message: {msg}"
                    );
                    assert!(
                        msg.contains(&format!("{opcode:?}")),
                        "message should name failing opcode: {msg}"
                    );
                }
                other => panic!("expected {opcode:?} to fail closed in ISel, got {other:?}"),
            }
        }
    }

    #[test]
    fn test_encode_function_movrr_gpr32_uses_32_bit_encoding() {
        let mut func = minimal_func("movrr32_encode");
        let entry = Block(0);
        let dst = VReg::new(0, RegClass::Gpr32);
        let src = VReg::new(1, RegClass::Gpr32);
        func.next_vreg = 2;
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![X86ISelOperand::VReg(dst), X86ISelOperand::VReg(src)],
            ),
        );

        let pipeline = raw_no_frame_x86_pipeline();

        let mut legacy_alloc = HashMap::new();
        legacy_alloc.insert(dst, EAX);
        legacy_alloc.insert(src, ECX);
        let legacy = pipeline.encode_function(&func, &legacy_alloc).unwrap();
        assert_eq!(legacy, vec![0x89, 0xC8]);

        let mut extended_alloc = HashMap::new();
        extended_alloc.insert(dst, R8D);
        extended_alloc.insert(src, R9D);
        let extended = pipeline.encode_function(&func, &extended_alloc).unwrap();
        assert_eq!(extended, vec![0x45, 0x89, 0xC8]);
    }

    fn optimizable_add_ri_func(name: &str) -> X86ISelFunction {
        let mut func = minimal_func(name);
        func.next_vreg = 2;
        func.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::MovRI,
                vec![test_vreg_op(0), X86ISelOperand::Imm(10)],
            ),
        );
        func.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::AddRI,
                vec![test_vreg_op(1), test_vreg_op(0), X86ISelOperand::Imm(20)],
            ),
        );
        func.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::CmpRI,
                vec![test_vreg_op(1), X86ISelOperand::Imm(30)],
            ),
        );
        func.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![X86ISelOperand::PReg(RAX), test_vreg_op(1)],
            ),
        );
        func.push_inst(Block(0), X86ISelInst::new(X86Opcode::Ret, vec![]));
        func
    }

    #[test]
    fn x86_isel_to_regalloc_uses_carried_inst_flags() {
        let mut func = minimal_func("flags_to_regalloc");
        func.push_inst(
            Block(0),
            X86ISelInst::with_flags(X86Opcode::Ret, vec![], InstFlags::READS_MEMORY),
        );

        let ra_func = x86_isel_to_regalloc(&func).unwrap();

        assert_eq!(ra_func.insts.len(), 1);
        assert_eq!(ra_func.insts[0].opcode, X86Opcode::Ret as u16);
        assert_eq!(ra_func.insts[0].flags, InstFlags::READS_MEMORY);
    }

    /// An internal multi-result `ret` (results past RAX,RDX / XMM0,XMM1): its
    /// return moves reach the allocator as EXPLICIT physical producers and the
    /// `ret` reads every register they wrote, so a written result register is
    /// reserved until the return. A C-shaped return converts exactly as it
    /// always did: implicit physical defs, no return sinks.
    #[test]
    fn x86_isel_to_regalloc_models_internal_multi_result_returns_as_sinks() {
        use trust_cg_lower::x86_64_isel::X86CallResultReg;
        let returns = [
            (RAX, 0u32),
            (RDX, 1),
            (x86_64_regs::RCX, 2),
            (x86_64_regs::RSI, 3),
        ];
        let build = |internal: Vec<X86CallResultReg>, moves: &[(X86PReg, u32)]| {
            let mut func = minimal_func("internal_ret");
            // Four I64 results: RAX, RDX (C file), then RCX, RSI (internal)
            // when the ret declares them; two (the C-shaped control) otherwise.
            func.sig.returns = vec![Type::I64; if internal.is_empty() { 2 } else { 4 }];
            for (reg, vreg) in moves {
                func.push_inst(
                    Block(0),
                    X86ISelInst::new(
                        X86Opcode::MovRR,
                        vec![X86ISelOperand::PReg(*reg), test_vreg_op(*vreg)],
                    ),
                );
            }
            func.push_inst(
                Block(0),
                X86ISelInst::new(X86Opcode::Ret, vec![]).with_internal_return_regs(internal),
            );
            func
        };
        let internal = vec![
            X86CallResultReg::new(x86_64_regs::RCX, 64),
            X86CallResultReg::new(x86_64_regs::RSI, 64),
        ];

        let ra = x86_isel_to_regalloc(&build(internal.clone(), &returns)).unwrap();
        let fixed: Vec<_> = returns
            .iter()
            .map(|(reg, _)| x86_fixed_operand_to_preg(*reg).unwrap())
            .collect();
        for (index, preg) in fixed.iter().enumerate() {
            assert_eq!(ra.insts[index].defs, vec![RegAllocOperand::PReg(*preg)]);
            assert!(ra.insts[index].implicit_defs.is_empty());
        }
        let ret = ra.insts.last().unwrap();
        assert_eq!(
            ret.implicit_uses, fixed,
            "the ret reads every result it returns"
        );

        // A C-shaped return: unchanged representation.
        let ra = x86_isel_to_regalloc(&build(vec![], &returns[..2])).unwrap();
        for (index, preg) in fixed[..2].iter().enumerate() {
            assert!(ra.insts[index].defs.is_empty());
            assert_eq!(ra.insts[index].implicit_defs, vec![*preg]);
        }
        assert!(ra.insts.last().unwrap().implicit_uses.is_empty());

        // Fail closed when a declared internal result has no producer...
        let error = x86_isel_to_regalloc(&build(internal.clone(), &returns[..3])).unwrap_err();
        assert!(
            format!("{error:?}").contains("no return move writes rsi"),
            "{error:?}"
        );
        // A pseudo after the `ret` does not hide it: the window and the sinks
        // are still found.
        let mut func = build(internal.clone(), &returns);
        func.push_inst(Block(0), X86ISelInst::new(X86Opcode::Nop, vec![]));
        let ra = x86_isel_to_regalloc(&func).unwrap();
        assert_eq!(ra.insts[0].defs, vec![RegAllocOperand::PReg(fixed[0])]);
        assert_eq!(ra.insts[returns.len()].implicit_uses, fixed);
        // ...and when a C-file result's move is not in the window.
        let mut func = build(internal, &returns[1..]);
        let entry = func.blocks.get_mut(&Block(0)).unwrap();
        entry.insts.insert(
            0,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![X86ISelOperand::PReg(RAX), test_vreg_op(9)],
            ),
        );
        entry
            .insts
            .insert(1, X86ISelInst::new(X86Opcode::Nop, vec![]));
        let error = x86_isel_to_regalloc(&func).unwrap_err();
        assert!(
            format!("{error:?}").contains("no return move writes rax"),
            "{error:?}"
        );
    }

    #[test]
    fn x86_isel_to_regalloc_preserves_ptest_operand_precise_memory_flags() {
        let mut func = minimal_func("ptest_flags_to_regalloc");
        func.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::Ptest,
                vec![X86ISelOperand::PReg(XMM0), X86ISelOperand::PReg(XMM1)],
            ),
        );
        func.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::Ptest,
                vec![
                    X86ISelOperand::PReg(XMM0),
                    X86ISelOperand::MemAddr {
                        base: Box::new(X86ISelOperand::PReg(RAX)),
                        disp: 16,
                    },
                ],
            ),
        );

        let ra_func = x86_isel_to_regalloc(&func).unwrap();

        assert_eq!(ra_func.insts.len(), 2);
        assert!(ra_func.insts[0].flags.has_side_effects());
        assert!(!ra_func.insts[0].flags.reads_memory());
        assert!(ra_func.insts[1].flags.has_side_effects());
        assert!(ra_func.insts[1].flags.reads_memory());
    }

    #[test]
    fn empty_x86_pass_manager_preserves_compile_output() {
        let func = build_x86_const_test_function();
        let pipeline = raw_no_frame_x86_pipeline();
        let baseline = pipeline.compile_function(&func).unwrap();
        let mut pm = trust_cg_opt::X86PassManager::new();

        let with_empty_pm = pipeline
            .compile_function_with_pass_manager(&func, &mut pm)
            .unwrap();

        assert_eq!(with_empty_pm, baseline);
    }

    #[test]
    fn default_x86_pass_manager_runs_licm_const_fold_copy_prop_cse_peephole_then_dce() {
        let pm = X86Pipeline::default_x86_pass_manager();

        assert_eq!(
            pm.pass_names(),
            vec![
                "x86-vectorize",
                "x86-sroa",
                // The SECOND vectorizer run, immediately after SROA, is part of the
                // DEFAULT schedule since 2026-09-29: it is where an owning-container
                // reduction first has a recognisable shape (slice temp promoted, the
                // peephole not yet having re-spelled the header test or the element
                // address), and it is what takes h1_vec_push_sum from 2.4890x to
                // 1.0023x LLVM. `no-vectorize-post-sroa` is the forensic opt-out.
                "x86-vectorize",
                "x86-licm",
                "x86-strength-reduce",
                "x86-loop-unroll",
                "x86-const-fold",
                "x86-const-guard-elim",
                "x86-block-merge",
                "x86-slot-forward",
                "x86-copy-prop",
                "x86-cse",
                "x86-peephole",
                "x86-bounds-check-elim",
                // DEFAULT ON since 2026-10-01: b1_mispredict 1.0959 -> 1.0260,
                // ~60x its noise floor. Runs AFTER the peephole because `BtRI`
                // — the one-bit consumer it targets — is SYNTHESIZED there and
                // does not exist in ISel output.
                "x86-xorshift-demanded-bits",
                "x86-dce",
                "x86-loop-rotate",
                "x86-cmov-swap",
                "x86-if-convert",
                "x86-branch-layout",
            ]
        );
    }

    #[test]
    fn x86_opt_level_pass_schedules_match_policy() {
        let pass_names = |level| {
            let pm = X86Pipeline::x86_pass_manager_for_opt_level(
                level,
                X86PipelineConfig::default().call_abi,
            );
            pm.pass_names()
                .into_iter()
                .map(str::to_string)
                .collect::<Vec<_>>()
        };

        assert!(pass_names(trust_cg_opt::OptLevel::O0).is_empty());
        assert_eq!(
            pass_names(trust_cg_opt::OptLevel::O1),
            vec![
                "x86-licm".to_string(),
                "x86-copy-prop".to_string(),
                "x86-peephole".to_string(),
                "x86-dce".to_string(),
                "x86-if-convert".to_string(),
                "x86-branch-layout".to_string(),
            ]
        );

        let production_order = vec![
            "x86-vectorize".to_string(),
            "x86-sroa".to_string(),
            // The SECOND vectorizer run, part of the DEFAULT schedule since
            // 2026-09-29 (see the note on the other expectation in this file).
            "x86-vectorize".to_string(),
            "x86-licm".to_string(),
            "x86-strength-reduce".to_string(),
            "x86-loop-unroll".to_string(),
            "x86-const-fold".to_string(),
            "x86-const-guard-elim".to_string(),
            "x86-block-merge".to_string(),
            "x86-slot-forward".to_string(),
            "x86-copy-prop".to_string(),
            "x86-cse".to_string(),
            "x86-peephole".to_string(),
            "x86-bounds-check-elim".to_string(),
            "x86-xorshift-demanded-bits".to_string(),
            "x86-dce".to_string(),
            "x86-loop-rotate".to_string(),
            "x86-cmov-swap".to_string(),
            "x86-if-convert".to_string(),
            "x86-branch-layout".to_string(),
        ];
        assert_eq!(pass_names(trust_cg_opt::OptLevel::O2), production_order);
        assert_eq!(pass_names(trust_cg_opt::OptLevel::Os), production_order);
        assert_eq!(pass_names(trust_cg_opt::OptLevel::O3), production_order);
    }

    /// Fresh processes isolate tracked policy; thread-local overrides isolate
    /// environment fallback. Exercise actual inversion with production admission.
    #[test]
    fn branch_layout_fallthrough_isolated_policy() {
        const CHILD: &str = "CG_BRANCH_LAYOUT_POLICY_CASE";
        const TEST: &str = "x86_64::pipeline::tests::branch_layout_fallthrough_isolated_policy";
        let Ok(case) = std::env::var(CHILD) else {
            let mut failures = Vec::new();
            for case in [
                "default",
                "zero",
                "one",
                "empty",
                "installed_on",
                "installed_off",
            ] {
                let mut command = std::process::Command::new(std::env::current_exe().unwrap());
                command.args(["--exact", TEST, "--nocapture", "--test-threads=1"]);
                command.env(CHILD, case);
                let output = command.output().unwrap();
                let stdout = String::from_utf8_lossy(&output.stdout);
                println!(
                    "case {case}:\n{stdout}{}",
                    String::from_utf8_lossy(&output.stderr)
                );
                if !output.status.success() || !stdout.contains("running 1 test") {
                    failures.push(case);
                }
            }
            assert!(failures.is_empty(), "failed cases: {failures:?}");
            return;
        };
        // The rule is DEFAULT ON since 2026-09-30, so the environment fallback is the
        // opt-OUT `TCG_NO_BRANCH_LAYOUT_FALLTHROUGH`. `=0` therefore means "do not
        // disable" (still on) and `=1` / `=""` mean disabled — the mirror of the old
        // opt-in table.
        let env_value = match case.as_str() {
            "zero" | "installed_on" => Some("0"),
            "one" | "installed_off" => Some("1"),
            "empty" => Some(""),
            _ => None,
        };
        if case.starts_with("installed_") {
            let enabled = case == "installed_on";
            assert!(set_branch_layout_fallthrough_enabled(enabled));
            assert!(set_branch_layout_fallthrough_enabled(enabled));
            assert!(!set_branch_layout_fallthrough_enabled(!enabled));
        }
        // DEFAULT ON: the rule is enabled unless the opt-out says otherwise. `zero`
        // (`=0`) does not opt out, so it stays enabled, and `default` is enabled too.
        let enabled = matches!(case.as_str(), "default" | "zero" | "installed_on");
        let check = || {
            use trust_cg_opt::X86MachinePass;
            let config = x86_branch_layout_config();
            assert_eq!(config.fallthrough_rule, enabled);
            let mut func = X86ISelFunction::new(
                "policy".into(),
                Signature {
                    params: vec![],
                    returns: vec![],
                },
            );
            for b in [Block(0), Block(1), Block(2)] {
                func.ensure_block(b);
            }
            func.push_inst(
                Block(0),
                X86ISelInst::new(
                    X86Opcode::Jcc,
                    vec![
                        X86ISelOperand::CondCode(X86CondCode::E),
                        X86ISelOperand::Block(Block(1)),
                    ],
                ),
            );
            func.push_inst(
                Block(0),
                X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(Block(2))]),
            );
            for b in [Block(1), Block(2)] {
                func.push_inst(b, X86ISelInst::new(X86Opcode::Ret, vec![]));
            }
            func.blocks.get_mut(&Block(0)).unwrap().successors = vec![Block(1), Block(2)];
            trust_cg_opt::X86BranchLayout::with_config(admit_x86_cc_inversion, config)
                .run(&mut func);
            let block = &func.blocks[&Block(0)];
            assert_eq!(
                block.insts[0].operands,
                vec![
                    X86ISelOperand::CondCode(if enabled {
                        X86CondCode::NE
                    } else {
                        X86CondCode::E
                    }),
                    X86ISelOperand::Block(Block(if enabled { 2 } else { 1 }))
                ]
            );
            assert_eq!(
                block.insts[1].operands,
                vec![X86ISelOperand::Block(Block(if enabled { 1 } else { 2 }))]
            );
        };
        crate::env_lock::with_env_overrides_removed(
            &[
                "TCG_NO_BRANCH_LAYOUT_FALLTHROUGH",
                "TCG_NO_X86_COLD_TRAP_LAYOUT",
                "TCG_NO_X86_LOOP_EXIT_LAYOUT",
                "TCG_X86_COLD_ARM_SINK",
            ],
            || {
                if let Some(value) = env_value {
                    crate::env_lock::with_env_overrides(
                        &[("TCG_NO_BRANCH_LAYOUT_FALLTHROUGH", value)],
                        check,
                    );
                } else {
                    check();
                }
            },
        );
    }

    /// The kill switch removes exactly the OPT-8 pass from both schedules.
    #[test]
    fn x86_branch_layout_kill_switch_removes_only_that_pass() {
        let names = |pm: &trust_cg_opt::X86PassManager| {
            pm.pass_names()
                .into_iter()
                .map(str::to_string)
                .collect::<Vec<_>>()
        };

        let o1_on = X86Pipeline::x86_o1_pass_manager_with_branch_layout(true);
        let o1_off = X86Pipeline::x86_o1_pass_manager_with_branch_layout(false);
        assert_eq!(
            names(&o1_on).last().map(String::as_str),
            Some("x86-branch-layout")
        );
        assert_eq!(names(&o1_on)[..names(&o1_on).len() - 1], names(&o1_off)[..]);

        let call_abi = X86PipelineConfig::default().call_abi;
        let o2_on = X86Pipeline::x86_o2_pass_manager_with_branch_layout(true, call_abi);
        let o2_off = X86Pipeline::x86_o2_pass_manager_with_branch_layout(false, call_abi);
        assert_eq!(
            names(&o2_on).last().map(String::as_str),
            Some("x86-branch-layout")
        );
        assert_eq!(names(&o2_on)[..names(&o2_on).len() - 1], names(&o2_off)[..]);
    }

    /// OPT-8 encoder elision: a block-trailing `jmp <layout-next>` must
    /// compile to EXACTLY the bytes of the same function with the jmp absent
    /// (fall-through identity), while a jmp to a non-adjacent block still
    /// emits its 5 bytes.
    #[test]
    fn trailing_jmp_to_layout_next_elides_to_fallthrough_identity() {
        let sig = Signature {
            params: vec![],
            returns: vec![Type::I64],
        };
        let pipeline = raw_no_frame_x86_pipeline();

        // Variant 1: entry ends `jmp b1` with b1 the layout successor.
        let mut with_jmp = X86ISelFunction::new("elide_jmp".to_string(), sig.clone());
        let (b0, b1) = (Block(0), Block(1));
        for b in [b0, b1] {
            with_jmp.ensure_block(b);
        }
        with_jmp.push_inst(
            b0,
            X86ISelInst::new(
                X86Opcode::MovRI,
                vec![
                    X86ISelOperand::PReg(x86_64_regs::RAX),
                    X86ISelOperand::Imm(7),
                ],
            ),
        );
        with_jmp.push_inst(
            b0,
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(b1)]),
        );
        with_jmp.push_inst(b1, X86ISelInst::new(X86Opcode::Ret, vec![]));
        with_jmp.blocks.get_mut(&b0).unwrap().successors = vec![b1];

        // Variant 2: identical, but pure fall-through (no jmp at all).
        let mut without_jmp = X86ISelFunction::new("elide_jmp".to_string(), sig.clone());
        for b in [b0, b1] {
            without_jmp.ensure_block(b);
        }
        without_jmp.push_inst(
            b0,
            X86ISelInst::new(
                X86Opcode::MovRI,
                vec![
                    X86ISelOperand::PReg(x86_64_regs::RAX),
                    X86ISelOperand::Imm(7),
                ],
            ),
        );
        without_jmp.push_inst(b1, X86ISelInst::new(X86Opcode::Ret, vec![]));
        without_jmp.blocks.get_mut(&b0).unwrap().successors = vec![b1];

        let jmp_bytes = pipeline.compile_function(&with_jmp).unwrap();
        let fallthrough_bytes = pipeline.compile_function(&without_jmp).unwrap();
        assert_eq!(
            jmp_bytes, fallthrough_bytes,
            "jmp <layout-next> must be a byte-level fall-through identity"
        );

        // Variant 3: the jmp targets a NON-adjacent block — must still emit
        // its 5 near-jmp bytes (no over-elision).
        let mut far_jmp = X86ISelFunction::new("far_jmp".to_string(), sig);
        let (b0, b1, b2) = (Block(0), Block(1), Block(2));
        for b in [b0, b1, b2] {
            far_jmp.ensure_block(b);
        }
        far_jmp.push_inst(
            b0,
            X86ISelInst::new(
                X86Opcode::MovRI,
                vec![
                    X86ISelOperand::PReg(x86_64_regs::RAX),
                    X86ISelOperand::Imm(7),
                ],
            ),
        );
        far_jmp.push_inst(
            b0,
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(b2)]),
        );
        // b1 also targets b2, so b2 has TWO predecessors. Without that,
        // `X86BlockMerge` would legitimately fold b2 into b0 and delete the very
        // jmp whose encoding this variant is asserting — the fixture, not the
        // property, would be what changed. b1 -> b2 is adjacent so it elides to
        // a fall-through and contributes no bytes.
        far_jmp.push_inst(
            b1,
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(b2)]),
        );
        far_jmp.push_inst(b2, X86ISelInst::new(X86Opcode::Ret, vec![]));
        far_jmp.blocks.get_mut(&b0).unwrap().successors = vec![b2];
        far_jmp.blocks.get_mut(&b1).unwrap().successors = vec![b2];

        let far_bytes = pipeline.compile_function(&far_jmp).unwrap();
        assert_eq!(
            far_bytes.len(),
            jmp_bytes.len() + 5,
            "non-adjacent jmp keeps its 5 bytes (b1's adjacent jmp elides)"
        );
    }

    /// OPT-8 production wiring, end-to-end at O1: the DEFAULT schedule
    /// (latch rule on, fall-through rule off) — with the validator-backed
    /// `admit_x86_cc_inversion` callback — moves a loop latch's back-edge
    /// off the unconditional `jmp` and onto the (taken) `jcc`, so the hot
    /// loop pays one branch per iteration and the exit `jmp` becomes
    /// elidable. This is the profile-independent win (p2_collatz -32%,
    /// b1_mispredict -13%); the fall-through rule that regressed
    /// p6_branch_match is default-off (`X86BranchLayoutConfig::default`).
    #[test]
    fn o1_schedule_moves_latch_back_edge_onto_the_jcc_via_validated_admission() {
        let sig = Signature {
            params: vec![],
            returns: vec![Type::I64],
        };
        let mut func = X86ISelFunction::new("latch_o1".to_string(), sig);
        // b0 preheader -> b1 body -> b2 latch (cmp; jcc GE exit; jmp header)
        // -> {b3 exit, b1 header}.
        let (b0, b1, b2, b3) = (Block(0), Block(1), Block(2), Block(3));
        for b in [b0, b1, b2, b3] {
            func.ensure_block(b);
        }
        func.push_inst(
            b0,
            X86ISelInst::new(
                X86Opcode::MovRI,
                vec![
                    X86ISelOperand::PReg(x86_64_regs::RAX),
                    X86ISelOperand::Imm(0),
                ],
            ),
        );
        func.push_inst(
            b0,
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(b1)]),
        );
        func.push_inst(
            b1,
            X86ISelInst::new(
                X86Opcode::AddRI,
                vec![
                    X86ISelOperand::PReg(x86_64_regs::RAX),
                    X86ISelOperand::Imm(1),
                ],
            ),
        );
        func.push_inst(
            b2,
            X86ISelInst::new(
                X86Opcode::CmpRI,
                vec![
                    X86ISelOperand::PReg(x86_64_regs::RAX),
                    X86ISelOperand::Imm(10),
                ],
            ),
        );
        func.push_inst(
            b2,
            X86ISelInst::new(
                X86Opcode::Jcc,
                vec![
                    X86ISelOperand::CondCode(X86CondCode::GE),
                    X86ISelOperand::Block(b3),
                ],
            ),
        );
        func.push_inst(
            b2,
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(b1)]),
        );
        func.push_inst(b3, X86ISelInst::new(X86Opcode::Ret, vec![]));
        func.blocks.get_mut(&b0).unwrap().successors = vec![b1];
        func.blocks.get_mut(&b1).unwrap().successors = vec![b2];
        func.blocks.get_mut(&b2).unwrap().successors = vec![b3, b1];

        let pipeline = X86Pipeline::new(X86PipelineConfig {
            opt_level: trust_cg_opt::OptLevel::O1,
            emit_frame: false,
            regalloc_mode: X86RegAllocMode::Simplified,
            ..X86PipelineConfig::default()
        });
        let _ = pipeline.run_x86_optimization_passes(&mut func);

        let latch = &func.blocks[&b2].insts;
        let n = latch.len();
        assert_eq!(
            latch[n - 2].operands,
            vec![
                X86ISelOperand::CondCode(X86CondCode::L),
                X86ISelOperand::Block(b1),
            ],
            "back-edge (header b1) must ride the inverted jcc (GE -> L)"
        );
        assert_eq!(
            latch[n - 1].operands,
            vec![X86ISelOperand::Block(b3)],
            "exit jmp targets the exit block (layout successor, elided at encode)"
        );
    }

    /// The production branch-layout rule policy and the loop-exit kill
    /// switch. All the switches are read through `crate::env_lock`, so the
    /// thread-local override scopes below are deterministic under parallel
    /// tests (no process-env mutation — see `trust_cg_process_env`).
    #[test]
    fn x86_branch_layout_config_loop_exit_kill_switch() {
        // Default (switches absent): the three profile-independent rules are
        // ON, the refuted profile-guess fallthrough rule is OFF.
        crate::env_lock::with_env_overrides_removed(
            &[
                "TCG_NO_X86_LOOP_EXIT_LAYOUT",
                "TCG_NO_X86_COLD_TRAP_LAYOUT",
                "TCG_NO_BRANCH_LAYOUT_FALLTHROUGH",
            ],
            || {
                let c = x86_branch_layout_config();
                assert!(c.latch_rule, "latch rule is unconditionally on");
                assert!(c.cold_trap_rule, "cold-trap rule is default-on");
                assert!(c.loop_exit_rule, "loop-exit rule is default-on");
                assert!(
                    c.fallthrough_rule,
                    "fallthrough rule is DEFAULT ON since 2026-09-30 (both recorded \
                     deferral reasons refuted by measurement; b1_mispredict 1.1216 -> \
                     1.0971)"
                );
            },
        );
        // Kill switch: TCG_NO_X86_LOOP_EXIT_LAYOUT disables EXACTLY the
        // loop-exit rule (forensic rollback / A-B comparison).
        crate::env_lock::with_env_overrides(&[("TCG_NO_X86_LOOP_EXIT_LAYOUT", "1")], || {
            let c = x86_branch_layout_config();
            assert!(
                !c.loop_exit_rule,
                "kill switch must disable the loop-exit rule"
            );
            assert!(c.latch_rule, "latch rule unaffected by the kill switch");
            assert!(
                c.cold_trap_rule,
                "cold-trap rule unaffected by the kill switch"
            );
        });
    }

    /// OPT-8 production wiring, end-to-end at O1: the DEFAULT schedule (with
    /// the validator-backed `admit_x86_cc_inversion` callback) applies the
    /// LOOP-EXIT rule to a top-tested loop header — the loop-exit edge moves
    /// onto the (rarely-taken) `jcc` and the in-loop edge rides the `jmp` to
    /// the layout successor (elided at encode), so the loop pays a
    /// fall-through instead of a taken branch on nearly every iteration.
    /// With `TCG_NO_X86_LOOP_EXIT_LAYOUT` set (thread-local override), the
    /// same schedule leaves the header untouched.
    #[test]
    fn o1_schedule_inverts_top_tested_loop_header_and_honors_kill_switch() {
        let (b0, b1, b2, b3) = (Block(0), Block(1), Block(2), Block(3));
        // b0 preheader -> b1 header (`cmp; jcc B b2; jmp b3` — exit edge on
        // the JMP) -> b2 body+latch (`add; jmp b1`) -> b3 exit.
        let build = || {
            let sig = Signature {
                params: vec![],
                returns: vec![Type::I64],
            };
            let mut func = X86ISelFunction::new("loop_exit_o1".to_string(), sig);
            for b in [b0, b1, b2, b3] {
                func.ensure_block(b);
            }
            func.push_inst(
                b0,
                X86ISelInst::new(
                    X86Opcode::MovRI,
                    vec![
                        X86ISelOperand::PReg(x86_64_regs::RAX),
                        X86ISelOperand::Imm(0),
                    ],
                ),
            );
            func.push_inst(
                b0,
                X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(b1)]),
            );
            func.push_inst(
                b1,
                X86ISelInst::new(
                    X86Opcode::CmpRI,
                    vec![
                        X86ISelOperand::PReg(x86_64_regs::RAX),
                        X86ISelOperand::Imm(10),
                    ],
                ),
            );
            func.push_inst(
                b1,
                X86ISelInst::new(
                    X86Opcode::Jcc,
                    vec![
                        X86ISelOperand::CondCode(X86CondCode::B),
                        X86ISelOperand::Block(b2),
                    ],
                ),
            );
            func.push_inst(
                b1,
                X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(b3)]),
            );
            func.push_inst(
                b2,
                X86ISelInst::new(
                    X86Opcode::AddRI,
                    vec![
                        X86ISelOperand::PReg(x86_64_regs::RAX),
                        X86ISelOperand::Imm(1),
                    ],
                ),
            );
            func.push_inst(
                b2,
                X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(b1)]),
            );
            func.push_inst(b3, X86ISelInst::new(X86Opcode::Ret, vec![]));
            func.blocks.get_mut(&b0).unwrap().successors = vec![b1];
            func.blocks.get_mut(&b1).unwrap().successors = vec![b2, b3];
            func.blocks.get_mut(&b2).unwrap().successors = vec![b1];
            func
        };
        let run_o1 = |func: &mut X86ISelFunction| {
            let pipeline = X86Pipeline::new(X86PipelineConfig {
                opt_level: trust_cg_opt::OptLevel::O1,
                emit_frame: false,
                regalloc_mode: X86RegAllocMode::Simplified,
                ..X86PipelineConfig::default()
            });
            let _ = pipeline.run_x86_optimization_passes(func);
        };

        crate::env_lock::with_env_overrides_removed(&["TCG_NO_X86_LOOP_EXIT_LAYOUT"], || {
            let mut func = build();
            run_o1(&mut func);
            let header = &func.blocks[&b1].insts;
            let n = header.len();
            assert_eq!(
                header[n - 2].operands,
                vec![
                    X86ISelOperand::CondCode(X86CondCode::AE),
                    X86ISelOperand::Block(b3),
                ],
                "loop exit must ride the inverted jcc (B -> AE)"
            );
            assert_eq!(
                header[n - 1].operands,
                vec![X86ISelOperand::Block(b2)],
                "in-loop edge rides the jmp to the layout successor (elided at encode)"
            );
        });

        // Isolate the LOOP-EXIT rule's kill switch from the FALLTHROUGH rule, which became
        // DEFAULT ON on 2026-09-30 and independently inverts this same header (its own
        // trigger is "T is the layout successor", which this fixture also satisfies).
        // Without the second override the assertion below would be testing the wrong rule:
        // the header would still invert, via fallthrough, and the loop-exit kill switch
        // would look broken when it is not.
        crate::env_lock::with_env_overrides(
            &[
                ("TCG_NO_X86_LOOP_EXIT_LAYOUT", "1"),
                ("TCG_NO_BRANCH_LAYOUT_FALLTHROUGH", "1"),
            ],
            || {
                let mut func = build();
                run_o1(&mut func);
                let header = &func.blocks[&b1].insts;
                let n = header.len();
                assert_eq!(
                    header[n - 2].operands,
                    vec![
                        X86ISelOperand::CondCode(X86CondCode::B),
                        X86ISelOperand::Block(b2),
                    ],
                    "kill switch: header jcc must be untouched"
                );
                assert_eq!(
                    header[n - 1].operands,
                    vec![X86ISelOperand::Block(b3)],
                    "kill switch: header jmp must be untouched"
                );
            },
        );
    }

    /// The cold-arm sink rule (rule 4) is OPT-IN for its soak:
    /// `TCG_X86_COLD_ARM_SINK` absent => OFF (and the three default-on rules
    /// unaffected); present => ON (and again nothing else moves). Read
    /// through `crate::env_lock` — thread-local override scopes, no
    /// process-env mutation.
    #[test]
    fn x86_branch_layout_config_cold_arm_sink_opt_in() {
        crate::env_lock::with_env_overrides_removed(&["TCG_X86_COLD_ARM_SINK"], || {
            let c = x86_branch_layout_config();
            assert!(
                !c.cold_arm_sink_rule,
                "cold-arm sinking must be OFF without the opt-in"
            );
            assert!(c.latch_rule, "latch rule unaffected");
            assert!(c.cold_trap_rule, "cold-trap rule unaffected");
            assert!(c.loop_exit_rule, "loop-exit rule unaffected");
            assert!(
                c.fallthrough_rule,
                "fallthrough rule stays DEFAULT ON, unaffected by this opt-in"
            );
        });
        crate::env_lock::with_env_overrides(&[("TCG_X86_COLD_ARM_SINK", "1")], || {
            let c = x86_branch_layout_config();
            assert!(
                c.cold_arm_sink_rule,
                "TCG_X86_COLD_ARM_SINK=1 must enable the sink rule"
            );
            assert!(c.latch_rule, "latch rule unaffected by the opt-in");
            assert!(c.cold_trap_rule, "cold-trap rule unaffected by the opt-in");
            assert!(c.loop_exit_rule, "loop-exit rule unaffected by the opt-in");
            assert!(
                c.fallthrough_rule,
                "the fallthrough rule is default-on and unaffected by this opt-in"
            );
        });
    }

    /// Rule 4 end-to-end at O1: with `TCG_X86_COLD_ARM_SINK=1` the DEFAULT
    /// schedule sinks an intra-loop diamond's call arm out of the loop span —
    /// a pure `block_order` permutation (the hard-terminated latch needs no
    /// seam jmp) after which the diamond's `jmp <kept arm>` targets the
    /// layout successor (elided at encode: the hot, call-free arm falls
    /// through every iteration). The permuted function must still satisfy
    /// the pipeline layout validator. Without the opt-in the same schedule
    /// leaves the layout untouched (kill-switch isolation).
    #[test]
    fn o1_schedule_sinks_cold_call_arm_only_when_opted_in() {
        let (b0, b1, b2, b3, b4, b5) = (Block(0), Block(1), Block(2), Block(3), Block(4), Block(5));
        // b0 preheader -> b1 diamond entry (`cmp; jcc E b2; jmp b3`) ->
        // b2 COLD call arm (add; call; add; jmp b4) -> b3 hot arm (add;
        // jmp b4) -> b4 join + rotated latch (`cmp; jcc L b1; jmp b5`) ->
        // b5 exit. PReg operands throughout: fixed-register contracts are
        // ABI-observable, so the O1 cleanups (LICM/copy-prop/peephole/DCE)
        // leave the arm's four instructions in place for branch layout.
        let build = || {
            let sig = Signature {
                params: vec![],
                returns: vec![Type::I64],
            };
            let mut func = X86ISelFunction::new("cold_arm_sink_o1".to_string(), sig);
            for b in [b0, b1, b2, b3, b4, b5] {
                func.ensure_block(b);
            }
            func.push_inst(
                b0,
                X86ISelInst::new(
                    X86Opcode::MovRI,
                    vec![
                        X86ISelOperand::PReg(x86_64_regs::RAX),
                        X86ISelOperand::Imm(0),
                    ],
                ),
            );
            func.push_inst(
                b0,
                X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(b1)]),
            );
            func.push_inst(
                b1,
                X86ISelInst::new(
                    X86Opcode::CmpRI,
                    vec![
                        X86ISelOperand::PReg(x86_64_regs::RAX),
                        X86ISelOperand::Imm(3),
                    ],
                ),
            );
            func.push_inst(
                b1,
                X86ISelInst::new(
                    X86Opcode::Jcc,
                    vec![
                        X86ISelOperand::CondCode(X86CondCode::E),
                        X86ISelOperand::Block(b2),
                    ],
                ),
            );
            func.push_inst(
                b1,
                X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(b3)]),
            );
            func.push_inst(
                b2,
                X86ISelInst::new(
                    X86Opcode::AddRI,
                    vec![
                        X86ISelOperand::PReg(x86_64_regs::RAX),
                        X86ISelOperand::Imm(2),
                    ],
                ),
            );
            func.push_inst(b2, X86ISelInst::new(X86Opcode::Call, vec![]));
            func.push_inst(
                b2,
                X86ISelInst::new(
                    X86Opcode::AddRI,
                    vec![
                        X86ISelOperand::PReg(x86_64_regs::RAX),
                        X86ISelOperand::Imm(2),
                    ],
                ),
            );
            func.push_inst(
                b2,
                X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(b4)]),
            );
            func.push_inst(
                b3,
                X86ISelInst::new(
                    X86Opcode::AddRI,
                    vec![
                        X86ISelOperand::PReg(x86_64_regs::RAX),
                        X86ISelOperand::Imm(1),
                    ],
                ),
            );
            func.push_inst(
                b3,
                X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(b4)]),
            );
            func.push_inst(
                b4,
                X86ISelInst::new(
                    X86Opcode::CmpRI,
                    vec![
                        X86ISelOperand::PReg(x86_64_regs::RAX),
                        X86ISelOperand::Imm(10),
                    ],
                ),
            );
            func.push_inst(
                b4,
                X86ISelInst::new(
                    X86Opcode::Jcc,
                    vec![
                        X86ISelOperand::CondCode(X86CondCode::L),
                        X86ISelOperand::Block(b1),
                    ],
                ),
            );
            func.push_inst(
                b4,
                X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(b5)]),
            );
            func.push_inst(b5, X86ISelInst::new(X86Opcode::Ret, vec![]));
            func.blocks.get_mut(&b0).unwrap().successors = vec![b1];
            func.blocks.get_mut(&b1).unwrap().successors = vec![b2, b3];
            func.blocks.get_mut(&b2).unwrap().successors = vec![b4];
            func.blocks.get_mut(&b3).unwrap().successors = vec![b4];
            func.blocks.get_mut(&b4).unwrap().successors = vec![b1, b5];
            func
        };
        let run_o1 = |func: &mut X86ISelFunction| {
            let pipeline = X86Pipeline::new(X86PipelineConfig {
                opt_level: trust_cg_opt::OptLevel::O1,
                emit_frame: false,
                regalloc_mode: X86RegAllocMode::Simplified,
                ..X86PipelineConfig::default()
            });
            let _ = pipeline.run_x86_optimization_passes(func);
        };

        // Isolate the COLD-ARM SINK rule from the FALLTHROUGH rule (default ON since
        // 2026-09-30), which also mutates `block_order` on this fixture. The expected order
        // below is the sink rule's own contribution.
        crate::env_lock::with_env_overrides(
            &[
                ("TCG_X86_COLD_ARM_SINK", "1"),
                ("TCG_NO_BRANCH_LAYOUT_FALLTHROUGH", "1"),
            ],
            || {
                let mut func = build();
                run_o1(&mut func);
                assert_eq!(
                    func.block_order,
                    vec![b0, b1, b3, b4, b2, b5],
                    "opted in: the call arm must sink past the loop span"
                );
                // The diamond terminators are untouched (no cc inversion — the
                // sink is layout-only): still `jcc E b2; jmp b3`, with b3 now the
                // layout successor so the jmp elides at encode.
                let entry = &func.blocks[&b1].insts;
                let n = entry.len();
                assert_eq!(
                    entry[n - 2].operands,
                    vec![
                        X86ISelOperand::CondCode(X86CondCode::E),
                        X86ISelOperand::Block(b2),
                    ],
                    "sink must not invert or retarget the jcc"
                );
                assert_eq!(
                    entry[n - 1].operands,
                    vec![X86ISelOperand::Block(b3)],
                    "sink must not retarget the jmp"
                );
                // The permuted layout satisfies the pipeline validator the
                // sink's self-check mirrors.
                validate_x86_function_layout(&func)
                    .expect("post-sink layout must pass the pipeline layout validator");
            },
        );

        crate::env_lock::with_env_overrides_removed(&["TCG_X86_COLD_ARM_SINK"], || {
            let mut func = build();
            run_o1(&mut func);
            assert_eq!(
                func.block_order,
                vec![b0, b1, b2, b3, b4, b5],
                "without the opt-in the layout must be untouched"
            );
        });
    }

    /// The production admission callback: every true hardware complement is
    /// admitted (validator-proven + chain-checked); any mismatched pair is
    /// refused outright.
    #[test]
    fn admit_x86_cc_inversion_accepts_complements_and_refuses_mismatches() {
        use trust_cg_ir::x86_64_ops::X86CondCode::*;
        for cc in [O, NO, B, AE, E, NE, BE, A, S, NS, P, NP, L, GE, LE, G] {
            assert!(
                admit_x86_cc_inversion(cc, cc.invert()),
                "{cc:?} -> {:?} must be admitted",
                cc.invert()
            );
            assert!(
                !admit_x86_cc_inversion(cc, cc),
                "{cc:?} -> {cc:?} (no inversion) must be refused"
            );
        }
    }

    /// The production reconstruction-opcode admission callback: the four
    /// Stage-1 RMW opcodes AND the variable-count rotate are admitted because
    /// (and ONLY because) their representative reconstruction obligations
    /// discharge `Valid` — the same criterion by which the coverage-gate
    /// inventory marks their rows covered (an inventory, not instruction
    /// credit, since E0.2). Anything else is refused outright (fail-closed: no
    /// reconstruction arm, no emission).
    #[test]
    fn admit_x86_reconstructed_opcode_admits_only_reconstruction_covered_opcodes() {
        for op in [
            X86Opcode::XorMR,
            X86Opcode::AddMR,
            X86Opcode::XorMRSib,
            X86Opcode::AddMRSib,
            // The rotate-arc Stage-2 peephole rides the SAME callback: RolRCl
            // must stay admitted or the variable-rotate collapse dies silently.
            X86Opcode::RolRCl,
        ] {
            assert!(
                admit_x86_reconstructed_opcode(op),
                "{op:?} lost its Stage-1 reconstruction discharge"
            );
        }
        // Non-reconstructable opcodes are refused (fail-closed), and the
        // memoized second query keeps the admitted verdict.
        assert!(!admit_x86_reconstructed_opcode(X86Opcode::Ret));
        assert!(admit_x86_reconstructed_opcode(X86Opcode::XorMRSib));
    }

    #[test]
    fn x86_opt_level_o0_preserves_o2_rewrites_isel_shape() {
        let mut o0_func = optimizable_add_ri_func("x86_opt_level_o0");
        let mut o2_func = o0_func.clone();
        let o0_pipeline = X86Pipeline::new(X86PipelineConfig {
            opt_level: trust_cg_opt::OptLevel::O0,
            ..X86PipelineConfig::default()
        });
        let o2_pipeline = X86Pipeline::new(X86PipelineConfig {
            opt_level: trust_cg_opt::OptLevel::O2,
            ..X86PipelineConfig::default()
        });

        let o0_stats = o0_pipeline.run_x86_optimization_passes(&mut o0_func);
        let o2_stats = o2_pipeline.run_x86_optimization_passes(&mut o2_func);

        assert_eq!(o0_stats.total_pass_runs(), 0);
        // Twenty production pass runs, including the post-SROA vectorizer
        // and default-on xorshift demanded bits after peephole/BCE, before DCE.
        // Keep this exact count alongside the O2/Os/O3 schedule pin above.
        assert_eq!(o2_stats.total_pass_runs(), 20);
        assert!(
            entry_opcodes(&o0_func).contains(&X86Opcode::AddRI),
            "O0 must preserve the optimizable AddRI before regalloc"
        );
        assert_eq!(
            entry_opcodes(&o2_func),
            vec![
                X86Opcode::MovRI,
                X86Opcode::CmpRI,
                X86Opcode::MovRR,
                X86Opcode::Ret,
            ],
            "O2 should fold the AddRI and let DCE remove the now-dead source"
        );
    }

    #[test]
    fn x86_opt_level_o3_runs_production_schedule_to_bounded_fixpoint() {
        let mut func = optimizable_add_ri_func("x86_opt_level_o3");
        let pipeline = X86Pipeline::new(X86PipelineConfig {
            opt_level: trust_cg_opt::OptLevel::O3,
            ..X86PipelineConfig::default()
        });

        let stats = pipeline.run_x86_optimization_passes(&mut func);

        assert!(stats.iterations <= TCG_X86_O3_FIXPOINT_MAX_ITERATIONS);
        assert!(
            stats.total_pass_runs()
                >= X86Pipeline::x86_o2_pass_manager(pipeline.config.call_abi).num_passes(),
            "O3 should run at least one production-order iteration"
        );
        assert_eq!(
            stats
                .runs
                .iter()
                .map(|(name, _)| name.as_str())
                .collect::<Vec<_>>(),
            vec![
                "x86-vectorize",
                "x86-sroa",
                // The SECOND vectorizer run, immediately after SROA, is part of the
                // DEFAULT schedule since 2026-09-29: it is where an owning-container
                // reduction first has a recognisable shape (slice temp promoted, the
                // peephole not yet having re-spelled the header test or the element
                // address), and it is what takes h1_vec_push_sum from 2.4890x to
                // 1.0023x LLVM. `no-vectorize-post-sroa` is the forensic opt-out.
                "x86-vectorize",
                "x86-licm",
                "x86-strength-reduce",
                "x86-loop-unroll",
                "x86-const-fold",
                "x86-const-guard-elim",
                "x86-block-merge",
                "x86-slot-forward",
                "x86-copy-prop",
                "x86-cse",
                "x86-peephole",
                "x86-bounds-check-elim",
                // DEFAULT ON since 2026-10-01: b1_mispredict 1.0959 -> 1.0260,
                // ~60x its noise floor. Runs AFTER the peephole because `BtRI`
                // — the one-bit consumer it targets — is SYNTHESIZED there and
                // does not exist in ISel output.
                "x86-xorshift-demanded-bits",
                "x86-dce",
                "x86-loop-rotate",
                "x86-cmov-swap",
                "x86-if-convert",
                "x86-branch-layout",
            ]
        );
    }

    #[test]
    fn compile_function_runs_default_x86_optimization_passes() {
        let pipeline = raw_no_frame_x86_pipeline();
        let func = optimizable_add_ri_func("default_x86_opts");

        let mut expected = minimal_func("default_x86_opts");
        expected.next_vreg = 2;
        expected.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::MovRI,
                vec![test_vreg_op(1), X86ISelOperand::Imm(30)],
            ),
        );
        expected.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::CmpRI,
                vec![test_vreg_op(1), X86ISelOperand::Imm(30)],
            ),
        );
        expected.push_inst(
            Block(0),
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![X86ISelOperand::PReg(RAX), test_vreg_op(1)],
            ),
        );
        expected.push_inst(Block(0), X86ISelInst::new(X86Opcode::Ret, vec![]));

        let default_bytes = pipeline.compile_function(&func).unwrap();
        let expected_bytes = pipeline
            .compile_function_after_x86_passes(&expected)
            .unwrap();
        let unoptimized_bytes = pipeline.compile_function_after_x86_passes(&func).unwrap();

        assert_eq!(default_bytes, expected_bytes);
        assert_ne!(unoptimized_bytes, expected_bytes);
    }

