    #[test]
    fn test_windows_coff_unwind_rejects_dynamic_xmm_frame() {
        let metadata = X86FrameMetadata {
            callee_saved: Vec::new(),
            callee_saved_xmms: vec![x86_64_regs::XMM6],
            xmm_save_offsets: vec![-16],
            frame_size: 16,
            has_dynamic_alloc: true,
        };

        match x86_64_coff_unwind_info(&metadata) {
            Err(X86PipelineError::WindowsCoffUnwindMetadataRequired { reason, .. }) => {
                assert!(reason.contains("callee-saved XMM"));
                assert!(reason.contains("dynamic stack allocation"));
            }
            other => panic!("expected dynamic Windows XMM frame to fail closed, got {other:?}"),
        }
    }

