    #[test]
    fn test_compile_trust_ir_v4i32_lane_insert_stack_materialization_encodes() {
        let mut func = LirFunction::new(
            "v4i32_lane_insert_stack_materialization",
            Signature {
                params: vec![Type::V128, Type::I32],
                returns: vec![Type::V128],
            },
        );
        let entry = Block(0);
        func.entry_block = entry;
        func.block_order.push(entry);
        func.stack_slots.push(StackSlotInfo::new(16, 16));
        func.blocks.insert(
            entry,
            BasicBlock {
                params: vec![],
                instructions: vec![
                    Instruction {
                        opcode: Opcode::StackAddr { slot: 0 },
                        args: vec![],
                        results: vec![Value(2)],
                    },
                    Instruction {
                        opcode: Opcode::Store {
                            ty: Type::V128,
                            align: None,
                        },
                        args: vec![Value(0), Value(2)],
                        results: vec![],
                    },
                    Instruction {
                        opcode: Opcode::Iconst {
                            ty: Type::I64,
                            imm: 3,
                        },
                        args: vec![],
                        results: vec![Value(3)],
                    },
                    Instruction {
                        opcode: Opcode::ArrayGep { elem_ty: Type::I32 },
                        args: vec![Value(2), Value(3)],
                        results: vec![Value(4)],
                    },
                    Instruction {
                        opcode: Opcode::Store {
                            ty: Type::I32,
                            align: None,
                        },
                        args: vec![Value(1), Value(4)],
                        results: vec![],
                    },
                    Instruction {
                        opcode: Opcode::Load {
                            ty: Type::V128,
                            align: None,
                        },
                        args: vec![Value(2)],
                        results: vec![Value(5)],
                    },
                    Instruction {
                        opcode: Opcode::Return,
                        args: vec![Value(5)],
                        results: vec![],
                    },
                ],
                source_locs: vec![],
            },
        );

        let pipeline = X86Pipeline::new(X86PipelineConfig {
            emit_frame: true,
            ..X86PipelineConfig::default()
        });
        let code = pipeline.compile_trust_ir_function(&func).unwrap();
        assert!(!code.is_empty());
        assert_eq!(*code.last().unwrap(), 0xC3);
        assert!(
            code.windows(3).any(|bytes| bytes == [0x66, 0x0F, 0x62]),
            "expected encoded PUNPCKLDQ lane pair assembly after stack materialization fusion: {code:02x?}"
        );
        assert!(
            code.windows(3).any(|bytes| bytes == [0x66, 0x0F, 0x6C]),
            "expected encoded PUNPCKLQDQ lane pair join after stack materialization fusion: {code:02x?}"
        );
        assert!(
            !code
                .windows(4)
                .any(|bytes| bytes == [0x66, 0x0F, 0x3A, 0x22]),
            "fused lane insertion should not encode SSE4.1 PINSRD: {code:02x?}"
        );
        assert!(
            !code.windows(2).any(|bytes| bytes == [0x0F, 0x7F])
                && !code.windows(2).any(|bytes| bytes == [0xF3, 0x0F]),
            "fused lane insertion should not leave vector stack stores or unaligned moves: {code:02x?}"
        );
    }

    fn v4i32_all_bits_const_store_lir(name: &str, lane_imm: i64) -> LirFunction {
        let mut func = LirFunction::new(
            name,
            Signature {
                params: vec![Type::I64],
                returns: vec![],
            },
        );
        let entry = Block(0);
        func.entry_block = entry;
        func.block_order.push(entry);
        func.stack_slots.push(StackSlotInfo::new(16, 16));

        let mut instructions = vec![Instruction {
            opcode: Opcode::StackAddr { slot: 0 },
            args: vec![],
            results: vec![Value(1)],
        }];
        let mut next_value = 2;
        for lane in 0..4 {
            let lane_idx = Value(next_value);
            let lane_ptr = Value(next_value + 1);
            let lane_value = Value(next_value + 2);
            next_value += 3;
            instructions.push(Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I64,
                    imm: lane,
                },
                args: vec![],
                results: vec![lane_idx],
            });
            instructions.push(Instruction {
                opcode: Opcode::ArrayGep { elem_ty: Type::I32 },
                args: vec![Value(1), lane_idx],
                results: vec![lane_ptr],
            });
            instructions.push(Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I32,
                    imm: lane_imm,
                },
                args: vec![],
                results: vec![lane_value],
            });
            instructions.push(Instruction {
                opcode: Opcode::Store {
                    ty: Type::I32,
                    align: None,
                },
                args: vec![lane_value, lane_ptr],
                results: vec![],
            });
        }
        instructions.push(Instruction {
            opcode: Opcode::Load {
                ty: Type::V128,
                align: None,
            },
            args: vec![Value(1)],
            results: vec![Value(next_value)],
        });
        instructions.push(Instruction {
            opcode: Opcode::Store {
                ty: Type::V128,
                align: None,
            },
            args: vec![Value(next_value), Value(0)],
            results: vec![],
        });
        instructions.push(Instruction {
            opcode: Opcode::Return,
            args: vec![],
            results: vec![],
        });

        func.blocks.insert(
            entry,
            BasicBlock {
                params: vec![],
                instructions,
                source_locs: vec![],
            },
        );
        func
    }

    #[test]
    fn test_compile_trust_ir_v4i32_all_bits_constants_encode_directly() {
        for (name, lane_imm, expected_opcode, unexpected_opcode) in [
            ("zero", 0, [0x66, 0x0F, 0xEF], [0x66, 0x0F, 0x76]),
            ("all_ones", -1, [0x66, 0x0F, 0x76], [0x66, 0x0F, 0xEF]),
        ] {
            let func = v4i32_all_bits_const_store_lir(
                &format!("v4i32_{name}_const_store_direct"),
                lane_imm,
            );
            let pipeline = X86Pipeline::new(X86PipelineConfig {
                emit_frame: true,
                ..X86PipelineConfig::default()
            });
            let code = pipeline.compile_trust_ir_function(&func).unwrap();

            assert!(!code.is_empty(), "{name}");
            assert_eq!(*code.last().unwrap(), 0xC3, "{name}");
            assert!(
                code.windows(expected_opcode.len())
                    .any(|bytes| bytes == expected_opcode),
                "{name} should encode direct vector constant opcode {expected_opcode:02x?}: {code:02x?}"
            );
            assert!(
                !code
                    .windows(unexpected_opcode.len())
                    .any(|bytes| bytes == unexpected_opcode),
                "{name} should not encode opposite vector constant opcode {unexpected_opcode:02x?}: {code:02x?}"
            );
        }
    }

