    #[test]
    fn test_module_macho_eh_function_emits_zplr_fde_and_lsda_relocs() {
        // EH Lane 2 Step 4: an EH function must emit a zPLR __eh_frame (CIE with
        // personality + FDE-with-LSDA) whose relocations wire the personality
        // (GOT), the FDE PC-begin (subtractor pair), and the FDE LSDA (subtractor
        // pair). compile_module SUCCEEDING is itself the ENC-EHDC decode-check
        // round-trip proof: verify_eh_frame_roundtrip runs inside the emitter and
        // fails the compile if the emitted zPLR CIE/FDE does not decode back to
        // the emitter intent.
        let func = build_x86_eh_test_function("eh_lane2_step4");
        let pipeline = X86Pipeline::new(X86PipelineConfig {
            emit_frame: true,
            output_format: X86OutputFormat::MachO,
            ..X86PipelineConfig::default()
        });

        let obj = pipeline
            .compile_module(&[func])
            .expect("EH object must emit (decode-check must round-trip)");
        assert_eq!(read_u32(&obj, 0), 0xFEEDFACF);

        // Both the LSDA section and the eh_frame must be present.
        assert!(find_macho_section(&obj, b"__gcc_except_tab").is_some());
        let eh_frame = find_macho_section(&obj, b"__eh_frame").expect("missing __eh_frame");
        assert!(eh_frame.size > 0);

        // The shared CIE must carry the zPLR augmentation (personality + LSDA).
        assert_eq!(
            &obj[eh_frame.offset + 9..eh_frame.offset + 14],
            b"zPLR\0",
            "EH CIE must be zPLR"
        );

        // EH Lane 3: ld64's x86-64 __eh_frame reader re-synthesizes __unwind_info
        // from SELF-RELATIVE (baked) FDE PC-begin / LSDA pointers and does NOT
        // consume subtractor pairs for them (that made ld fail "symbol index out
        // of range"). So the ONLY __eh_frame relocation is the personality GOT
        // pointer — no SUBTRACTOR / UNSIGNED pairs. Matches clang.
        assert_eq!(
            eh_frame.reloc_count, 1,
            "x86-64 zPLR __eh_frame carries exactly one relocation: the personality GOT"
        );

        // Parse the single relocation (8 bytes): r_address (u32), r_word1 (u32).
        let base = eh_frame.reloc_offset;
        let got_address = read_u32(&obj, base);
        let r_word1 = read_u32(&obj, base + 4);
        let kind = (r_word1 >> 28) & 0xF;
        let pc_relative = (r_word1 >> 24) & 1;
        let length = (r_word1 >> 25) & 3;
        assert_eq!(
            kind,
            crate::macho::constants::X86_64_RELOC_GOT,
            "the sole __eh_frame reloc is the personality GOT"
        );
        assert_eq!(pc_relative, 1, "personality GOT reloc is pc-relative");
        assert_eq!(length, 2, "personality GOT reloc is 4-byte");

        // Encoding and reloc MUST agree: the personality encoding byte
        // immediately preceding the GOT-relocated pointer slot is 0x9b
        // (DW_EH_PE_indirect|pcrel|sdata4).
        let got_address = got_address as usize;
        assert_eq!(
            obj[eh_frame.offset + got_address - 1],
            0x9b,
            "personality encoding must be 0x9b to match the GOT reloc"
        );
        // The personality slot carries the baked `+4` addend (X86_64_RELOC_GOT is
        // pcrel-biased by the field END, DW_EH_PE_pcrel is field-START relative).
        assert_eq!(
            read_u32(&obj, eh_frame.offset + got_address),
            4,
            "personality slot must carry the +4 field-end pcrel-bias addend"
        );

        // The FDE PC-begin / LSDA pointers are pcrel|absptr (8-byte, encoding
        // 0x10) — no sdata4, no subtractor pairs.
        let cie_len = read_u32(&obj, eh_frame.offset) as usize;
        let fde_off = eh_frame.offset + 4 + cie_len; // FDE follows the CIE
        // FDE: length(4) + CIE-ptr(4) then the 8-byte PC-begin (nonzero, baked).
        let pc_begin = read_u32(&obj, fde_off + 8);
        let pc_begin_hi = read_u32(&obj, fde_off + 12);
        assert!(
            !(pc_begin == 0 && pc_begin_hi == 0),
            "FDE PC-begin must be a baked (nonzero) self-relative 8-byte pointer"
        );
    }

