    #[test]
    fn test_compile_trust_ir_windows_x64_call_uses_fixed_frame_shadow_space() {
        let mut func = LirFunction::new(
            "windows_shadow_call",
            Signature {
                params: vec![],
                returns: vec![],
            },
        );
        let entry = Block(0);
        func.entry_block = entry;
        func.block_order.push(entry);
        func.blocks.insert(
            entry,
            BasicBlock {
                params: vec![],
                instructions: vec![
                    Instruction {
                        opcode: Opcode::Call {
                            name: "target".to_string(),
                            binding: Default::default(),
                        },
                        args: vec![],
                        results: vec![],
                    },
                    Instruction {
                        opcode: Opcode::Return,
                        args: vec![],
                        results: vec![],
                    },
                ],
                source_locs: vec![],
            },
        );

        let pipeline = X86Pipeline::new(X86PipelineConfig {
            emit_elf: false,
            emit_frame: true,
            opt_level: trust_cg_opt::OptLevel::O0,
            regalloc_mode: X86RegAllocMode::Simplified,
            call_abi: X86CallAbi::WindowsX64,
            ..X86PipelineConfig::default()
        });

        let code = pipeline
            .compile_trust_ir_function_emitting_call_fixups(&func)
            .unwrap();
        let call_offset = code
            .iter()
            .position(|byte| *byte == 0xE8)
            .expect("Windows x64 call lowering should emit CALL rel32");

        assert!(
            code.starts_with(&[0x55, 0x48, 0x89, 0xE5, 0x48, 0x83, 0xEC, 0x20])
                || code.starts_with(&[
                    0x55, 0x48, 0x89, 0xE5, 0x48, 0x81, 0xEC, 0x20, 0x00, 0x00, 0x00
                ]),
            "Windows x64 calls must reserve shadow space in the prologue: {code:02X?}"
        );
        assert!(call_offset > 0);
    }

    #[test]
    fn test_compile_trust_ir_windows_x64_emit_frame_false_rejects_non_leaf() {
        let mut func = LirFunction::new(
            "windows_frameless_non_leaf",
            Signature {
                params: vec![],
                returns: vec![],
            },
        );
        let entry = Block(0);
        func.entry_block = entry;
        func.block_order.push(entry);
        func.blocks.insert(
            entry,
            BasicBlock {
                params: vec![],
                instructions: vec![
                    Instruction {
                        opcode: Opcode::Call {
                            name: "target".to_string(),
                            binding: Default::default(),
                        },
                        args: vec![],
                        results: vec![],
                    },
                    Instruction {
                        opcode: Opcode::Return,
                        args: vec![],
                        results: vec![],
                    },
                ],
                source_locs: vec![],
            },
        );

        let pipeline = X86Pipeline::new(X86PipelineConfig {
            emit_elf: false,
            emit_frame: false,
            opt_level: trust_cg_opt::OptLevel::O0,
            regalloc_mode: X86RegAllocMode::Simplified,
            call_abi: X86CallAbi::WindowsX64,
            ..X86PipelineConfig::default()
        });

        let err = pipeline.compile_trust_ir_function(&func).unwrap_err();

        match err {
            X86PipelineError::FrameLowering(msg) => {
                assert!(msg.contains("Windows x64 calls require"));
                assert!(msg.contains("emit_frame=false"));
            }
            other => panic!("expected Windows frameless non-leaf rejection, got {other:?}"),
        }
    }

    #[test]
    fn test_windows_x64_xmm_allocation_records_nonvolatile_xmms() {
        use trust_cg_ir::x86_64_regs::{
            XMM0, XMM1, XMM2, XMM3, XMM4, XMM5, XMM6, XMM7, XMM8, XMM9, XMM10, XMM11, XMM12, XMM13,
            XMM14, XMM15,
        };

        let mut func = minimal_func("windows_xmm_alloc");
        func.next_vreg = 16;
        for idx in 0..16 {
            let vreg = VReg::new(idx, RegClass::Fpr64);
            func.push_inst(
                Block(0),
                X86ISelInst::new(
                    X86Opcode::MovsdRR,
                    vec![X86ISelOperand::VReg(vreg), X86ISelOperand::PReg(XMM0)],
                ),
            );
        }
        func.push_inst(Block(0), X86ISelInst::new(X86Opcode::Ret, vec![]));

        let assignment = X86RegAssignment::assign_with_abi(&func, X86CallAbi::WindowsX64).unwrap();
        let allocated = assignment
            .allocation
            .values()
            .copied()
            .collect::<HashSet<_>>();

        assert_eq!(allocated.len(), 16);
        for reg in [
            XMM0, XMM1, XMM2, XMM3, XMM4, XMM5, XMM6, XMM7, XMM8, XMM9, XMM10, XMM11, XMM12, XMM13,
            XMM14, XMM15,
        ] {
            assert!(
                allocated.contains(&reg),
                "Windows x64 allocation should allow full XMM register file when preservation is tracked: {:?}",
                reg
            );
        }
        assert_eq!(
            assignment.used_callee_saved_xmms,
            vec![
                XMM6, XMM7, XMM8, XMM9, XMM10, XMM11, XMM12, XMM13, XMM14, XMM15
            ]
        );
        assert!(assignment.used_callee_saved.is_empty());
    }

    #[test]
    fn test_windows_x64_xmm_callee_saved_prologue_epilogue() {
        use trust_cg_ir::x86_64_regs::{XMM6, XMM15};

        let func = minimal_func("windows_xmm_frame");
        let layout = compute_x86_stack_frame_layout(&func, 0, 2).unwrap();

        assert_eq!(layout.xmm_save_offsets.len(), 2);
        assert!(layout.frame_size >= 32);

        let prologue = generate_prologue(
            &[],
            &[XMM6, XMM15],
            &layout.xmm_save_offsets,
            layout.frame_size,
        );
        assert!(
            prologue
                .iter()
                .any(|inst| inst.opcode == X86Opcode::MovdquMR),
            "Windows XMM callee-saves must be stored with 128-bit MOVDQU"
        );

        let epilogue = generate_epilogue(
            &[],
            &[XMM6, XMM15],
            &layout.xmm_save_offsets,
            layout.frame_size,
            false,
        );
        assert!(
            epilogue
                .iter()
                .any(|inst| inst.opcode == X86Opcode::MovdquRM),
            "Windows XMM callee-saves must be restored with 128-bit MOVDQU"
        );
    }

