    #[test]
    fn volatile_store_operands_are_uses_and_never_defs() {
        for (opcode, value) in [
            (X86Opcode::VolatileMovMR8, X86ISelOperand::PReg(R10B)),
            (X86Opcode::VolatileMovMR16, X86ISelOperand::PReg(R10W)),
            (X86Opcode::VolatileMovMR32, X86ISelOperand::PReg(R10D)),
            (X86Opcode::VolatileMovMR, X86ISelOperand::PReg(R10)),
            (X86Opcode::VolatileMovssMR, X86ISelOperand::PReg(XMM0)),
            (X86Opcode::VolatileMovsdMR, X86ISelOperand::PReg(XMM0)),
            (X86Opcode::VolatileMovdquMR, X86ISelOperand::PReg(XMM0)),
            (X86Opcode::VolatileMovdqaMR, X86ISelOperand::PReg(XMM0)),
        ] {
            let inst = X86ISelInst::new(
                opcode,
                vec![
                    X86ISelOperand::MemAddr {
                        base: Box::new(X86ISelOperand::PReg(RBP)),
                        disp: -16,
                    },
                    value,
                ],
            );

            assert!(!opcode_has_def(opcode), "{opcode:?}");
            let address = x86_operand_access(&inst, 0);
            assert!(address.is_use, "{opcode:?} address must be a use");
            assert!(!address.is_def, "{opcode:?} address must not be a def");
            let stored_value = x86_operand_access(&inst, 1);
            assert!(stored_value.is_use, "{opcode:?} value must be a use");
            assert!(
                !stored_value.is_def,
                "{opcode:?} stored value must not be a def"
            );
        }
    }

    #[test]
    fn volatile_store_forms_initialize_spill_slots() {
        let rbp_mem = |disp: i32| X86ISelOperand::MemAddr {
            base: Box::new(X86ISelOperand::PReg(RBP)),
            disp,
        };
        let spill_disps: HashSet<i32> = [-160].into_iter().collect();

        for (opcode, value) in [
            (X86Opcode::VolatileMovMR8, X86ISelOperand::PReg(R10B)),
            (X86Opcode::VolatileMovMR16, X86ISelOperand::PReg(R10W)),
            (X86Opcode::VolatileMovMR32, X86ISelOperand::PReg(R10D)),
            (X86Opcode::VolatileMovMR, X86ISelOperand::PReg(R10)),
            (X86Opcode::VolatileMovssMR, X86ISelOperand::PReg(XMM0)),
            (X86Opcode::VolatileMovsdMR, X86ISelOperand::PReg(XMM0)),
            (X86Opcode::VolatileMovdquMR, X86ISelOperand::PReg(XMM0)),
            (X86Opcode::VolatileMovdqaMR, X86ISelOperand::PReg(XMM0)),
        ] {
            let mut func = minimal_func(&format!("volatile_spill_store_{opcode:?}"));
            func.push_inst(
                Block(0),
                X86ISelInst::new(opcode, vec![rbp_mem(-160), value]),
            );
            assert_eq!(
                x86_uninitialized_spill_read(&func, &spill_disps),
                None,
                "{opcode:?} must classify its spill memory operand as a write"
            );
        }
    }

    fn dead_volatile_load_function(name: &str) -> (X86ISelFunction, Vec<VReg>) {
        let mut func = minimal_func(name);
        let dead_defs = vec![
            VReg::new(100, RegClass::Gpr32),
            VReg::new(101, RegClass::Gpr64),
            VReg::new(102, RegClass::Fpr32),
            VReg::new(103, RegClass::Fpr64),
            VReg::new(104, RegClass::Fpr128),
        ];
        for (opcode, dst) in [
            (X86Opcode::VolatileMovRM32, dead_defs[0]),
            (X86Opcode::VolatileMovRM, dead_defs[1]),
            (X86Opcode::VolatileMovssRM, dead_defs[2]),
            (X86Opcode::VolatileMovsdRM, dead_defs[3]),
            (X86Opcode::VolatileMovdquRM, dead_defs[4]),
        ] {
            func.push_inst(
                Block(0),
                X86ISelInst::new(
                    opcode,
                    vec![
                        X86ISelOperand::VReg(dst),
                        X86ISelOperand::MemAddr {
                            base: Box::new(X86ISelOperand::PReg(RSP)),
                            disp: 0,
                        },
                    ],
                ),
            );
        }
        func.push_inst(Block(0), X86ISelInst::new(X86Opcode::Ret, Vec::new()));
        (func, dead_defs)
    }

    #[test]
    fn full_regalloc_binds_dead_volatile_loads_to_reserved_scratch_registers() {
        let (func, dead_defs) = dead_volatile_load_function("dead_volatile_bind");
        let mut allocation = HashMap::new();
        bind_x86_dead_volatile_load_defs(&func, &mut allocation, X86CallAbi::SystemV).unwrap();

        assert_eq!(allocation[&dead_defs[0]], R10D);
        assert_eq!(allocation[&dead_defs[1]], R10);
        assert_eq!(allocation[&dead_defs[2]], XMM14);
        assert_eq!(allocation[&dead_defs[3]], XMM14);
        assert_eq!(allocation[&dead_defs[4]], XMM14);
    }

    #[test]
    fn unused_volatile_fp_and_v128_loads_survive_both_x86_allocators() {
        for regalloc_mode in [
            X86RegAllocMode::Simplified,
            X86RegAllocMode::Full(AllocStrategy::LinearScan),
            X86RegAllocMode::Full(AllocStrategy::Greedy),
        ] {
            let (func, _) =
                dead_volatile_load_function(&format!("dead_volatile_compile_{regalloc_mode:?}"));
            let pipeline = X86Pipeline::new(X86PipelineConfig {
                opt_level: trust_cg_opt::OptLevel::O0,
                emit_frame: false,
                regalloc_mode,
                ..X86PipelineConfig::default()
            });
            let code = pipeline
                .compile_function(&func)
                .unwrap_or_else(|err| panic!("{regalloc_mode:?} must preserve dead loads: {err}"));
            assert!(
                code.len() > 1,
                "{regalloc_mode:?} must emit all volatile loads before RET"
            );
            assert_eq!(
                code.last(),
                Some(&0xc3),
                "{regalloc_mode:?} must retain RET"
            );
        }
    }

    /// TV-3 requires a stamped instruction for every volatile load, used or
    /// not. Unused volatile loads of every x86-64 register file compile from
    /// LIR through `compile_trust_ir_function`, which enforces TV-3 on the
    /// exact pre-pass ISel/LIR pair.
    #[test]
    fn unused_volatile_loads_pass_the_x86_dataflow_integrity_gate() {
        let entry = Block(0);
        let mut func = LirFunction::new(
            "unused_volatile_loads",
            Signature {
                params: vec![Type::I64],
                returns: vec![],
            },
        );
        func.entry_block = entry;
        func.block_order = vec![entry];
        let mut instructions: Vec<Instruction> = [
            (Type::I8, 1),
            (Type::I16, 2),
            (Type::I32, 4),
            (Type::I64, 8),
            (Type::F32, 4),
            (Type::F64, 8),
            (Type::V128, 16),
        ]
        .into_iter()
        .zip(1u32..)
        .map(|((ty, align), result)| Instruction {
            opcode: Opcode::VolatileLoad {
                ty,
                align: Some(align),
            },
            args: vec![Value(0)],
            results: vec![Value(result)],
        })
        .collect();
        instructions.push(Instruction {
            opcode: Opcode::Return,
            args: vec![],
            results: vec![],
        });
        func.blocks.insert(
            entry,
            BasicBlock {
                params: vec![],
                instructions,
                source_locs: vec![],
            },
        );
        let code = raw_no_frame_x86_pipeline()
            .compile_trust_ir_function(&func)
            .unwrap_or_else(|error| panic!("unused volatile loads must compile: {error}"));
        assert_eq!(code.last(), Some(&0xc3), "{code:02x?}");
    }

    #[test]
    fn test_resolve_inst_operands_handles_qword_lane_insert_extract() {
        let pinsrq = X86ISelInst::new(
            X86Opcode::Pinsrq,
            vec![
                X86ISelOperand::PReg(XMM8),
                X86ISelOperand::PReg(XMM0),
                X86ISelOperand::PReg(R9),
                X86ISelOperand::Imm(1),
            ],
        );
        let ops = resolve_inst_operands(&pinsrq, &HashMap::new());
        assert_eq!(ops.dst, Some(XMM8));
        assert_eq!(ops.src, Some(R9));
        assert_eq!(ops.imm, 1);

        let pextrq = X86ISelInst::new(
            X86Opcode::Pextrq,
            vec![
                X86ISelOperand::PReg(RAX),
                X86ISelOperand::PReg(XMM15),
                X86ISelOperand::Imm(0),
            ],
        );
        let ops = resolve_inst_operands(&pextrq, &HashMap::new());
        assert_eq!(ops.dst, Some(RAX));
        assert_eq!(ops.src, Some(XMM15));
        assert_eq!(ops.imm, 0);
    }

