    #[test]
    fn test_isel_to_regalloc_shift_rr_models_rcx_implicit_use() {
        let mut func = minimal_func("shift_rr_implicit_count");
        let entry = Block(0);
        let shift_ops = [
            (
                X86Opcode::ShlRR,
                VReg::new(0, RegClass::Gpr64),
                VReg::new(1, RegClass::Gpr64),
            ),
            (
                X86Opcode::ShrRR,
                VReg::new(2, RegClass::Gpr64),
                VReg::new(3, RegClass::Gpr64),
            ),
            (
                X86Opcode::SarRR,
                VReg::new(4, RegClass::Gpr64),
                VReg::new(5, RegClass::Gpr64),
            ),
        ];
        func.next_vreg = 6;

        for (opcode, dst, lhs) in shift_ops {
            func.push_inst(
                entry,
                X86ISelInst::new(
                    opcode,
                    vec![X86ISelOperand::VReg(dst), X86ISelOperand::VReg(lhs)],
                ),
            );
        }

        let ra_func = x86_isel_to_regalloc(&func).unwrap();
        let rcx = regalloc_preg(x86_64_regs::RCX);
        for (idx, (_, dst, lhs)) in shift_ops.into_iter().enumerate() {
            let inst = &ra_func.insts[idx];
            assert_eq!(inst.defs, vec![RegAllocOperand::VReg(dst)]);
            assert_eq!(inst.uses, vec![RegAllocOperand::VReg(lhs)]);
            assert!(inst.implicit_defs.is_empty());
            assert_eq!(inst.implicit_uses, vec![rcx]);
        }
    }

