    fn build_x86_high_gpr_pressure_function(live_values: u32) -> X86ISelFunction {
        let mut func = minimal_func("high_gpr_pressure");
        let entry = Block(0);
        func.next_vreg = live_values;

        for id in 0..live_values {
            func.push_inst(
                entry,
                X86ISelInst::new(
                    X86Opcode::MovRI,
                    vec![
                        X86ISelOperand::VReg(VReg::new(id, RegClass::Gpr64)),
                        X86ISelOperand::Imm(id as i64 + 1),
                    ],
                ),
            );
        }
        for id in 1..live_values {
            func.push_inst(
                entry,
                X86ISelInst::new(
                    X86Opcode::AddRR,
                    vec![
                        X86ISelOperand::VReg(VReg::new(0, RegClass::Gpr64)),
                        X86ISelOperand::VReg(VReg::new(0, RegClass::Gpr64)),
                        X86ISelOperand::VReg(VReg::new(id, RegClass::Gpr64)),
                    ],
                ),
            );
        }
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![
                    X86ISelOperand::PReg(x86_64_regs::RAX),
                    X86ISelOperand::VReg(VReg::new(0, RegClass::Gpr64)),
                ],
            ),
        );
        func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));
        func
    }

    fn build_x86_two_block_linear_high_gpr_pressure_function(live_values: u32) -> X86ISelFunction {
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut func = X86ISelFunction::new("two_block_linear_high_gpr_pressure".to_string(), sig);
        let entry = Block(0);
        let exit = Block(1);
        func.ensure_block(entry);
        func.ensure_block(exit);
        func.blocks.get_mut(&entry).unwrap().successors.push(exit);
        func.next_vreg = live_values;

        for id in 0..live_values {
            func.push_inst(
                entry,
                X86ISelInst::new(
                    X86Opcode::MovRI,
                    vec![
                        X86ISelOperand::VReg(VReg::new(id, RegClass::Gpr64)),
                        X86ISelOperand::Imm(id as i64 + 1),
                    ],
                ),
            );
        }
        for id in 1..live_values {
            func.push_inst(
                entry,
                X86ISelInst::new(
                    X86Opcode::AddRR,
                    vec![
                        X86ISelOperand::VReg(VReg::new(0, RegClass::Gpr64)),
                        X86ISelOperand::VReg(VReg::new(0, RegClass::Gpr64)),
                        X86ISelOperand::VReg(VReg::new(id, RegClass::Gpr64)),
                    ],
                ),
            );
        }
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![
                    X86ISelOperand::PReg(x86_64_regs::RAX),
                    X86ISelOperand::VReg(VReg::new(0, RegClass::Gpr64)),
                ],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(exit)]),
        );
        func.push_inst(exit, X86ISelInst::new(X86Opcode::Ret, vec![]));
        func
    }

    fn build_x86_safe_join_cfg_function(name: &str) -> X86ISelFunction {
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut func = X86ISelFunction::new(name.to_string(), sig);
        let entry = Block(0);
        let left = Block(1);
        let right = Block(2);
        let join = Block(3);
        for block in [entry, left, right, join] {
            func.ensure_block(block);
        }
        func.blocks.get_mut(&entry).unwrap().successors = vec![left, right];
        func.blocks.get_mut(&left).unwrap().successors.push(join);
        func.blocks.get_mut(&right).unwrap().successors.push(join);
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::Jcc,
                vec![
                    X86ISelOperand::CondCode(X86CondCode::E),
                    X86ISelOperand::Block(right),
                ],
            ),
        );
        func.push_inst(
            left,
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(join)]),
        );
        func.push_inst(
            right,
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(join)]),
        );
        func.push_inst(join, X86ISelInst::new(X86Opcode::Ret, vec![]));
        func
    }

    fn build_x86_join_high_gpr_pressure_function(live_values: u32) -> X86ISelFunction {
        let mut func = build_x86_safe_join_cfg_function("join_high_gpr_pressure");
        let entry = Block(0);
        let join = Block(3);
        func.next_vreg = live_values;
        func.blocks.get_mut(&entry).unwrap().insts.clear();
        func.blocks.get_mut(&join).unwrap().insts.clear();

        for id in 0..live_values {
            func.push_inst(
                entry,
                X86ISelInst::new(
                    X86Opcode::MovRI,
                    vec![
                        X86ISelOperand::VReg(VReg::new(id, RegClass::Gpr64)),
                        X86ISelOperand::Imm(id as i64 + 1),
                    ],
                ),
            );
        }
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::CmpRI,
                vec![
                    X86ISelOperand::VReg(VReg::new(0, RegClass::Gpr64)),
                    X86ISelOperand::Imm(0),
                ],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::Jcc,
                vec![
                    X86ISelOperand::CondCode(X86CondCode::E),
                    X86ISelOperand::Block(Block(2)),
                ],
            ),
        );
        for id in 1..live_values {
            func.push_inst(
                join,
                X86ISelInst::new(
                    X86Opcode::AddRR,
                    vec![
                        X86ISelOperand::VReg(VReg::new(0, RegClass::Gpr64)),
                        X86ISelOperand::VReg(VReg::new(0, RegClass::Gpr64)),
                        X86ISelOperand::VReg(VReg::new(id, RegClass::Gpr64)),
                    ],
                ),
            );
        }
        func.push_inst(
            join,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![
                    X86ISelOperand::PReg(x86_64_regs::RAX),
                    X86ISelOperand::VReg(VReg::new(0, RegClass::Gpr64)),
                ],
            ),
        );
        func.push_inst(join, X86ISelInst::new(X86Opcode::Ret, vec![]));
        func
    }

