    fn build_x86_parent_loop_preheader_pressure_function(live_values: u32) -> X86ISelFunction {
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut func = X86ISelFunction::new("parent_loop_preheader_pressure".to_string(), sig);
        let entry = Block(0);
        let loop_block = Block(1);
        let exit = Block(2);
        for block in [entry, loop_block, exit] {
            func.ensure_block(block);
        }
        func.blocks
            .get_mut(&entry)
            .unwrap()
            .successors
            .push(loop_block);
        func.blocks.get_mut(&loop_block).unwrap().successors = vec![loop_block, exit];
        func.next_vreg = live_values;

        for id in 0..live_values {
            func.push_inst(
                entry,
                X86ISelInst::new(
                    X86Opcode::MovRI,
                    vec![
                        X86ISelOperand::VReg(VReg::new(id, RegClass::Gpr64)),
                        X86ISelOperand::Imm(id as i64 + 1),
                    ],
                ),
            );
        }
        for _ in 0..live_values {
            func.push_inst(
                entry,
                X86ISelInst::new(X86Opcode::NopMulti, vec![X86ISelOperand::Imm(2)]),
            );
        }
        func.push_inst(
            entry,
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(loop_block)]),
        );

        for id in 0..live_values {
            func.push_inst(
                loop_block,
                X86ISelInst::new(
                    X86Opcode::CmpRI,
                    vec![
                        X86ISelOperand::VReg(VReg::new(id, RegClass::Gpr64)),
                        X86ISelOperand::Imm(0),
                    ],
                ),
            );
        }
        func.push_inst(
            loop_block,
            X86ISelInst::new(
                X86Opcode::Jcc,
                vec![
                    X86ISelOperand::CondCode(X86CondCode::E),
                    X86ISelOperand::Block(exit),
                ],
            ),
        );
        func.push_inst(
            loop_block,
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(loop_block)]),
        );

        func.push_inst(
            exit,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![
                    X86ISelOperand::PReg(x86_64_regs::RAX),
                    X86ISelOperand::VReg(VReg::new(0, RegClass::Gpr64)),
                ],
            ),
        );
        func.push_inst(exit, X86ISelInst::new(X86Opcode::Ret, vec![]));
        func
    }

    fn build_x86_loop_carried_multidef_function() -> X86ISelFunction {
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut func = X86ISelFunction::new("loop_carried_multidef".to_string(), sig);
        let entry = Block(0);
        let loop_block = Block(1);
        let exit = Block(2);
        for block in [entry, loop_block, exit] {
            func.ensure_block(block);
        }
        func.blocks
            .get_mut(&entry)
            .unwrap()
            .successors
            .push(loop_block);
        func.blocks.get_mut(&loop_block).unwrap().successors = vec![loop_block, exit];
        func.next_vreg = 1;

        let counter = VReg::new(0, RegClass::Gpr64);
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRI,
                vec![X86ISelOperand::VReg(counter), X86ISelOperand::Imm(0)],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(loop_block)]),
        );

        func.push_inst(
            loop_block,
            X86ISelInst::new(
                X86Opcode::CmpRI,
                vec![X86ISelOperand::VReg(counter), X86ISelOperand::Imm(6)],
            ),
        );
        func.push_inst(
            loop_block,
            X86ISelInst::new(
                X86Opcode::Jcc,
                vec![
                    X86ISelOperand::CondCode(X86CondCode::E),
                    X86ISelOperand::Block(exit),
                ],
            ),
        );
        func.push_inst(
            loop_block,
            X86ISelInst::new(
                X86Opcode::AddRI,
                vec![X86ISelOperand::VReg(counter), X86ISelOperand::Imm(1)],
            ),
        );
        func.push_inst(
            loop_block,
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(loop_block)]),
        );

        func.push_inst(
            exit,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![
                    X86ISelOperand::PReg(x86_64_regs::RAX),
                    X86ISelOperand::VReg(counter),
                ],
            ),
        );
        func.push_inst(exit, X86ISelInst::new(X86Opcode::Ret, vec![]));
        func
    }

    #[test]
    fn test_full_regalloc_high_pressure_materializes_spills_with_split_replay() {
        let func = build_x86_high_gpr_pressure_function(15);
        for strategy in [AllocStrategy::LinearScan, AllocStrategy::Greedy] {
            let pipeline = X86Pipeline::new(X86PipelineConfig {
                opt_level: trust_cg_opt::OptLevel::O0,
                regalloc_mode: X86RegAllocMode::Full(strategy),
                ..X86PipelineConfig::default()
            });
            let code = pipeline
                .compile_function(&func)
                .unwrap_or_else(|err| panic!("high-pressure {strategy:?} regalloc failed: {err}"));
            assert!(!code.is_empty(), "{strategy:?} should produce code");
            assert_eq!(*code.last().unwrap(), 0xC3, "last byte should be RET");
        }
    }

    /// Recheck (5) [TCG-POST-RA-SPILL-INIT] end to end on a REAL spilling
    /// function: the spill displacements come from the slots
    /// `install_x86_spill_slots` created, so they are non-empty whenever the
    /// allocator spilled (an always-zero spill count once made this set empty
    /// and the check vacuous), the untouched stream passes, and the same
    /// stream with one spill slot's stores dropped is refused.
    #[test]
    fn test_spill_init_recheck_runs_on_a_real_spilling_function() {
        for strategy in [AllocStrategy::LinearScan, AllocStrategy::Greedy] {
            let pipeline = X86Pipeline::new(X86PipelineConfig {
                opt_level: trust_cg_opt::OptLevel::O0,
                regalloc_mode: X86RegAllocMode::Full(strategy),
                ..X86PipelineConfig::default()
            });
            let abi = pipeline.config.call_abi;
            // The high-pressure fixture with every value redefined once
            // (`v = v + v`): a multi-def value is never rematerialized, so its
            // spill slot is really reloaded rather than replaced by a MovRI.
            let mut func = build_x86_high_gpr_pressure_function(15);
            let entry = Block(0);
            let insts = &mut func.blocks.get_mut(&entry).expect("entry block").insts;
            for id in (0..15u32).rev() {
                let v = X86ISelOperand::VReg(VReg::new(id, RegClass::Gpr64));
                insts.insert(
                    15,
                    X86ISelInst::new(X86Opcode::AddRR, vec![v.clone(), v.clone(), v]),
                );
            }
            prune_unused_x86_stack_slots(&mut func);
            let assignment = pipeline
                .run_full_regalloc(&mut func, strategy)
                .unwrap_or_else(|err| panic!("{strategy:?} regalloc failed: {err}"));
            let installed_spills = install_x86_spill_slots(&mut func, &assignment.spill_plan);
            assert!(
                !installed_spills.is_empty(),
                "{strategy:?}: the high-pressure fixture must spill"
            );
            fixup_formal_arg_parallel_copy(
                &mut func,
                &assignment.allocation,
                &installed_spills,
                abi,
            )
            .expect("formal-arg fixup");
            materialize_x86_spills(&mut func, &installed_spills, abi).expect("spill replay");
            fixup_two_address(&mut func, &assignment.allocation, abi).expect("two-address fixup");
            let layout = compute_x86_stack_frame_layout(
                &func,
                assignment.used_callee_saved.len(),
                assignment.used_callee_saved_xmms.len(),
            )
            .expect("frame layout");
            let spill_disps =
                x86_spill_slot_disps(&layout, &installed_spills).expect("spill displacements");
            assert_eq!(
                spill_disps.len(),
                installed_spills.len(),
                "{strategy:?}: every installed spill slot must have its own displacement"
            );
            resolve_x86_stack_slots(&mut func, &layout).expect("stack slot resolution");
            pipeline.insert_prologue_epilogue(&mut func, &assignment, &layout);
            resolve_x86_branches(&mut func);
            pipeline
                .recheck_post_regalloc(&func, &assignment.allocation, &spill_disps)
                .unwrap_or_else(|err| panic!("{strategy:?}: intact stream refused: {err}"));

            // Drop every store to one spill slot that the stream also reads.
            let is_spill_access = |inst: &X86ISelInst, disp: i32| {
                inst.operands.iter().any(|op| {
                    matches!(op, X86ISelOperand::MemAddr { base, disp: d }
                        if *d == disp && matches!(base.as_ref(), X86ISelOperand::PReg(p) if *p == RBP))
                })
            };
            let is_store = |op: X86Opcode| matches!(op, X86Opcode::MovMR | X86Opcode::MovMR32);
            let target = spill_disps
                .iter()
                .copied()
                .find(|&disp| {
                    let insts = || func.blocks.values().flat_map(|b| b.insts.iter());
                    insts().any(|i| is_store(i.opcode) && is_spill_access(i, disp))
                        && insts().any(|i| !is_store(i.opcode) && is_spill_access(i, disp))
                })
                .unwrap_or_else(|| panic!("{strategy:?}: no spill slot is both stored and read"));
            let mut broken = func.clone();
            for block in broken.blocks.values_mut() {
                block
                    .insts
                    .retain(|inst| !(is_store(inst.opcode) && is_spill_access(inst, target)));
            }
            let err = pipeline
                .recheck_post_regalloc(&broken, &assignment.allocation, &spill_disps)
                .expect_err("a spill slot read with its stores dropped must be refused");
            assert!(
                err.to_string().contains("[TCG-POST-RA-SPILL-INIT]"),
                "{strategy:?}: expected the spill-init refusal, got: {err}"
            );
        }
    }

    #[test]
    fn test_greedy_regalloc_high_pressure_uses_single_block_generic_splitting() {
        let mut func = build_x86_high_gpr_pressure_function(15);
        let fresh_start = func.next_vreg;
        let pipeline = X86Pipeline::new(X86PipelineConfig {
            opt_level: trust_cg_opt::OptLevel::O0,
            regalloc_mode: X86RegAllocMode::Full(AllocStrategy::Greedy),
            ..X86PipelineConfig::default()
        });

        let assignment = pipeline
            .run_full_regalloc(&mut func, AllocStrategy::Greedy)
            .expect("greedy high-pressure regalloc should replay split copies");

        assert!(
            func.next_vreg > fresh_start,
            "production x86 regalloc should create and replay split vregs for straight-line pressure"
        );
        assert!(!assignment.allocation.is_empty());

        let code = pipeline
            .compile_function(&build_x86_high_gpr_pressure_function(15))
            .expect("greedy high-pressure compile should succeed");
        assert!(!code.is_empty(), "greedy regalloc should produce code");
        assert_eq!(*code.last().unwrap(), 0xC3, "last byte should be RET");
    }

    /// `n` constants `v_i = MovRI i+1`, then for every `i` in `1..n` a copy
    /// `t = MovRR v_i` and `v0 = AddRR v0, v0, t`, with ONE shared,
    /// multiply-defined `t` so the coalescer cannot merge the copies, then
    /// `MovRR RAX, v0; Ret`. Under greedy splitting (n >= 13 on the x86 pool)
    /// a split child's only readers are those original copies.
    fn build_x86_shared_copy_pressure_function(n: u32) -> X86ISelFunction {
        let gpr = |id: u32| X86ISelOperand::VReg(VReg::new(id, RegClass::Gpr64));
        let mut func = minimal_func(&format!("shared_copy_pressure_{n}"));
        let entry = Block(0);
        func.next_vreg = 2 * n;
        for id in 0..n {
            func.push_inst(
                entry,
                X86ISelInst::new(
                    X86Opcode::MovRI,
                    vec![gpr(id), X86ISelOperand::Imm(i64::from(id) + 1)],
                ),
            );
        }
        for id in 1..n {
            func.push_inst(
                entry,
                X86ISelInst::new(X86Opcode::MovRR, vec![gpr(n), gpr(id)]),
            );
            func.push_inst(
                entry,
                X86ISelInst::new(X86Opcode::AddRR, vec![gpr(0), gpr(0), gpr(n)]),
            );
        }
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![X86ISelOperand::PReg(x86_64_regs::RAX), gpr(0)],
            ),
        );
        func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));
        func
    }

    #[test]
    fn greedy_split_child_read_only_by_copies_is_defined_in_the_replay() {
        let pipeline = X86Pipeline::new(X86PipelineConfig {
            opt_level: trust_cg_opt::OptLevel::O0,
            regalloc_mode: X86RegAllocMode::Full(AllocStrategy::Greedy),
            ..X86PipelineConfig::default()
        });
        for n in [13, 16] {
            let mut func = build_x86_shared_copy_pressure_function(n);
            let fresh_start = func.next_vreg;
            pipeline
                .run_full_regalloc(&mut func, AllocStrategy::Greedy)
                .unwrap_or_else(|err| panic!("n = {n}: greedy regalloc should replay: {err}"));

            // Non-vacuity: the allocator split, and some split child is read
            // only by copies, which is the shape under test.
            assert!(
                func.next_vreg > fresh_start,
                "n = {n}: greedy must split this function"
            );
            let ra = x86_isel_to_regalloc(&func).expect("the replayed x86 stream must convert");
            let mut readers: HashMap<VReg, Vec<bool>> = HashMap::new();
            for inst_id in &ra.blocks[0].insts {
                let inst = &ra.insts[inst_id.0 as usize];
                let is_copy = inst.opcode == trust_cg_regalloc::phi_elim::PSEUDO_COPY;
                for vreg in inst.vreg_uses() {
                    if (fresh_start..func.next_vreg).contains(&vreg.id) {
                        readers.entry(vreg).or_default().push(is_copy);
                    }
                }
            }
            assert!(
                readers
                    .values()
                    .any(|is_copy| is_copy.iter().all(|&is_copy| is_copy)),
                "n = {n}: no split child is read only by copies, so the test is vacuous"
            );

            assert_eq!(
                first_vreg_read_without_earlier_def(&func, Block(0)),
                None,
                "n = {n}: every read in the replayed stream must have an earlier definition"
            );
            let code = pipeline
                .compile_function(&build_x86_shared_copy_pressure_function(n))
                .unwrap_or_else(|err| panic!("n = {n}: compile should succeed: {err}"));
            assert_eq!(
                *code.last().unwrap(),
                0xC3,
                "n = {n}: last byte should be RET"
            );
        }
    }

    #[test]
    fn test_greedy_regalloc_two_block_linear_uses_generic_splitting() {
        let mut func = build_x86_two_block_linear_high_gpr_pressure_function(15);
        let fresh_start = func.next_vreg;
        let pipeline = X86Pipeline::new(X86PipelineConfig {
            opt_level: trust_cg_opt::OptLevel::O0,
            regalloc_mode: X86RegAllocMode::Full(AllocStrategy::Greedy),
            ..X86PipelineConfig::default()
        });

        let assignment = pipeline
            .run_full_regalloc(&mut func, AllocStrategy::Greedy)
            .expect("two-block linear greedy regalloc should replay split copies");

        assert!(
            func.next_vreg > fresh_start,
            "production x86 regalloc should create and replay split vregs for linear multi-block CFGs"
        );
        assert!(
            func.blocks
                .values()
                .flat_map(|block| block.insts.iter())
                .flat_map(|inst| inst.operands.iter())
                .any(|operand| matches!(operand, X86ISelOperand::VReg(vreg) if vreg.id >= fresh_start)),
            "replayed x86 stream should contain split-created vregs before physical substitution"
        );
        assert!(!assignment.allocation.is_empty());

        let code = pipeline
            .compile_function(&build_x86_two_block_linear_high_gpr_pressure_function(15))
            .expect("two-block linear greedy regalloc compile should succeed");
        assert!(!code.is_empty(), "greedy regalloc should produce code");
        assert_eq!(*code.last().unwrap(), 0xC3, "last byte should be RET");
    }

    #[test]
    fn test_greedy_regalloc_join_block_rejects_splitting() {
        // ANY join block (a block with >1 predecessor) rejects splitting — the
        // greedy join-block split-copy placement is unsound under register
        // pressure even without a call crossing the join (MISCOMPILE #64).
        // Previously this CFG was admitted ("safe join"); it is now failed
        // closed to plain greedy spill.
        let func = build_x86_safe_join_cfg_function("join_split_guard");
        let ra_func = x86_isel_to_regalloc(&func).expect("x86 conversion should succeed");
        assert_eq!(
            x86_regalloc_splitting_cfg_diagnostic(&ra_func),
            Err(X86SplitReplayCfgDiagnostic::JoinBlockUnderSplit { join: BlockId(3) }),
        );
        assert!(
            !x86_regalloc_splitting_supported_cfg(&ra_func),
            "x86 splitting must be rejected for any join block — call-free join \
             split-copy placement is unsound under pressure (m64)"
        );
    }

    #[test]
    fn test_greedy_regalloc_call_across_join_rejects_splitting() {
        // A diamond CFG (entry -> {left,right} -> join) whose entry block makes a
        // `call` is the `?`-operator shape: a value live across the call AND the
        // join can lose its split copy on the taken path under the greedy
        // splitter, faulting/miscompiling at runtime. Splitting must be REJECTED
        // (fail closed to plain greedy spill) for this shape; the call-free
        // `build_x86_safe_join_cfg_function` join above keeps splitting.
        let mut func = build_x86_safe_join_cfg_function("call_across_join_guard");
        let entry = Block(0);
        // Prepend a real call into the entry block (before its conditional branch),
        // so the function has BOTH a call and a join block.
        let entry_block = func.blocks.get_mut(&entry).unwrap();
        entry_block.insts.insert(
            0,
            X86ISelInst::new(X86Opcode::Call, vec![X86ISelOperand::Imm(0)]),
        );
        let ra_func = x86_isel_to_regalloc(&func).expect("x86 conversion should succeed");
        assert_eq!(
            x86_regalloc_splitting_cfg_diagnostic(&ra_func),
            Err(X86SplitReplayCfgDiagnostic::CallAcrossJoin { join: BlockId(3) }),
        );
        assert!(
            !x86_regalloc_splitting_supported_cfg(&ra_func),
            "x86 splitting must be rejected when a function has both a call and a join \
             (the `?`-operator diamond) — its join split-copy placement is unsound there"
        );
    }

    #[test]
    fn test_greedy_regalloc_fixed_reg_clobber_rejects_splitting() {
        // A function containing a DIV (a fixed-physical-register clobber: the
        // dividend is pinned in RAX and RDX is clobbered) must reject splitting —
        // the greedy splitter does not model the implicit RAX/RDX def/use edges,
        // so a live range crossing the DIV can be spilled to / reloaded from a
        // slot the DIV corrupted (the div/rem-under-pressure miscompile, m52).
        // A plain MOV to a physical register (RAX for the return value) is NOT a
        // clobber and must keep splitting; the clobber-free fixture below proves
        // the guard does not fire on it.
        let mut func = build_x86_two_block_linear_high_gpr_pressure_function(4);
        let entry = Block(0);
        func.blocks.get_mut(&entry).unwrap().insts.insert(
            0,
            X86ISelInst::new(
                X86Opcode::Div,
                vec![X86ISelOperand::VReg(VReg::new(1, RegClass::Gpr64))],
            ),
        );
        let ra_func = x86_isel_to_regalloc(&func).expect("x86 conversion should succeed");
        assert_eq!(
            x86_regalloc_splitting_cfg_diagnostic(&ra_func),
            Err(X86SplitReplayCfgDiagnostic::FixedRegClobber {
                opcode: X86Opcode::Div as u16
            })
        );
        assert!(
            !x86_regalloc_splitting_supported_cfg(&ra_func),
            "a function containing a DIV fixed-register clobber must reject splitting"
        );

        // Sanity: the clobber-free fixture keeps splitting (a plain `mov RAX, vN`
        // for the return value is not treated as a clobber).
        let clean = build_x86_two_block_linear_high_gpr_pressure_function(4);
        let clean_ra = x86_isel_to_regalloc(&clean).expect("x86 conversion should succeed");
        assert_eq!(x86_regalloc_splitting_cfg_diagnostic(&clean_ra), Ok(()));
        assert!(
            x86_regalloc_splitting_supported_cfg(&clean_ra),
            "a plain `mov RAX, vN` return-value move is not a fixed-register clobber"
        );
    }

    #[test]
    fn test_x86_regalloc_opcode_is_fixed_reg_clobber_classification() {
        // The clobber set must be exactly the opcodes whose fixed RAX/RDX (etc.)
        // constraints `add_x86_fixed_implicit_operands` adds as implicit edges.
        for op in [
            X86Opcode::Div,
            X86Opcode::Idiv,
            X86Opcode::Mul,
            X86Opcode::Cdq,
            X86Opcode::Cqo,
            X86Opcode::Cmpxchg,
            X86Opcode::AtomicRmwCasLoop,
            X86Opcode::AtomicRmwCasLoop8,
            X86Opcode::AtomicRmwCasLoop16,
        ] {
            assert!(
                x86_regalloc_opcode_is_fixed_reg_clobber(op as u16),
                "{op:?} pins/clobbers a fixed physical register and must be flagged"
            );
        }
        // Ordinary explicit-operand ops (including the explicit `mov RAX, vN`
        // return-value setup) carry no implicit fixed-register edges and must NOT
        // be flagged, so they keep splitting.
        for op in [
            X86Opcode::MovRR,
            X86Opcode::MovRI,
            X86Opcode::AddRR,
            X86Opcode::SubRR,
            X86Opcode::Ret,
            X86Opcode::Jmp,
        ] {
            assert!(
                !x86_regalloc_opcode_is_fixed_reg_clobber(op as u16),
                "{op:?} has no implicit fixed-register clobber and must keep splitting"
            );
        }
    }

    #[test]
    fn test_greedy_regalloc_join_edge_cfg_compiles_with_spill_fallback() {
        // A high-pressure join CFG no longer splits (MISCOMPILE #64 — join
        // split-copy placement is unsound); it must still compile correctly via
        // the plain greedy spill fallback.
        let mut func = build_x86_join_high_gpr_pressure_function(15);
        let pipeline = X86Pipeline::new(X86PipelineConfig {
            opt_level: trust_cg_opt::OptLevel::O0,
            regalloc_mode: X86RegAllocMode::Full(AllocStrategy::Greedy),
            ..X86PipelineConfig::default()
        });

        let assignment = pipeline
            .run_full_regalloc(&mut func, AllocStrategy::Greedy)
            .expect("join-edge greedy regalloc should fall back to spill");
        assert!(!assignment.allocation.is_empty());

        let code = pipeline
            .compile_function(&build_x86_join_high_gpr_pressure_function(15))
            .expect("join-edge greedy regalloc compile should succeed");
        assert!(!code.is_empty(), "greedy regalloc should produce code");
        assert_eq!(*code.last().unwrap(), 0xC3, "last byte should be RET");
    }

