    #[test]
    fn test_is_x86_two_address_rr() {
        assert!(is_x86_two_address_rr(X86Opcode::AddRR));
        assert!(is_x86_two_address_rr(X86Opcode::SubRR));
        assert!(is_x86_two_address_rr(X86Opcode::AndRR));
        assert!(is_x86_two_address_rr(X86Opcode::OrRR));
        assert!(is_x86_two_address_rr(X86Opcode::XorRR));
        assert!(is_x86_two_address_rr(X86Opcode::ImulRR));
        assert!(is_x86_two_address_rr(X86Opcode::Addsd));
        assert!(is_x86_two_address_rr(X86Opcode::Subsd));
        assert!(is_x86_two_address_rr(X86Opcode::Andpd));
        assert!(is_x86_two_address_rr(X86Opcode::Andps));
        assert!(is_x86_two_address_rr(X86Opcode::Pandn));
        assert!(is_x86_two_address_rr(X86Opcode::Pcmpeqb));
        assert!(is_x86_two_address_rr(X86Opcode::Pcmpeqw));
        assert!(is_x86_two_address_rr(X86Opcode::Pcmpgtb));
        assert!(is_x86_two_address_rr(X86Opcode::Pcmpgtw));
        assert!(is_x86_two_address_rr(X86Opcode::Pcmpgtd));
        assert!(is_x86_two_address_rr(X86Opcode::Paddb));
        assert!(is_x86_two_address_rr(X86Opcode::Paddw));
        assert!(is_x86_two_address_rr(X86Opcode::Paddd));
        assert!(is_x86_two_address_rr(X86Opcode::Psubb));
        assert!(is_x86_two_address_rr(X86Opcode::Psubw));
        assert!(is_x86_two_address_rr(X86Opcode::Psubd));
        assert!(is_x86_two_address_rr(X86Opcode::Paddq));
        assert!(is_x86_two_address_rr(X86Opcode::Psubq));
        assert!(is_x86_two_address_rr(X86Opcode::Pmullw));
        assert!(is_x86_two_address_rr(X86Opcode::Pmuludq));
        assert!(is_x86_two_address_rr(X86Opcode::Punpckldq));
        assert!(is_x86_two_address_rr(X86Opcode::Punpcklqdq));
        assert!(is_x86_two_address_rr(X86Opcode::Pmulld));
        assert!(is_x86_two_address_rr(X86Opcode::Pcmpeqq));
        assert!(is_x86_two_address_rr(X86Opcode::Pcmpgtq));

        // These are NOT two-address RR:
        assert!(!is_x86_two_address_rr(X86Opcode::MovRR));
        assert!(!is_x86_two_address_rr(X86Opcode::Pinsrd));
        assert!(!is_x86_two_address_rr(X86Opcode::Pinsrq));
        assert!(!is_x86_two_address_rr(X86Opcode::CmpRR));
        assert!(!is_x86_two_address_rr(X86Opcode::Sqrtsd));
        assert!(!is_x86_two_address_rr(X86Opcode::Sqrtss));
        assert!(!is_x86_two_address_rr(X86Opcode::Lea));
        assert!(!is_x86_two_address_rr(X86Opcode::Ret));
        assert!(!is_x86_two_address_rr(X86Opcode::AddRI)); // RI is in-place, not RR
        assert!(!is_x86_two_address_rr(X86Opcode::Neg)); // unary, not RR

        let dst = VReg::new(0, RegClass::Fpr128);
        let old_vector = VReg::new(1, RegClass::Fpr128);
        let scalar = VReg::new(2, RegClass::Gpr32);
        let pinsrd = X86ISelInst::new(
            X86Opcode::Pinsrd,
            vec![
                X86ISelOperand::VReg(dst),
                X86ISelOperand::VReg(old_vector),
                X86ISelOperand::VReg(scalar),
                X86ISelOperand::Imm(2),
            ],
        );
        assert_eq!(x86_two_address_lhs_operand_index(&pinsrd), Some(1));

        let scalar_qword = VReg::new(3, RegClass::Gpr64);
        let pinsrq = X86ISelInst::new(
            X86Opcode::Pinsrq,
            vec![
                X86ISelOperand::VReg(dst),
                X86ISelOperand::VReg(old_vector),
                X86ISelOperand::VReg(scalar_qword),
                X86ISelOperand::Imm(1),
            ],
        );
        assert_eq!(x86_two_address_lhs_operand_index(&pinsrq), Some(1));
    }

    #[test]
    fn test_fixup_two_address_inserts_mov_when_dst_ne_lhs() {
        // Build: ADD v2, v0, v1 (three-address, v2 != v0)
        // After assignment: v0->RAX, v1->RCX, v2->RDX
        // Fixup should insert: MOV v2, v0 before ADD v2, v0, v1
        use trust_cg_ir::x86_64_regs::{RAX, RCX, RDX};

        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut func = X86ISelFunction::new("fixup_test".to_string(), sig);
        let entry = Block(0);
        func.ensure_block(entry);

        let v0 = VReg::new(0, RegClass::Gpr64);
        let v1 = VReg::new(1, RegClass::Gpr64);
        let v2 = VReg::new(2, RegClass::Gpr64);
        func.next_vreg = 3;

        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::AddRR,
                vec![
                    X86ISelOperand::VReg(v2),
                    X86ISelOperand::VReg(v0),
                    X86ISelOperand::VReg(v1),
                ],
            ),
        );

        let mut alloc = HashMap::new();
        alloc.insert(v0, RAX);
        alloc.insert(v1, RCX);
        alloc.insert(v2, RDX);

        // Before fixup: 1 instruction (ADD)
        assert_eq!(func.blocks[&entry].insts.len(), 1);

        fixup_two_address(&mut func, &alloc, X86CallAbi::SystemV).unwrap();

        // After fixup: 2 instructions (MOV + ADD)
        let insts = &func.blocks[&entry].insts;
        assert_eq!(insts.len(), 2, "should insert MOV before ADD");
        assert_eq!(insts[0].opcode, X86Opcode::MovRR, "first should be MOV");
        assert_eq!(insts[1].opcode, X86Opcode::AddRR, "second should be ADD");

        // MOV operands should be [dst(v2), lhs(v0)]
        assert_eq!(insts[0].operands[0], X86ISelOperand::VReg(v2));
        assert_eq!(insts[0].operands[1], X86ISelOperand::VReg(v0));
    }

