    #[test]
    fn test_fixup_two_address_shift_rr_regalloc_does_not_clobber_count() {
        let mut func = minimal_func("shift_rr_count_not_clobbered");
        let entry = Block(0);
        let lhs = VReg::new(0, RegClass::Gpr64);
        let count = VReg::new(1, RegClass::Gpr64);
        let dst = VReg::new(2, RegClass::Gpr64);
        func.next_vreg = 3;

        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRI,
                vec![X86ISelOperand::VReg(lhs), X86ISelOperand::Imm(9)],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRI,
                vec![X86ISelOperand::VReg(count), X86ISelOperand::Imm(2)],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![
                    X86ISelOperand::PReg(x86_64_regs::RCX),
                    X86ISelOperand::VReg(count),
                ],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::ShlRR,
                vec![X86ISelOperand::VReg(dst), X86ISelOperand::VReg(lhs)],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![
                    X86ISelOperand::PReg(x86_64_regs::RAX),
                    X86ISelOperand::VReg(dst),
                ],
            ),
        );
        func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));

        let pipeline = raw_no_frame_x86_pipeline();
        let assignment = pipeline
            .run_full_regalloc(&mut func, AllocStrategy::LinearScan)
            .expect("linear-scan regalloc should allocate shift regression");
        let dst_preg = assignment.allocation[&dst];
        assert!(
            !x86_64_regs::x86_regs_overlap(dst_preg, x86_64_regs::RCX),
            "shift result must not be allocated to RCX because CL holds the count"
        );

        fixup_two_address(&mut func, &assignment.allocation, X86CallAbi::SystemV).unwrap();

        let insts = &func.blocks[&entry].insts;
        let count_move_idx = insts
            .iter()
            .position(|inst| {
                inst.opcode == X86Opcode::MovRR
                    && inst.operands.first() == Some(&X86ISelOperand::PReg(x86_64_regs::RCX))
            })
            .expect("test function should still contain the count move into RCX");
        let shift_idx = insts
            .iter()
            .position(|inst| inst.opcode == X86Opcode::ShlRR)
            .expect("test function should still contain the register shift");
        assert!(
            count_move_idx + 1 < shift_idx,
            "two-address copy should be inserted between the count move and shift"
        );
        assert_eq!(insts[shift_idx - 1].opcode, X86Opcode::MovRR);
        let copy_dst = resolve_operand(&insts[shift_idx - 1].operands[0], &assignment.allocation)
            .expect("two-address copy destination should resolve");
        assert_eq!(copy_dst, dst_preg);
        assert!(
            !x86_64_regs::x86_regs_overlap(copy_dst, x86_64_regs::RCX),
            "two-address fixup must not write RCX before the shift consumes CL"
        );
    }

    #[test]
    fn test_fixup_two_address_inserts_mov_for_unary_explicit_source() {
        use trust_cg_ir::x86_64_regs::{RAX, RDX};

        let mut func = minimal_func("unary_fixup_test");
        let entry = Block(0);
        let src = VReg::new(0, RegClass::Gpr64);
        let dst = VReg::new(1, RegClass::Gpr64);
        func.next_vreg = 2;

        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::Not,
                vec![X86ISelOperand::VReg(dst), X86ISelOperand::VReg(src)],
            ),
        );

        let mut alloc = HashMap::new();
        alloc.insert(src, RAX);
        alloc.insert(dst, RDX);

        fixup_two_address(&mut func, &alloc, X86CallAbi::SystemV).unwrap();

        let insts = &func.blocks[&entry].insts;
        assert_eq!(insts.len(), 2, "should insert MOV before unary op");
        assert_eq!(insts[0].opcode, X86Opcode::MovRR);
        assert_eq!(
            insts[0].operands,
            vec![X86ISelOperand::VReg(dst), X86ISelOperand::VReg(src)]
        );
        assert_eq!(insts[1].opcode, X86Opcode::Not);
    }

    #[test]
    fn test_fixup_two_address_noncommutative_packed_sse_rhs_alias_uses_scratch() {
        for opcode in [
            X86Opcode::Pandn,
            X86Opcode::Pcmpgtb,
            X86Opcode::Pcmpgtw,
            X86Opcode::Pcmpgtd,
            X86Opcode::Psubb,
            X86Opcode::Psubw,
            X86Opcode::Psubd,
        ] {
            let mut func = minimal_func("packed_sse_rhs_alias_fixup_test");
            let entry = Block(0);
            let lhs = VReg::new(0, RegClass::Fpr128);
            let rhs = VReg::new(1, RegClass::Fpr128);
            let dst = VReg::new(2, RegClass::Fpr128);
            func.next_vreg = 3;

            func.push_inst(
                entry,
                X86ISelInst::new(
                    opcode,
                    vec![
                        X86ISelOperand::VReg(dst),
                        X86ISelOperand::VReg(lhs),
                        X86ISelOperand::VReg(rhs),
                    ],
                ),
            );

            let mut alloc = HashMap::new();
            alloc.insert(lhs, XMM0);
            alloc.insert(rhs, XMM1);
            alloc.insert(dst, XMM1);

            fixup_two_address(&mut func, &alloc, X86CallAbi::SystemV).unwrap();

            let insts = &func.blocks[&entry].insts;
            assert_eq!(
                insts.len(),
                3,
                "{opcode:?} should preserve rhs through a scratch sequence"
            );
            assert_eq!(insts[0].opcode, X86Opcode::MovdqaRR);
            assert_eq!(insts[1].opcode, opcode);
            assert_eq!(insts[2].opcode, X86Opcode::MovdqaRR);

            let scratch = X86ISelOperand::PReg(XMM14);
            assert_eq!(
                insts[0].operands,
                vec![scratch.clone(), X86ISelOperand::VReg(lhs)]
            );
            assert_eq!(
                insts[1].operands,
                vec![scratch.clone(), scratch.clone(), X86ISelOperand::VReg(rhs)]
            );
            assert_eq!(insts[2].operands, vec![X86ISelOperand::VReg(dst), scratch]);

            let copy_in = resolve_inst_operands(&insts[0], &alloc);
            assert_eq!(copy_in.dst, Some(XMM14));
            assert_eq!(copy_in.src, Some(XMM0));
            let packed_op = resolve_inst_operands(&insts[1], &alloc);
            assert_eq!(packed_op.dst, Some(XMM14));
            assert_eq!(packed_op.src, Some(XMM1));
            let copy_out = resolve_inst_operands(&insts[2], &alloc);
            assert_eq!(copy_out.dst, Some(XMM1));
            assert_eq!(copy_out.src, Some(XMM14));
        }
    }

    #[test]
    fn test_fixup_two_address_noncommutative_packed_sse_rhs_alias_fails_without_scratch() {
        let mut func = minimal_func("packed_sse_rhs_alias_no_scratch_test");
        let entry = Block(0);
        let lhs = VReg::new(0, RegClass::Fpr128);
        let rhs = VReg::new(1, RegClass::Fpr128);
        let dst = VReg::new(2, RegClass::Fpr128);
        func.next_vreg = 3;

        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::Pcmpgtd,
                vec![
                    X86ISelOperand::VReg(dst),
                    X86ISelOperand::VReg(lhs),
                    X86ISelOperand::VReg(rhs),
                ],
            ),
        );

        let mut alloc = HashMap::new();
        alloc.insert(lhs, XMM0);
        alloc.insert(rhs, XMM1);
        alloc.insert(dst, XMM1);
        for (idx, preg) in X86_ALLOCATABLE_XMMS.iter().copied().enumerate() {
            alloc.insert(VReg::new(10 + idx as u32, RegClass::Fpr128), preg);
        }

        let err = fixup_two_address(&mut func, &alloc, X86CallAbi::SystemV).unwrap_err();
        let X86PipelineError::RegAlloc(msg) = err else {
            panic!("expected RegAlloc fail-closed error");
        };
        assert!(
            msg.contains("cannot repair dst/rhs alias"),
            "unexpected error: {msg}"
        );
    }

