    // -----------------------------------------------------------------------
    // TV-5 ghost-operand contract + end-to-end fault injection
    // -----------------------------------------------------------------------

    /// Build `[opcode v1, v0, v2]` (three-address, vregs 0..=2) in a fresh
    /// function for driving `fixup_two_address` directly.
    fn tv5_three_address_func(opcode: X86Opcode) -> X86ISelFunction {
        let mut func = minimal_func("tv5_fixup");
        let entry = Block(0);
        func.next_vreg = 3;
        func.push_inst(
            entry,
            X86ISelInst::new(
                opcode,
                vec![test_vreg_op(0), test_vreg_op(1), test_vreg_op(2)],
            ),
        );
        func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));
        func
    }

    #[test]
    fn x86_packed_bitwise_fixup_uses_full_xmm_bridge() {
        use trust_cg_ir::x86_64_regs::{XMM0, XMM1, XMM2};

        for (opcode, class) in [
            (X86Opcode::Andps, RegClass::Fpr32),
            (X86Opcode::Andpd, RegClass::Fpr64),
        ] {
            let mut func = minimal_func("packed_bitwise_bridge");
            let entry = Block(0);
            let dst = VReg::new(0, class);
            let lhs = VReg::new(1, class);
            let rhs = VReg::new(2, class);
            func.next_vreg = 3;
            func.push_inst(
                entry,
                X86ISelInst::new(
                    opcode,
                    vec![
                        X86ISelOperand::VReg(dst),
                        X86ISelOperand::VReg(lhs),
                        X86ISelOperand::VReg(rhs),
                    ],
                ),
            );
            let alloc = HashMap::from([(dst, XMM2), (lhs, XMM0), (rhs, XMM1)]);

            fixup_two_address(&mut func, &alloc, X86CallAbi::SystemV).unwrap();

            let insts = &func.blocks[&entry].insts;
            assert_eq!(insts.len(), 2, "{opcode:?}: {insts:?}");
            assert_eq!(
                insts[0].opcode,
                X86Opcode::MovdqaRR,
                "{opcode:?} reads all 128 XMM bits and needs a full-width bridge"
            );
            assert_eq!(insts[1].opcode, opcode);
        }
    }

    /// PINNED GHOST CONTRACT: the tied-ghost-operand dataflow validator
    /// (trust-cg-verify::post_ra_dataflow) depends on `operands[1]` of a
    /// tied-form instruction surviving `fixup_two_address` as the
    /// encoder-ignored certificate of the intended tied source. Pin all
    /// three fixup arms:
    ///   arm 3 (bridge copy): the copy `[dst, lhs]` is inserted immediately
    ///     before the tied instruction and `operands[1]` is UNCHANGED;
    ///   arm 1 (commutative dst-aliases-rhs swap): operands 1 and 2 are
    ///     swapped so `operands[1]` resolves to a register overlapping
    ///     `operands[0]`;
    ///   arm 2 (non-commutative dst-aliases-rhs scratch triangle):
    ///     `operands[0]` and `operands[1]` are BOTH the same scratch PReg.
    #[test]
    fn x86_fixup_two_address_ghost_contract_pinned() {
        use trust_cg_ir::x86_64_regs::{RAX, RCX, RDX};
        let entry = Block(0);

        // Arm 3: dst(RAX) != lhs(RCX), rhs(RDX) disjoint -> bridge copy.
        let mut func = tv5_three_address_func(X86Opcode::AddRR);
        let alloc = HashMap::from([
            (test_vreg(0), RAX),
            (test_vreg(1), RCX),
            (test_vreg(2), RDX),
        ]);
        fixup_two_address(&mut func, &alloc, X86CallAbi::SystemV).unwrap();
        let insts = &func.blocks[&entry].insts;
        assert_eq!(insts.len(), 3, "bridge copy + tied inst + ret");
        assert_eq!(insts[0].opcode, X86Opcode::MovRR);
        assert_eq!(
            insts[0].operands,
            vec![test_vreg_op(0), test_vreg_op(1)],
            "the bridge copy must be `mov dst <- lhs`, adjacent to the tied inst"
        );
        assert_eq!(insts[1].opcode, X86Opcode::AddRR);
        assert_eq!(
            insts[1].operands[1],
            test_vreg_op(1),
            "arm 3 must leave the ghost operands[1] UNCHANGED"
        );

        // Arm 1: commutative, dst aliases rhs -> swap; op1 then aliases op0.
        let mut func = tv5_three_address_func(X86Opcode::AddRR);
        let alloc = HashMap::from([
            (test_vreg(0), RAX),
            (test_vreg(1), RCX),
            (test_vreg(2), RAX),
        ]);
        fixup_two_address(&mut func, &alloc, X86CallAbi::SystemV).unwrap();
        let insts = &func.blocks[&entry].insts;
        assert_eq!(insts.len(), 2, "swap arm inserts no copy");
        assert_eq!(insts[0].opcode, X86Opcode::AddRR);
        assert_eq!(
            insts[0].operands,
            vec![test_vreg_op(0), test_vreg_op(2), test_vreg_op(1)]
        );
        let op0 = resolve_operand(&insts[0].operands[0], &alloc).unwrap();
        let op1 = resolve_operand(&insts[0].operands[1], &alloc).unwrap();
        assert!(
            x86_64_regs::x86_regs_overlap(op0, op1),
            "after the commutative swap the ghost must alias the destination"
        );

        // Arm 2: non-commutative, dst aliases rhs -> scratch triangle.
        let mut func = tv5_three_address_func(X86Opcode::SubRR);
        let alloc = HashMap::from([
            (test_vreg(0), RAX),
            (test_vreg(1), RCX),
            (test_vreg(2), RAX),
        ]);
        fixup_two_address(&mut func, &alloc, X86CallAbi::SystemV).unwrap();
        let insts = &func.blocks[&entry].insts;
        assert_eq!(insts.len(), 4, "copy-in + tied inst + copy-out + ret");
        assert_eq!(insts[0].opcode, X86Opcode::MovRR);
        assert_eq!(insts[1].opcode, X86Opcode::SubRR);
        assert_eq!(insts[2].opcode, X86Opcode::MovRR);
        let scratch = insts[1].operands[0].clone();
        assert!(
            matches!(scratch, X86ISelOperand::PReg(_)),
            "arm 2 rewrites the destination to a scratch PReg"
        );
        assert_eq!(
            insts[1].operands[1], scratch,
            "arm 2 must set operands[0] == operands[1] == the scratch"
        );
        assert_eq!(insts[0].operands[0], scratch, "copy-in targets the scratch");
        assert_eq!(insts[0].operands[1], test_vreg_op(1));
        assert_eq!(insts[2].operands, vec![test_vreg_op(0), scratch]);
    }

    /// End-to-end fault injection over REAL fixup output: run
    /// `fixup_two_address`, assert the stream passes the TV-5 dataflow
    /// validator, then DELETE the inserted bridge copy and assert the
    /// validator refutes with tied-operand-value-mismatch — the exact
    /// empirically proven silent-miscompile shape.
    #[test]
    fn x86_post_ra_dataflow_end_to_end_fault_injection_refutes() {
        use trust_cg_ir::x86_64_regs::{RAX, RCX, RDX};
        use trust_cg_verify::post_ra_dataflow;
        use trust_cg_verify::post_regalloc_recheck::PostRegallocRecheckMode;

        let entry = Block(0);
        let mut func = tv5_three_address_func(X86Opcode::AddRR);
        let alloc = HashMap::from([
            (test_vreg(0), RAX),
            (test_vreg(1), RCX),
            (test_vreg(2), RDX),
        ]);
        fixup_two_address(&mut func, &alloc, X86CallAbi::SystemV).unwrap();

        // Green half: the un-mutated fixup output discharges the obligation.
        assert!(
            post_ra_dataflow::evaluate(&func, &alloc, "x86_64", PostRegallocRecheckMode::Enforce)
                .is_none(),
            "sound fixup output must pass the dataflow validator"
        );

        // Fault injection: delete the load-bearing bridge copy.
        let block = func.blocks.get_mut(&entry).unwrap();
        let bridge_idx = block
            .insts
            .iter()
            .position(|inst| inst.opcode == X86Opcode::MovRR)
            .expect("fixup must have inserted a MovRR bridge copy");
        block.insts.remove(bridge_idx);

        let violation =
            post_ra_dataflow::evaluate(&func, &alloc, "x86_64", PostRegallocRecheckMode::Enforce)
                .expect("deleting the bridge copy must fail closed");
        assert_eq!(violation.kind.tag(), "tied-operand-value-mismatch");
    }

    /// The pipeline recheck surfaces the TV-5 refutation as a fail-closed
    /// `X86PipelineError::RegAlloc` carrying the greppable tag (env is never
    /// set in tests; the compiled-in default is Enforce).
    #[test]
    fn x86_recheck_post_regalloc_dataflow_error_string() {
        use trust_cg_ir::x86_64_regs::{RAX, RCX, RDX};

        let entry = Block(0);
        let mut func = tv5_three_address_func(X86Opcode::AddRR);
        let alloc = HashMap::from([
            (test_vreg(0), RAX),
            (test_vreg(1), RCX),
            (test_vreg(2), RDX),
        ]);
        fixup_two_address(&mut func, &alloc, X86CallAbi::SystemV).unwrap();
        let block = func.blocks.get_mut(&entry).unwrap();
        let bridge_idx = block
            .insts
            .iter()
            .position(|inst| inst.opcode == X86Opcode::MovRR)
            .expect("fixup must have inserted a MovRR bridge copy");
        block.insts.remove(bridge_idx);

        let pipeline = X86Pipeline::new(X86PipelineConfig::default());
        let err = pipeline
            .recheck_post_regalloc(&func, &alloc, &HashSet::new())
            .expect_err("the corrupted stream must fail the recheck closed");
        match err {
            X86PipelineError::RegAlloc(msg) => {
                assert!(msg.contains("[TCG-POST-RA-DATAFLOW]"), "{msg}");
                assert!(msg.contains("tied-operand-value-mismatch"), "{msg}");
            }
            other => panic!("expected X86PipelineError::RegAlloc, got {other:?}"),
        }
    }

    /// Green end-to-end: a function whose lowering GUARANTEES a two-address
    /// bridge copy (dst != lhs on physical registers) compiles Ok through the
    /// full pipeline with the TV-5 dataflow gate live at its Enforce default.
    #[test]
    fn x86_post_ra_dataflow_green_end_to_end_bridge_copy() {
        use trust_cg_ir::x86_64_regs::{RAX, RCX, RDX};

        let mut func = minimal_func("tv5_green");
        let entry = Block(0);
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRI,
                vec![X86ISelOperand::PReg(RCX), X86ISelOperand::Imm(1)],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRI,
                vec![X86ISelOperand::PReg(RDX), X86ISelOperand::Imm(2)],
            ),
        );
        // Three-address on pregs: dst(RAX) != lhs(RCX) forces the bridge.
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::AddRR,
                vec![
                    X86ISelOperand::PReg(RAX),
                    X86ISelOperand::PReg(RCX),
                    X86ISelOperand::PReg(RDX),
                ],
            ),
        );
        func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));

        let pipeline = raw_no_frame_x86_pipeline();
        let code = pipeline
            .compile_function(&func)
            .expect("guaranteed-bridge function must compile with TV-5 enforced");
        assert!(!code.is_empty());
    }

    /// PINNED (movrr-coalesce x TV-5, green half): the post-fixup `MovRR`
    /// coalescer deletes a pure CSE copy and renames the downstream real
    /// reads AND the encoder-ignored tied ghost `operands[1]` in lockstep,
    /// and the transformed stream still discharges TV-5's tied-operand
    /// obligation (the sym-faithful-rename carve-out documented in
    /// trust-cg-verify::post_ra_dataflow's module doc).
    #[test]
    fn x86_movrr_coalesce_renames_ghost_and_passes_tv5() {
        use trust_cg_ir::x86_64_regs::{RBX, RCX, RDX, RSI};
        use trust_cg_verify::post_ra_dataflow;
        use trust_cg_verify::post_regalloc_recheck::PostRegallocRecheckMode;

        let entry = Block(0);
        let mut func = minimal_func("movrr_ghost_rename");
        // Post-fixup shape: pure CSE copy, arm-3 bridge, tied op, ret.
        //   movq %rbx, %rsi          (candidate: pdst=RSI <- psrc=RBX)
        //   movq %rsi, %rcx          (bridge: dst <- lhs)
        //   addq  [RCX, ghost=RSI, RDX]
        //   ret
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![X86ISelOperand::PReg(RSI), X86ISelOperand::PReg(RBX)],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![X86ISelOperand::PReg(RCX), X86ISelOperand::PReg(RSI)],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::AddRR,
                vec![
                    X86ISelOperand::PReg(RCX),
                    X86ISelOperand::PReg(RSI),
                    X86ISelOperand::PReg(RDX),
                ],
            ),
        );
        func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));

        let alloc: HashMap<VReg, X86PReg> = HashMap::new();
        let removed = coalesce_x86_redundant_movrr_copies(&mut func, &alloc);
        assert_eq!(removed, 1, "exactly the pure CSE copy must be coalesced");

        let insts = &func.blocks[&entry].insts;
        assert_eq!(insts.len(), 3, "copy deleted; bridge + tied + ret remain");
        assert_eq!(insts[0].opcode, X86Opcode::MovRR);
        assert_eq!(
            insts[0].operands,
            vec![X86ISelOperand::PReg(RCX), X86ISelOperand::PReg(RBX)],
            "the bridge's real read must be renamed to the copy source"
        );
        assert_eq!(insts[1].opcode, X86Opcode::AddRR);
        assert_eq!(
            insts[1].operands[1],
            X86ISelOperand::PReg(RBX),
            "the tied ghost operands[1] must be renamed in lockstep"
        );

        assert!(
            post_ra_dataflow::evaluate(&func, &alloc, "x86_64", PostRegallocRecheckMode::Enforce)
                .is_none(),
            "the sym-faithful rename must discharge TV-5's tied obligation"
        );
    }

    /// Build the canonical post-fixup GPR tied bridge:
    ///
    /// ```text
    ///   movq  a, d              <- the two-address bridge (a = psrc, d = pdst)
    ///   xorq  d, ghost a, b     <- tied xor
    ///   addq  c, c, d           <- consumer: a renameable pure read of `d`
    /// ```
    ///
    /// plus whatever the caller appends. The block has no successors, so its
    /// GPR live-out is empty.
    ///
    /// ⚑ `XorRR`, not `AddRR`: an `AddRR` bridge with dead flags is claimed by
    /// the earlier bridge-into-LEA arm, which would make this fixture test
    /// that arm instead of this one.
    fn tied_bridge_func(name: &str) -> (X86ISelFunction, Block) {
        use trust_cg_ir::x86_64_regs::{RBX, RCX, RDI, RDX};
        let entry = Block(0);
        let mut func = minimal_func(name);
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![X86ISelOperand::PReg(RCX), X86ISelOperand::PReg(RBX)],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::XorRR,
                vec![
                    X86ISelOperand::PReg(RCX),
                    X86ISelOperand::PReg(RBX),
                    X86ISelOperand::PReg(RDX),
                ],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::AddRR,
                vec![
                    X86ISelOperand::PReg(RDI),
                    X86ISelOperand::PReg(RDI),
                    X86ISelOperand::PReg(RCX),
                ],
            ),
        );
        (func, entry)
    }

    /// The tied-RMW arm: `mov a,d ; add d,b` collapses to the self-tied
    /// `add a,b` with later reads of `d` renamed to `a`, and TV-5 accepts it.
    ///
    /// This is the copy class `x86_try_rename_coalesce_copy` can NEVER remove:
    /// its first guard rejects any copy whose destination is read-modified
    /// later, and the instruction after a `fixup_two_address` bridge is BY
    /// CONSTRUCTION exactly that. The cleanup pass and the pass that creates
    /// the copies were structurally incompatible until this arm existed.
    #[test]
    fn x86_tied_copy_elide_collapses_bridge_and_passes_tv5() {
        use trust_cg_ir::x86_64_regs::{RBX, RDI, RDX};
        use trust_cg_verify::post_ra_dataflow;
        use trust_cg_verify::post_regalloc_recheck::PostRegallocRecheckMode;

        let (mut func, entry) = tied_bridge_func("tied_copy_elide");
        let alloc: HashMap<VReg, X86PReg> = HashMap::new();
        let removed = coalesce_x86_redundant_movrr_copies(&mut func, &alloc);
        assert_eq!(removed, 1, "the tied bridge copy must be collapsed");

        let insts = &func.blocks[&entry].insts;
        assert_eq!(insts.len(), 2, "bridge deleted; tied xor + consumer remain");
        assert_eq!(insts[0].opcode, X86Opcode::XorRR);
        assert_eq!(
            insts[0].operands,
            vec![
                X86ISelOperand::PReg(RBX),
                X86ISelOperand::PReg(RBX),
                X86ISelOperand::PReg(RDX),
            ],
            "the xor must be SELF-TIED on the bridge source"
        );
        assert_eq!(
            insts[1].operands,
            vec![
                X86ISelOperand::PReg(RDI),
                X86ISelOperand::PReg(RDI),
                X86ISelOperand::PReg(RBX),
            ],
            "the downstream read of the old destination must be renamed"
        );

        assert!(
            post_ra_dataflow::evaluate(&func, &alloc, "x86_64", PostRegallocRecheckMode::Enforce)
                .is_none(),
            "a self-tied op discharges TV-5's tied obligation"
        );
    }

    /// THE soundness condition: the bridge SOURCE must be dead after the op,
    /// because the collapsed op overwrites it with the result. A later read of
    /// the source must decline.
    #[test]
    fn x86_tied_copy_elide_declines_when_bridge_source_is_still_read() {
        use trust_cg_ir::x86_64_regs::{RBX, RSI};

        let (mut func, entry) = tied_bridge_func("tied_copy_elide_src_live");
        // `movq %rbx, %rsi` — a plain read of the bridge SOURCE after the op.
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![X86ISelOperand::PReg(RSI), X86ISelOperand::PReg(RBX)],
            ),
        );
        let before: Vec<_> = func.blocks[&entry]
            .insts
            .iter()
            .map(|i| (i.opcode, i.operands.clone()))
            .collect();
        let alloc: HashMap<VReg, X86PReg> = HashMap::new();
        let removed = coalesce_x86_redundant_movrr_copies(&mut func, &alloc);
        assert_eq!(removed, 0, "a live bridge source must decline the collapse");
        let after: Vec<_> = func.blocks[&entry]
            .insts
            .iter()
            .map(|i| (i.opcode, i.operands.clone()))
            .collect();
        assert_eq!(after, before, "declining must leave the stream untouched");
    }

    /// A downstream read of the bridge DESTINATION that cannot be rewritten to
    /// the source — here a tied read-modify, the same shape that makes the
    /// existing rename arm bail — must decline: renaming it would redirect a
    /// definition, and NOT renaming it would read a register the collapse no
    /// longer writes.
    #[test]
    fn x86_tied_copy_elide_declines_on_unrenameable_destination_read() {
        use trust_cg_ir::x86_64_regs::{RCX, RSI};

        let (mut func, entry) = tied_bridge_func("tied_copy_elide_rmw_read");
        // `addq %rsi, %rcx` in tied form: operand 0 is a read-modify of RCX.
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::AddRR,
                vec![
                    X86ISelOperand::PReg(RCX),
                    X86ISelOperand::PReg(RCX),
                    X86ISelOperand::PReg(RSI),
                ],
            ),
        );
        let before: Vec<_> = func.blocks[&entry]
            .insts
            .iter()
            .map(|i| (i.opcode, i.operands.clone()))
            .collect();
        let alloc: HashMap<VReg, X86PReg> = HashMap::new();
        let removed = coalesce_x86_redundant_movrr_copies(&mut func, &alloc);
        assert_eq!(
            removed, 0,
            "an unrenameable read of the bridge destination must decline"
        );
        let after: Vec<_> = func.blocks[&entry]
            .insts
            .iter()
            .map(|i| (i.opcode, i.operands.clone()))
            .collect();
        assert_eq!(after, before, "declining must leave the stream untouched");
    }

    /// Run `body` with the LEA self-writeback arm opted IN.
    ///
    /// ⚑ The arm is OFF by default (see `x86_lea_writeback_collapse_enabled`),
    /// so every test below — including the DECLINE tests — must opt in. A
    /// decline test that ran at the default would pass vacuously: it would be
    /// asserting that a disabled arm does nothing, not that the guard holds.
    fn with_lea_writeback_on<T>(body: impl FnOnce() -> T) -> T {
        crate::env_lock::with_env_overrides(&[("TCG_X86_LEA_WRITEBACK", "1")], body)
    }

    /// `lea d,[a+1] ; mov a,d ; cmp d,N` — the unit-stride induction-variable
    /// shape at the bottom of every counted loop.
    fn lea_self_writeback_func(name: &str) -> (X86ISelFunction, Block) {
        use trust_cg_ir::x86_64_regs::{RCX, RDI};
        let entry = Block(0);
        let mut func = minimal_func(name);
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::Lea,
                vec![
                    X86ISelOperand::PReg(RCX),
                    X86ISelOperand::MemAddr {
                        base: Box::new(X86ISelOperand::PReg(RDI)),
                        disp: 1,
                    },
                ],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![X86ISelOperand::PReg(RDI), X86ISelOperand::PReg(RCX)],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::CmpRI,
                vec![X86ISelOperand::PReg(RCX), X86ISelOperand::Imm(64)],
            ),
        );
        (func, entry)
    }

    /// The LEA self-writeback arm: `lea d,[a+1] ; mov a,d` collapses to the
    /// in-place `lea a,[a+1]`, with the trip test's read of `d` renamed to `a`.
    ///
    /// This is the copy neither existing arm can remove. The producer-writeback
    /// arm has no `Lea` in its allowlist AND requires `d` dead, which the trip
    /// test refutes; the rename arm coalesces in the other direction and bails
    /// because `a` — the induction variable — is loop-carried.
    #[test]
    fn x86_lea_self_writeback_collapses_and_passes_tv5() {
        use trust_cg_ir::x86_64_regs::RDI;
        use trust_cg_verify::post_ra_dataflow;
        use trust_cg_verify::post_regalloc_recheck::PostRegallocRecheckMode;

        let (mut func, entry) = lea_self_writeback_func("lea_self_writeback");
        let alloc: HashMap<VReg, X86PReg> = HashMap::new();
        let removed =
            with_lea_writeback_on(|| coalesce_x86_redundant_movrr_copies(&mut func, &alloc));
        assert_eq!(removed, 1, "the induction-variable writeback must collapse");

        let insts = &func.blocks[&entry].insts;
        assert_eq!(insts.len(), 2, "writeback deleted; lea + trip test remain");
        assert_eq!(insts[0].opcode, X86Opcode::Lea);
        assert_eq!(
            insts[0].operands,
            vec![
                X86ISelOperand::PReg(RDI),
                X86ISelOperand::MemAddr {
                    base: Box::new(X86ISelOperand::PReg(RDI)),
                    disp: 1,
                },
            ],
            "the lea must increment the induction variable IN PLACE"
        );
        assert_eq!(
            insts[1].operands,
            vec![X86ISelOperand::PReg(RDI), X86ISelOperand::Imm(64)],
            "the trip test's read of the dead temporary must be renamed"
        );

        assert!(
            post_ra_dataflow::evaluate(&func, &alloc, "x86_64", PostRegallocRecheckMode::Enforce)
                .is_none(),
            "an in-place lea is ordinary value routing TV-5 accepts"
        );
    }

    /// THE shape condition: the address must be BASED ON the writeback's
    /// destination. Redirecting the destination of a lea that does not read `a`
    /// would be a general destination redirect, which this arm's empty-interval
    /// soundness argument does not cover — it must decline.
    #[test]
    fn x86_lea_self_writeback_declines_when_base_is_not_the_writeback_destination() {
        use trust_cg_ir::x86_64_regs::{RCX, RDI, RDX};

        let entry = Block(0);
        let mut func = minimal_func("lea_self_writeback_foreign_base");
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::Lea,
                vec![
                    X86ISelOperand::PReg(RCX),
                    X86ISelOperand::MemAddr {
                        base: Box::new(X86ISelOperand::PReg(RDX)),
                        disp: 1,
                    },
                ],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![X86ISelOperand::PReg(RDI), X86ISelOperand::PReg(RCX)],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::CmpRI,
                vec![X86ISelOperand::PReg(RCX), X86ISelOperand::Imm(64)],
            ),
        );
        let before: Vec<_> = func.blocks[&entry]
            .insts
            .iter()
            .map(|i| (i.opcode, i.operands.clone()))
            .collect();
        let alloc: HashMap<VReg, X86PReg> = HashMap::new();
        assert_eq!(
            with_lea_writeback_on(|| coalesce_x86_redundant_movrr_copies(&mut func, &alloc)),
            0,
            "a lea whose base is not the writeback destination must decline"
        );
        let after: Vec<_> = func.blocks[&entry]
            .insts
            .iter()
            .map(|i| (i.opcode, i.operands.clone()))
            .collect();
        assert_eq!(after, before, "declining must leave the stream untouched");
    }

    /// A downstream read of the LEA's temporary that cannot be rewritten — here
    /// a tied read-modify — must decline: renaming it would redirect a
    /// definition, and NOT renaming it would read a register the collapse no
    /// longer writes.
    #[test]
    fn x86_lea_self_writeback_declines_on_unrenameable_temporary_read() {
        use trust_cg_ir::x86_64_regs::{RCX, RSI};

        let (mut func, entry) = lea_self_writeback_func("lea_self_writeback_rmw_read");
        // `addq %rsi, %rcx` in tied form: operand 0 is a read-modify of RCX.
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::AddRR,
                vec![
                    X86ISelOperand::PReg(RCX),
                    X86ISelOperand::PReg(RCX),
                    X86ISelOperand::PReg(RSI),
                ],
            ),
        );
        let before: Vec<_> = func.blocks[&entry]
            .insts
            .iter()
            .map(|i| (i.opcode, i.operands.clone()))
            .collect();
        let alloc: HashMap<VReg, X86PReg> = HashMap::new();
        assert_eq!(
            with_lea_writeback_on(|| coalesce_x86_redundant_movrr_copies(&mut func, &alloc)),
            0,
            "an unrenameable read of the lea temporary must decline"
        );
        let after: Vec<_> = func.blocks[&entry]
            .insts
            .iter()
            .map(|i| (i.opcode, i.operands.clone()))
            .collect();
        assert_eq!(after, before, "declining must leave the stream untouched");
    }

    /// The rename is only value-preserving while `a` still carries `d`'s value.
    /// A write to `a` BEFORE a surviving read of `d` must decline.
    #[test]
    fn x86_lea_self_writeback_declines_when_a_is_overwritten_before_the_read() {
        use trust_cg_ir::x86_64_regs::{RCX, RDI, RSI};

        let entry = Block(0);
        let mut func = minimal_func("lea_self_writeback_a_clobbered");
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::Lea,
                vec![
                    X86ISelOperand::PReg(RCX),
                    X86ISelOperand::MemAddr {
                        base: Box::new(X86ISelOperand::PReg(RDI)),
                        disp: 1,
                    },
                ],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![X86ISelOperand::PReg(RDI), X86ISelOperand::PReg(RCX)],
            ),
        );
        // `addq %rsi, %rdi` (tied) — `a` no longer carries the lea's result.
        // ⚑ A tied read-modify rather than a plain `mov`: a full redefinition of
        // `a` would make the writeback outright DEAD, and the pre-existing
        // rename arm would remove it first, so the fixture would not exercise
        // this guard at all.
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::AddRR,
                vec![
                    X86ISelOperand::PReg(RDI),
                    X86ISelOperand::PReg(RDI),
                    X86ISelOperand::PReg(RSI),
                ],
            ),
        );
        // …so this read of `d` can no longer be renamed to it.
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::CmpRI,
                vec![X86ISelOperand::PReg(RCX), X86ISelOperand::Imm(64)],
            ),
        );
        let before: Vec<_> = func.blocks[&entry]
            .insts
            .iter()
            .map(|i| (i.opcode, i.operands.clone()))
            .collect();
        let alloc: HashMap<VReg, X86PReg> = HashMap::new();
        assert_eq!(
            with_lea_writeback_on(|| coalesce_x86_redundant_movrr_copies(&mut func, &alloc)),
            0,
            "a clobbered `a` before a surviving read of `d` must decline"
        );
        let after: Vec<_> = func.blocks[&entry]
            .insts
            .iter()
            .map(|i| (i.opcode, i.operands.clone()))
            .collect();
        assert_eq!(after, before, "declining must leave the stream untouched");
    }

    /// The arm is DEFAULT ON since 2026-09-30, and ONE flag must be the whole difference.
    ///
    /// ⚑ THE DEFAULT IS STILL THE LOAD-BEARING HALF of this test; only its polarity moved.
    /// The previous version asserted "off unless asked" and said so in exactly these terms:
    /// flipping the polarity by mistake must not pass the suite. That property is preserved
    /// here in the new direction — the assertions below run on a stream the arm is KNOWN to
    /// collapse, so a wiring slip in either direction fails.
    ///
    /// WHY THE POLARITY MOVED, since the old reason is recorded in the git history and looks
    /// authoritative. The old posture rested on `p7_sieve`'s shipped binary regressing 1.44x
    /// on placement with the arm on, and on `p1_xorshift` gaining 14.6%. Both figures were
    /// re-measured on 2026-09-30, once a tracked option made the arm askable through the
    /// bridge at all (its only channel had been a `TCG_*` variable `trustc` refuses), and
    /// BOTH had expired: p1 0.9996 -> 0.9998 and p7 0.7118 -> 0.7142, each inside its own
    /// noise floor. The flip stands on a different and smaller basis — `p2_collatz` 1.0231 ->
    /// 1.0105, a parity violation halved, against `m2_call_heavy` and `p6_branch_match`
    /// losing 0.7% and 0.3% while staying below parity. See
    /// `set_x86_lea_writeback_collapse_enabled`.
    #[test]
    fn x86_lea_self_writeback_is_default_on_and_its_opt_out_restores_the_writeback() {
        crate::env_lock::with_env_overrides_removed(&["TCG_NO_X86_LEA_WRITEBACK_COLLAPSE"], || {
            assert!(
                x86_lea_writeback_collapse_enabled(),
                "the arm is DEFAULT ON; absent the opt-out it must fire"
            );
            let (mut func, entry) = lea_self_writeback_func("lea_self_writeback_default");
            let alloc: HashMap<VReg, X86PReg> = HashMap::new();
            assert_eq!(
                coalesce_x86_redundant_movrr_copies(&mut func, &alloc),
                1,
                "by default the writeback must be collapsed"
            );
            assert_eq!(func.blocks[&entry].insts.len(), 2);
        });
        crate::env_lock::with_env_overrides(&[("TCG_NO_X86_LEA_WRITEBACK_COLLAPSE", "1")], || {
            assert!(
                !x86_lea_writeback_collapse_enabled(),
                "the opt-out must disable the arm"
            );
            let (mut func, entry) = lea_self_writeback_func("lea_self_writeback_optout");
            let alloc: HashMap<VReg, X86PReg> = HashMap::new();
            assert_eq!(
                coalesce_x86_redundant_movrr_copies(&mut func, &alloc),
                0,
                "with the opt-out the writeback must survive"
            );
            assert_eq!(func.blocks[&entry].insts.len(), 3);
        });
    }

    /// The kill switch must be a real one-flag revert of the arm.
    #[test]
    fn x86_tied_copy_elide_kill_switch_reverts_the_arm() {
        crate::env_lock::with_env_overrides_removed(&["TCG_NO_X86_TIED_COPY_ELIDE"], || {
            assert!(x86_tied_copy_elide_enabled());
            let (mut func, entry) = tied_bridge_func("tied_copy_elide_on");
            let alloc: HashMap<VReg, X86PReg> = HashMap::new();
            assert_eq!(coalesce_x86_redundant_movrr_copies(&mut func, &alloc), 1);
            assert_eq!(func.blocks[&entry].insts.len(), 2);
        });
        crate::env_lock::with_env_overrides(&[("TCG_NO_X86_TIED_COPY_ELIDE", "1")], || {
            assert!(!x86_tied_copy_elide_enabled());
            let (mut func, entry) = tied_bridge_func("tied_copy_elide_off");
            let alloc: HashMap<VReg, X86PReg> = HashMap::new();
            assert_eq!(
                coalesce_x86_redundant_movrr_copies(&mut func, &alloc),
                0,
                "with the kill switch set the bridge must survive"
            );
            assert_eq!(func.blocks[&entry].insts.len(), 3);
        });
    }

    /// PINNED (bridge-into-LEA x TV-5): the collapse must REUSE the `AddRR`'s
    /// own operands, so the destination keeps its VREG identity.
    ///
    /// Regression test. The first version of this rewrite built the `LeaSib`
    /// out of freshly spelled `PReg`s. The register written is identical, so
    /// every differential run passed — but the destination VREG lost its
    /// definition at this instruction, and TV-5 then walks back to that vreg's
    /// previous def. With a call in between it reports
    /// `call-severed-vreg-read` and the compile FAILS CLOSED. That took out
    /// 7 of the 18 bench programs at -O2/-O3.
    ///
    /// Asserting on the emitted opcode alone would NOT catch it, so this pins
    /// the operands themselves and re-runs TV-5.
    #[test]
    fn x86_bridge_into_lea_preserves_vreg_identity() {
        use trust_cg_ir::x86_64_regs::{RBX, RCX, RDI, RDX};
        use trust_cg_verify::post_ra_dataflow;
        use trust_cg_verify::post_regalloc_recheck::PostRegallocRecheckMode;

        let entry = Block(0);
        let mut func = minimal_func("bridge_into_lea_vregs");
        let vr = |id| VReg::new(id, trust_cg_ir::regs::RegClass::Gpr64);
        let (d, a, b) = (vr(0), vr(1), vr(2));

        //   movq  a, d              <- the two-address bridge
        //   addq  d, ghost a, b     <- tied add
        //   addq  rdi, rdi, rdi     <- full CC definer, so the add's flags die
        //   ret
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![X86ISelOperand::VReg(d), X86ISelOperand::VReg(a)],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::AddRR,
                vec![
                    X86ISelOperand::VReg(d),
                    X86ISelOperand::VReg(a),
                    X86ISelOperand::VReg(b),
                ],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::AddRR,
                vec![
                    X86ISelOperand::PReg(RDI),
                    X86ISelOperand::PReg(RDI),
                    X86ISelOperand::PReg(RDI),
                ],
            ),
        );
        func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));

        let mut alloc: HashMap<VReg, X86PReg> = HashMap::new();
        alloc.insert(d, RCX);
        alloc.insert(a, RBX);
        alloc.insert(b, RDX);

        let removed = coalesce_x86_redundant_movrr_copies(&mut func, &alloc);
        assert_eq!(removed, 1, "the bridge copy must be collapsed into the LEA");

        let insts = &func.blocks[&entry].insts;
        assert_eq!(insts[0].opcode, X86Opcode::LeaSib);
        assert_eq!(
            insts[0].operands,
            vec![
                X86ISelOperand::VReg(d),
                X86ISelOperand::SibMemAddr {
                    base: Box::new(X86ISelOperand::VReg(a)),
                    index: Box::new(X86ISelOperand::VReg(b)),
                    scale: 1,
                    disp: 0,
                },
            ],
            "the LEA must carry the add's own VREG operands, not re-spelled PRegs \
             — re-spelling orphans the destination vreg's definition"
        );

        assert!(
            post_ra_dataflow::evaluate(&func, &alloc, "x86_64", PostRegallocRecheckMode::Enforce)
                .is_none(),
            "the collapsed stream must still discharge TV-5"
        );
    }

    /// PINNED (movrr-coalesce x TV-5, negative half): the GHOST-SKIPPING
    /// variant of the same transform — copy deleted, real reads renamed, ghost
    /// `operands[1]` left stale — is REFUTED by TV-5 with
    /// tied-operand-value-mismatch. This documents WHY the coalescer's ghost
    /// rename is mandatory (skipping it turns sound output into a spurious
    /// fail-closed compile error), i.e. the carve-out in
    /// trust-cg-verify::post_ra_dataflow is required, not merely permitted.
    #[test]
    fn x86_movrr_coalesce_ghost_skip_variant_refuted_by_tv5() {
        use trust_cg_ir::x86_64_regs::{RBX, RCX, RDX, RSI};
        use trust_cg_verify::post_ra_dataflow;
        use trust_cg_verify::post_regalloc_recheck::PostRegallocRecheckMode;

        let entry = Block(0);
        let mut func = minimal_func("movrr_ghost_skip");
        // Hand-built output of a HYPOTHETICAL ghost-skipping coalescer applied
        // to the stream in the green-half test above:
        //   movq %rbx, %rcx          (bridge renamed to the copy source)
        //   addq  [RCX, ghost=RSI(STALE), RDX]
        //   ret
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![X86ISelOperand::PReg(RCX), X86ISelOperand::PReg(RBX)],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::AddRR,
                vec![
                    X86ISelOperand::PReg(RCX),
                    X86ISelOperand::PReg(RSI),
                    X86ISelOperand::PReg(RDX),
                ],
            ),
        );
        func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));

        let alloc: HashMap<VReg, X86PReg> = HashMap::new();
        let violation =
            post_ra_dataflow::evaluate(&func, &alloc, "x86_64", PostRegallocRecheckMode::Enforce)
                .expect("a stale ghost sym after copy deletion must be refuted");
        assert_eq!(violation.kind.tag(), "tied-operand-value-mismatch");
    }

    /// PINNED (bail-on-bridge): a `MovRR` that is itself the arm-3 two-address
    /// bridge feeding a tied op is NEVER deleted — the scan classifies op0 of
    /// the tied form as a (partial, tied) machine read of the copy destination
    /// while the same instruction defines it, and bails before any mutation.
    #[test]
    fn x86_movrr_coalesce_never_deletes_tied_bridge() {
        use trust_cg_ir::x86_64_regs::{RBX, RCX, RDX};

        let entry = Block(0);
        let mut func = minimal_func("movrr_bridge_bail");
        //   movq %rbx, %rcx          (the bridge itself is the candidate)
        //   addq  [RCX, ghost=RBX, RDX]
        //   ret
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![X86ISelOperand::PReg(RCX), X86ISelOperand::PReg(RBX)],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::AddRR,
                vec![
                    X86ISelOperand::PReg(RCX),
                    X86ISelOperand::PReg(RBX),
                    X86ISelOperand::PReg(RDX),
                ],
            ),
        );
        func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));

        let alloc: HashMap<VReg, X86PReg> = HashMap::new();
        let removed = coalesce_x86_redundant_movrr_copies(&mut func, &alloc);
        assert_eq!(removed, 0, "a tied op's bridge copy must never be deleted");

        let insts = &func.blocks[&entry].insts;
        assert_eq!(insts.len(), 3, "stream must be untouched");
        assert_eq!(insts[0].opcode, X86Opcode::MovRR);
        assert_eq!(
            insts[0].operands,
            vec![X86ISelOperand::PReg(RCX), X86ISelOperand::PReg(RBX)]
        );
        assert_eq!(
            insts[1].operands[1],
            X86ISelOperand::PReg(RBX),
            "ghost untouched"
        );
    }

    // -----------------------------------------------------------------------
    // XMM bridge-copy collapse
    // -----------------------------------------------------------------------

    /// Build the v1_saxpy-shaped accept fixture: a `MovdqaRR` bridge feeding
    /// a tied `Paddd` whose ghost operand still names the bridge source, a
    /// downstream store reading the bridge destination, and a `Jmp` to a
    /// `Ret` block (so the copy block itself carries no call/return barrier).
    fn xmm_bridge_paddd_fixture() -> X86ISelFunction {
        use trust_cg_ir::x86_64_regs::{XMM2, XMM3, XMM8};

        let (b0, b1) = (Block(0), Block(1));
        let mut func = minimal_func("xmm_bridge_paddd");
        func.ensure_block(b1);
        //   movdqa %xmm2, %xmm3        (bridge: d=XMM3 <- s=XMM2)
        //   paddd  [XMM3, ghost=XMM2, XMM8]
        //   movdqu [%rax], %xmm3       (read of d)
        //   jmp b1
        // b1: ret
        func.push_inst(
            b0,
            X86ISelInst::new(
                X86Opcode::MovdqaRR,
                vec![X86ISelOperand::PReg(XMM3), X86ISelOperand::PReg(XMM2)],
            ),
        );
        func.push_inst(
            b0,
            X86ISelInst::new(
                X86Opcode::Paddd,
                vec![
                    X86ISelOperand::PReg(XMM3),
                    X86ISelOperand::PReg(XMM2),
                    X86ISelOperand::PReg(XMM8),
                ],
            ),
        );
        func.push_inst(
            b0,
            X86ISelInst::new(
                X86Opcode::MovdquMR,
                vec![
                    X86ISelOperand::MemAddr {
                        base: Box::new(X86ISelOperand::PReg(RAX)),
                        disp: 0,
                    },
                    X86ISelOperand::PReg(XMM3),
                ],
            ),
        );
        func.push_inst(
            b0,
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(b1)]),
        );
        func.push_inst(b1, X86ISelInst::new(X86Opcode::Ret, vec![]));
        func.blocks.get_mut(&b0).unwrap().successors = vec![b1];
        func
    }

    /// ACCEPT (v1-shape): the `MovdqaRR` bridge before a tied `Paddd` whose
    /// source is dead after the op is deleted, the op becomes self-tied on
    /// the bridge SOURCE, downstream reads of the bridge destination are
    /// renamed in lockstep, and the transformed stream still discharges TV-5.
    #[test]
    fn x86_xmm_bridge_collapse_paddd_accept() {
        use trust_cg_ir::x86_64_regs::{XMM2, XMM8};
        use trust_cg_verify::post_ra_dataflow;
        use trust_cg_verify::post_regalloc_recheck::PostRegallocRecheckMode;

        crate::env_lock::with_env_overrides_removed(&["TCG_NO_X86_XMM_BRIDGE_COLLAPSE"], || {
            let mut func = xmm_bridge_paddd_fixture();
            let alloc: HashMap<VReg, X86PReg> = HashMap::new();
            let removed = coalesce_x86_redundant_movrr_copies(&mut func, &alloc);
            assert_eq!(removed, 1, "the XMM bridge copy must be collapsed");

            let insts = &func.blocks[&Block(0)].insts;
            assert_eq!(insts.len(), 3, "bridge deleted; op + store + jmp remain");
            assert_eq!(insts[0].opcode, X86Opcode::Paddd);
            assert_eq!(
                insts[0].operands,
                vec![
                    X86ISelOperand::PReg(XMM2),
                    X86ISelOperand::PReg(XMM2),
                    X86ISelOperand::PReg(XMM8),
                ],
                "the op must be self-tied on the bridge source (dst == ghost)"
            );
            assert_eq!(insts[1].opcode, X86Opcode::MovdquMR);
            assert_eq!(
                insts[1].operands[1],
                X86ISelOperand::PReg(XMM2),
                "the downstream read of the bridge destination must be renamed"
            );

            assert!(
                post_ra_dataflow::evaluate(
                    &func,
                    &alloc,
                    "x86_64",
                    PostRegallocRecheckMode::Enforce
                )
                .is_none(),
                "the collapsed stream must still discharge TV-5"
            );
        });
    }

    /// DECLINE (source redefined before a renamed read): a fresh load INTO
    /// the bridge source between the tied op and a read of the bridge
    /// destination makes the rename unsound — the source no longer carries
    /// the op's result when the read executes.
    #[test]
    fn x86_xmm_bridge_collapse_pmulld_declines_on_src_redef() {
        use trust_cg_ir::x86_64_regs::{RCX, XMM2, XMM3, XMM8};

        crate::env_lock::with_env_overrides_removed(&["TCG_NO_X86_XMM_BRIDGE_COLLAPSE"], || {
            let entry = Block(0);
            let mut func = minimal_func("xmm_bridge_src_redef");
            //   movdqa %xmm2, %xmm3        (bridge: d=XMM3 <- s=XMM2)
            //   pmulld [XMM3, ghost=XMM2, XMM8]
            //   movdqu %xmm2, [%rax]       (a NEW load into s: full redef)
            //   movdqu [%rcx], %xmm3       (read of d AFTER the s redef)
            func.push_inst(
                entry,
                X86ISelInst::new(
                    X86Opcode::MovdqaRR,
                    vec![X86ISelOperand::PReg(XMM3), X86ISelOperand::PReg(XMM2)],
                ),
            );
            func.push_inst(
                entry,
                X86ISelInst::new(
                    X86Opcode::Pmulld,
                    vec![
                        X86ISelOperand::PReg(XMM3),
                        X86ISelOperand::PReg(XMM2),
                        X86ISelOperand::PReg(XMM8),
                    ],
                ),
            );
            func.push_inst(
                entry,
                X86ISelInst::new(
                    X86Opcode::MovdquRM,
                    vec![
                        X86ISelOperand::PReg(XMM2),
                        X86ISelOperand::MemAddr {
                            base: Box::new(X86ISelOperand::PReg(RAX)),
                            disp: 0,
                        },
                    ],
                ),
            );
            func.push_inst(
                entry,
                X86ISelInst::new(
                    X86Opcode::MovdquMR,
                    vec![
                        X86ISelOperand::MemAddr {
                            base: Box::new(X86ISelOperand::PReg(RCX)),
                            disp: 0,
                        },
                        X86ISelOperand::PReg(XMM3),
                    ],
                ),
            );

            let alloc: HashMap<VReg, X86PReg> = HashMap::new();
            let removed = coalesce_x86_redundant_movrr_copies(&mut func, &alloc);
            assert_eq!(removed, 0, "src redef before a read of dst must decline");

            let insts = &func.blocks[&entry].insts;
            assert_eq!(insts.len(), 4, "stream must be untouched");
            assert_eq!(insts[0].opcode, X86Opcode::MovdqaRR);
            assert_eq!(
                insts[0].operands,
                vec![X86ISelOperand::PReg(XMM3), X86ISelOperand::PReg(XMM2)]
            );
            assert_eq!(
                insts[1].operands[0],
                X86ISelOperand::PReg(XMM3),
                "the op destination must be untouched"
            );
            assert_eq!(
                insts[3].operands[1],
                X86ISelOperand::PReg(XMM3),
                "the read of the bridge destination must be untouched"
            );
        });
    }

    /// FIXPOINT (two bridges, p4-shape): the punpcklqdq bridge is declined in
    /// sweep 1 because its SOURCE is redefined by the paddq bridge's copy
    /// before a read of its destination. The paddq bridge collapses in sweep
    /// 1, which deletes that copy — and only the sweep-2 rescan of the
    /// rebuilt stream can see the punpcklqdq bridge become legal.
    #[test]
    fn x86_xmm_bridge_collapse_two_bridge_fixpoint() {
        use trust_cg_ir::x86_64_regs::{XMM1, XMM2, XMM3, XMM8, XMM14};

        crate::env_lock::with_env_overrides_removed(&["TCG_NO_X86_XMM_BRIDGE_COLLAPSE"], || {
            let entry = Block(0);
            let mut func = minimal_func("xmm_bridge_fixpoint");
            //   movdqa %xmm2, %xmm3          (bridge A: d=XMM3 <- s=XMM2)
            //   punpcklqdq [XMM3, ghost=XMM2, XMM8]
            //   movdqa %xmm1, %xmm2          (bridge B: d=XMM2 <- s=XMM1;
            //                                 REDEFINES bridge A's source)
            //   paddq  [XMM2, ghost=XMM1, XMM14]
            //   movdqu [%rax], %xmm3         (read of A's d, after A's s redef)
            //   movdqu [%rax+16], %xmm2      (read of B's d)
            func.push_inst(
                entry,
                X86ISelInst::new(
                    X86Opcode::MovdqaRR,
                    vec![X86ISelOperand::PReg(XMM3), X86ISelOperand::PReg(XMM2)],
                ),
            );
            func.push_inst(
                entry,
                X86ISelInst::new(
                    X86Opcode::Punpcklqdq,
                    vec![
                        X86ISelOperand::PReg(XMM3),
                        X86ISelOperand::PReg(XMM2),
                        X86ISelOperand::PReg(XMM8),
                    ],
                ),
            );
            func.push_inst(
                entry,
                X86ISelInst::new(
                    X86Opcode::MovdqaRR,
                    vec![X86ISelOperand::PReg(XMM2), X86ISelOperand::PReg(XMM1)],
                ),
            );
            func.push_inst(
                entry,
                X86ISelInst::new(
                    X86Opcode::Paddq,
                    vec![
                        X86ISelOperand::PReg(XMM2),
                        X86ISelOperand::PReg(XMM1),
                        X86ISelOperand::PReg(XMM14),
                    ],
                ),
            );
            func.push_inst(
                entry,
                X86ISelInst::new(
                    X86Opcode::MovdquMR,
                    vec![
                        X86ISelOperand::MemAddr {
                            base: Box::new(X86ISelOperand::PReg(RAX)),
                            disp: 0,
                        },
                        X86ISelOperand::PReg(XMM3),
                    ],
                ),
            );
            func.push_inst(
                entry,
                X86ISelInst::new(
                    X86Opcode::MovdquMR,
                    vec![
                        X86ISelOperand::MemAddr {
                            base: Box::new(X86ISelOperand::PReg(RAX)),
                            disp: 16,
                        },
                        X86ISelOperand::PReg(XMM2),
                    ],
                ),
            );

            let alloc: HashMap<VReg, X86PReg> = HashMap::new();
            let removed = coalesce_x86_redundant_movrr_copies(&mut func, &alloc);
            assert_eq!(removed, 2, "both bridges must collapse across two sweeps");

            let insts = &func.blocks[&entry].insts;
            assert_eq!(insts.len(), 4, "both bridge copies deleted");
            assert_eq!(insts[0].opcode, X86Opcode::Punpcklqdq);
            assert_eq!(
                insts[0].operands,
                vec![
                    X86ISelOperand::PReg(XMM2),
                    X86ISelOperand::PReg(XMM2),
                    X86ISelOperand::PReg(XMM8),
                ],
                "sweep 2: the punpcklqdq must be self-tied on its bridge source"
            );
            assert_eq!(insts[1].opcode, X86Opcode::Paddq);
            assert_eq!(
                insts[1].operands,
                vec![
                    X86ISelOperand::PReg(XMM1),
                    X86ISelOperand::PReg(XMM1),
                    X86ISelOperand::PReg(XMM14),
                ],
                "sweep 1: the paddq must be self-tied on its bridge source"
            );
            assert_eq!(
                insts[2].operands[1],
                X86ISelOperand::PReg(XMM2),
                "the read of punpcklqdq's old destination must be renamed"
            );
            assert_eq!(
                insts[3].operands[1],
                X86ISelOperand::PReg(XMM1),
                "the read of paddq's old destination must be renamed"
            );
        });
    }

    /// DECLINE (live-out): the bridge source is live into a successor block
    /// and never fully redefined in the copy block, so its value must
    /// survive the op — the collapse would overwrite it.
    #[test]
    fn x86_xmm_bridge_collapse_declines_live_out_source() {
        use trust_cg_ir::x86_64_regs::{XMM2, XMM3, XMM8};

        crate::env_lock::with_env_overrides_removed(&["TCG_NO_X86_XMM_BRIDGE_COLLAPSE"], || {
            let (b0, b1) = (Block(0), Block(1));
            let mut func = minimal_func("xmm_bridge_live_out");
            func.ensure_block(b1);
            // b0:  movdqa %xmm2, %xmm3
            //      paddd  [XMM3, ghost=XMM2, XMM8]
            //      jmp b1
            // b1:  movdqu [%rax], %xmm2      (s read in the successor)
            func.push_inst(
                b0,
                X86ISelInst::new(
                    X86Opcode::MovdqaRR,
                    vec![X86ISelOperand::PReg(XMM3), X86ISelOperand::PReg(XMM2)],
                ),
            );
            func.push_inst(
                b0,
                X86ISelInst::new(
                    X86Opcode::Paddd,
                    vec![
                        X86ISelOperand::PReg(XMM3),
                        X86ISelOperand::PReg(XMM2),
                        X86ISelOperand::PReg(XMM8),
                    ],
                ),
            );
            func.push_inst(
                b0,
                X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(b1)]),
            );
            func.push_inst(
                b1,
                X86ISelInst::new(
                    X86Opcode::MovdquMR,
                    vec![
                        X86ISelOperand::MemAddr {
                            base: Box::new(X86ISelOperand::PReg(RAX)),
                            disp: 0,
                        },
                        X86ISelOperand::PReg(XMM2),
                    ],
                ),
            );
            func.blocks.get_mut(&b0).unwrap().successors = vec![b1];

            let alloc: HashMap<VReg, X86PReg> = HashMap::new();
            let removed = coalesce_x86_redundant_movrr_copies(&mut func, &alloc);
            assert_eq!(removed, 0, "a live-out source must decline the collapse");
            assert_eq!(func.blocks[&b0].insts.len(), 3, "stream must be untouched");
            assert_eq!(func.blocks[&b0].insts[0].opcode, X86Opcode::MovdqaRR);
        });
    }

    /// DECLINE (partial def is a read barrier): `MovssRR` into the bridge
    /// source merges the untouched upper lanes — it READS the old value, so
    /// it can neither kill the source nor be scanned past. (`Pinsrd`/
    /// `Pinsrq` are the other partial-def opcodes; both are likewise
    /// excluded from `x86_opcode_full_xmm_def`.)
    #[test]
    fn x86_xmm_bridge_collapse_partial_def_barrier_declines() {
        use trust_cg_ir::x86_64_regs::{XMM2, XMM3, XMM8, XMM14};

        crate::env_lock::with_env_overrides_removed(&["TCG_NO_X86_XMM_BRIDGE_COLLAPSE"], || {
            let entry = Block(0);
            let mut func = minimal_func("xmm_bridge_partial_def");
            //   movdqa %xmm2, %xmm3
            //   paddd  [XMM3, ghost=XMM2, XMM8]
            //   movss  %xmm14, %xmm2       (PARTIAL def of s: lane-0 merge)
            func.push_inst(
                entry,
                X86ISelInst::new(
                    X86Opcode::MovdqaRR,
                    vec![X86ISelOperand::PReg(XMM3), X86ISelOperand::PReg(XMM2)],
                ),
            );
            func.push_inst(
                entry,
                X86ISelInst::new(
                    X86Opcode::Paddd,
                    vec![
                        X86ISelOperand::PReg(XMM3),
                        X86ISelOperand::PReg(XMM2),
                        X86ISelOperand::PReg(XMM8),
                    ],
                ),
            );
            func.push_inst(
                entry,
                X86ISelInst::new(
                    X86Opcode::MovssRR,
                    vec![X86ISelOperand::PReg(XMM2), X86ISelOperand::PReg(XMM14)],
                ),
            );

            let alloc: HashMap<VReg, X86PReg> = HashMap::new();
            let removed = coalesce_x86_redundant_movrr_copies(&mut func, &alloc);
            assert_eq!(removed, 0, "a partial def of the source must decline");
            assert_eq!(
                func.blocks[&entry].insts.len(),
                3,
                "stream must be untouched"
            );
            assert_eq!(func.blocks[&entry].insts[0].opcode, X86Opcode::MovdqaRR);
        });
    }

    /// DECLINE (implicit XMM behavior in the window): `Pblendvb` reads XMM0
    /// without naming it, so no rename over a window containing it can be
    /// trusted. The identical stream WITHOUT the `Pblendvb` collapses,
    /// pinning the decline to the implicit-XMM instruction itself.
    #[test]
    fn x86_xmm_bridge_collapse_pblendvb_window_declines() {
        use trust_cg_ir::x86_64_regs::{XMM2, XMM3, XMM8, XMM14, XMM15};

        crate::env_lock::with_env_overrides_removed(&["TCG_NO_X86_XMM_BRIDGE_COLLAPSE"], || {
            let build = |with_pblendvb: bool| {
                let entry = Block(0);
                let mut func = minimal_func("xmm_bridge_pblendvb");
                func.push_inst(
                    entry,
                    X86ISelInst::new(
                        X86Opcode::MovdqaRR,
                        vec![X86ISelOperand::PReg(XMM3), X86ISelOperand::PReg(XMM2)],
                    ),
                );
                func.push_inst(
                    entry,
                    X86ISelInst::new(
                        X86Opcode::Paddd,
                        vec![
                            X86ISelOperand::PReg(XMM3),
                            X86ISelOperand::PReg(XMM2),
                            X86ISelOperand::PReg(XMM8),
                        ],
                    ),
                );
                if with_pblendvb {
                    func.push_inst(
                        entry,
                        X86ISelInst::new(
                            X86Opcode::Pblendvb,
                            vec![X86ISelOperand::PReg(XMM14), X86ISelOperand::PReg(XMM15)],
                        ),
                    );
                }
                func.push_inst(
                    entry,
                    X86ISelInst::new(
                        X86Opcode::MovdquMR,
                        vec![
                            X86ISelOperand::MemAddr {
                                base: Box::new(X86ISelOperand::PReg(RAX)),
                                disp: 0,
                            },
                            X86ISelOperand::PReg(XMM3),
                        ],
                    ),
                );
                func
            };
            let alloc: HashMap<VReg, X86PReg> = HashMap::new();

            let mut with_pblendvb = build(true);
            let removed = coalesce_x86_redundant_movrr_copies(&mut with_pblendvb, &alloc);
            assert_eq!(removed, 0, "an implicit-XMM window must decline");
            assert_eq!(
                with_pblendvb.blocks[&Block(0)].insts[0].opcode,
                X86Opcode::MovdqaRR,
                "the bridge must survive"
            );

            let mut without_pblendvb = build(false);
            let removed = coalesce_x86_redundant_movrr_copies(&mut without_pblendvb, &alloc);
            assert_eq!(
                removed, 1,
                "the identical stream without Pblendvb must collapse"
            );
        });
    }

    /// Kill switch: `TCG_NO_X86_XMM_BRIDGE_COLLAPSE` disables ONLY the XMM
    /// arm — the bridge copy survives untouched — and the default (unset)
    /// collapses the same stream.
    #[test]
    fn x86_xmm_bridge_collapse_kill_switch() {
        use trust_cg_ir::x86_64_regs::XMM3;

        crate::env_lock::with_env_overrides(&[("TCG_NO_X86_XMM_BRIDGE_COLLAPSE", "1")], || {
            let mut func = xmm_bridge_paddd_fixture();
            let alloc: HashMap<VReg, X86PReg> = HashMap::new();
            let removed = coalesce_x86_redundant_movrr_copies(&mut func, &alloc);
            assert_eq!(removed, 0, "the kill switch must disable the XMM arm");
            let insts = &func.blocks[&Block(0)].insts;
            assert_eq!(insts.len(), 4, "stream must be untouched");
            assert_eq!(insts[0].opcode, X86Opcode::MovdqaRR);
            assert_eq!(insts[1].operands[0], X86ISelOperand::PReg(XMM3));
        });
        crate::env_lock::with_env_overrides_removed(&["TCG_NO_X86_XMM_BRIDGE_COLLAPSE"], || {
            let mut func = xmm_bridge_paddd_fixture();
            let alloc: HashMap<VReg, X86PReg> = HashMap::new();
            let removed = coalesce_x86_redundant_movrr_copies(&mut func, &alloc);
            assert_eq!(removed, 1, "default-on: the same stream must collapse");
        });
    }

    /// PINNED (mirror drift): the coalescer's implicit-register model
    /// `x86_inst_implicit_gpr64_roots` must agree with regalloc's
    /// `add_x86_fixed_implicit_operands` at GPR64-root granularity over every
    /// opcode either side names, plus a no-implicit control set — the same
    /// pattern as TV-5's `post_ra_tied_lhs_index` mirror pin. If you add an
    /// opcode with implicit fixed GPRs to `add_x86_fixed_implicit_operands`,
    /// add it HERE and mirror it in `x86_inst_implicit_gpr64_roots` (an
    /// unmirrored implicit use could otherwise let the coalescer rename a
    /// read the mirror cannot see). Call/return conventions are excluded:
    /// the mirror models them separately from `call_arg_regs`/return-reg
    /// facts and treats calls as hard barriers regardless.
    #[test]
    fn x86_movrr_implicit_gpr64_mirror_agrees_with_regalloc_model() {
        use std::collections::BTreeSet;
        use trust_cg_regalloc::x86_adapter::preg_to_x86;

        fn mirror_roots(inst: &X86ISelInst) -> (BTreeSet<&'static str>, BTreeSet<&'static str>) {
            let mut uses = Vec::new();
            let mut defs = Vec::new();
            x86_inst_implicit_gpr64_roots(inst, &mut uses, &mut defs);
            let name_set = |v: &[X86PReg]| {
                v.iter()
                    .map(|&r| x86_64_regs::x86_preg_name(r))
                    .collect::<BTreeSet<_>>()
            };
            (name_set(&uses), name_set(&defs))
        }

        fn regalloc_roots(inst: &X86ISelInst) -> (BTreeSet<&'static str>, BTreeSet<&'static str>) {
            let mut implicit_defs = Vec::new();
            let mut implicit_uses = Vec::new();
            add_x86_fixed_implicit_operands(inst, &mut implicit_defs, &mut implicit_uses);
            let name_set = |v: &[trust_cg_regalloc::PReg]| {
                v.iter()
                    .filter_map(|&p| preg_to_x86(p))
                    .filter_map(x86_64_regs::x86_containing_gpr64)
                    .map(x86_64_regs::x86_preg_name)
                    .collect::<BTreeSet<_>>()
            };
            (name_set(&implicit_uses), name_set(&implicit_defs))
        }

        let gpr32_first_operand = || vec![X86ISelOperand::VReg(VReg::new(0, RegClass::Gpr32))];

        // Every opcode named by either implicit-register model, each in the
        // operand shapes that change its fixed-register selection, plus
        // representative no-implicit controls.
        let cases: Vec<(X86Opcode, Vec<X86ISelOperand>)> = vec![
            (X86Opcode::Cdq, vec![]),
            (X86Opcode::Cqo, vec![]),
            (X86Opcode::ShlRR, vec![]),
            (X86Opcode::ShrRR, vec![]),
            (X86Opcode::SarRR, vec![]),
            (X86Opcode::RolRCl, vec![]),
            (X86Opcode::Idiv, vec![]),
            (X86Opcode::Idiv, gpr32_first_operand()),
            (X86Opcode::Div, vec![]),
            (X86Opcode::Div, gpr32_first_operand()),
            (X86Opcode::Mul, vec![]),
            (X86Opcode::Mul, gpr32_first_operand()),
            (X86Opcode::Cmpxchg, vec![]),
            (X86Opcode::Cmpxchg, gpr32_first_operand()),
            (X86Opcode::AtomicRmwCasLoop, vec![]),
            (X86Opcode::AtomicRmwCasLoop, gpr32_first_operand()),
            (X86Opcode::AtomicRmwCasLoop8, vec![]),
            (X86Opcode::AtomicRmwCasLoop16, vec![]),
            (X86Opcode::Pblendvb, vec![]),
            // No-implicit controls: both models must agree on EMPTY.
            (X86Opcode::AddRR, vec![]),
            (X86Opcode::SubRR, vec![]),
            (X86Opcode::ImulRR, vec![]),
            (X86Opcode::XorRR, vec![]),
            (X86Opcode::MovRR, vec![]),
        ];

        for (opcode, operands) in cases {
            let inst = X86ISelInst::new(opcode, operands);
            let (m_uses, m_defs) = mirror_roots(&inst);
            let (r_uses, r_defs) = regalloc_roots(&inst);
            assert_eq!(
                m_uses, r_uses,
                "implicit GPR64-root USE mirror drift on {opcode:?} (operands {:?})",
                inst.operands
            );
            assert_eq!(
                m_defs, r_defs,
                "implicit GPR64-root DEF mirror drift on {opcode:?} (operands {:?})",
                inst.operands
            );
        }
    }

    /// PINNED (mirror drift): TV-5 Stage A's verify-owned commutativity
    /// mirror (`post_ra_spec_commutative_two_address_rr`) must agree with
    /// codegen's `is_x86_commutative_two_address_rr` over the entire
    /// two-address opcode surface (and representative non-two-address
    /// controls). Drift in either direction is a correctness hazard for the
    /// captured-spec check: OVER-inclusion could accept a swapped
    /// non-commutative op as sound; under-inclusion would refute a sound
    /// commutative swap (a false positive under enforce).
    #[test]
    fn x86_captured_spec_commutative_mirror_agrees_with_codegen() {
        use trust_cg_verify::post_ra_captured_spec::post_ra_spec_commutative_two_address_rr;

        let two_address: Vec<X86Opcode> = vec![
            X86Opcode::AddRR,
            X86Opcode::SubRR,
            X86Opcode::AdcRR,
            X86Opcode::SbbRR,
            X86Opcode::AndRR,
            X86Opcode::OrRR,
            X86Opcode::XorRR,
            X86Opcode::ImulRR,
            X86Opcode::Addsd,
            X86Opcode::Subsd,
            X86Opcode::Mulsd,
            X86Opcode::Divsd,
            X86Opcode::Andpd,
            X86Opcode::Addss,
            X86Opcode::Subss,
            X86Opcode::Mulss,
            X86Opcode::Divss,
            X86Opcode::Andps,
            X86Opcode::Pand,
            X86Opcode::Pandn,
            X86Opcode::Por,
            X86Opcode::Pxor,
            X86Opcode::Pcmpeqb,
            X86Opcode::Pcmpeqw,
            X86Opcode::Pcmpgtb,
            X86Opcode::Pcmpgtw,
            X86Opcode::Pcmpeqd,
            X86Opcode::Pcmpgtd,
            X86Opcode::Paddb,
            X86Opcode::Paddw,
            X86Opcode::Paddd,
            X86Opcode::Psubb,
            X86Opcode::Psubw,
            X86Opcode::Psubd,
            X86Opcode::Paddq,
            X86Opcode::Psubq,
            X86Opcode::Pmullw,
            X86Opcode::Pmuludq,
            X86Opcode::Punpcklbw,
            X86Opcode::Punpckldq,
            X86Opcode::Packuswb,
            X86Opcode::Punpckhbw,
            X86Opcode::Punpcklqdq,
            X86Opcode::Pmulld,
            X86Opcode::Pcmpeqq,
            X86Opcode::Pcmpgtq,
            X86Opcode::Addps,
            X86Opcode::Subps,
            X86Opcode::Mulps,
            X86Opcode::Divps,
            X86Opcode::Addpd,
            X86Opcode::Subpd,
            X86Opcode::Mulpd,
            X86Opcode::Divpd,
            X86Opcode::Minsd,
            X86Opcode::Maxsd,
            X86Opcode::Minss,
            X86Opcode::Maxss,
            X86Opcode::Cmpsd,
            X86Opcode::Cmpss,
            // Non-two-address controls (must be false on both sides).
            X86Opcode::MovRR,
            X86Opcode::MovRI,
            X86Opcode::CmpRR,
            X86Opcode::TestRR,
            X86Opcode::Lea,
            X86Opcode::Idiv,
        ];
        for opcode in two_address {
            assert_eq!(
                post_ra_spec_commutative_two_address_rr(opcode),
                is_x86_commutative_two_address_rr(opcode),
                "commutativity mirror drift on {opcode:?}"
            );
        }
    }

    /// The jump-table dispatch `emit_x86_jump_table` emits:
    /// `LeaRip base; MovRMSib off, [base + norm*8]; AddRR [off, base];
    /// JmpR [off]`. Returns `(func, base, off)`.
    fn jump_table_dispatch_fixture() -> (X86ISelFunction, VReg, VReg) {
        let mut func = minimal_func("jump_table_dispatch");
        let entry = Block(0);
        let norm = VReg::new(0, RegClass::Gpr64);
        let base = VReg::new(1, RegClass::Gpr64);
        let off = VReg::new(2, RegClass::Gpr64);
        func.next_vreg = 3;
        for inst in [
            X86ISelInst::new(
                X86Opcode::MovRR,
                vec![X86ISelOperand::VReg(norm), X86ISelOperand::PReg(RDI)],
            ),
            X86ISelInst::new(
                X86Opcode::LeaRip,
                vec![
                    X86ISelOperand::VReg(base),
                    X86ISelOperand::JumpTableIndex(0),
                ],
            ),
            X86ISelInst::new(
                X86Opcode::MovRMSib,
                vec![
                    X86ISelOperand::VReg(off),
                    X86ISelOperand::SibMemAddr {
                        base: Box::new(X86ISelOperand::VReg(base)),
                        index: Box::new(X86ISelOperand::VReg(norm)),
                        scale: 8,
                        disp: 0,
                    },
                ],
            ),
            X86ISelInst::new(
                X86Opcode::AddRR,
                vec![X86ISelOperand::VReg(off), X86ISelOperand::VReg(base)],
            ),
            X86ISelInst::new(X86Opcode::JmpR, vec![X86ISelOperand::VReg(off)]),
        ] {
            func.push_inst(entry, inst);
        }
        (func, base, off)
    }

    /// `JmpR [target]` READS its target. `opcode_has_def` used to end in
    /// `_ => true` without naming `JmpR`, so the allocator saw the jump-table
    /// target defined (dead) at the jump and read nowhere after the tied add.
    #[test]
    fn regalloc_reads_the_indirect_jump_target() {
        let (func, base, off) = jump_table_dispatch_fixture();

        let ra = x86_isel_to_regalloc(&func).unwrap();

        let jump = &ra.insts[4];
        assert_eq!(jump.opcode, X86Opcode::JmpR as u16);
        assert_eq!(jump.uses, vec![RegAllocOperand::VReg(off)]);
        assert!(jump.defs.is_empty(), "JmpR defines nothing: {jump:?}");
        let add = &ra.insts[3];
        assert_eq!(add.defs, vec![RegAllocOperand::VReg(off)]);
        assert_eq!(
            add.uses,
            vec![RegAllocOperand::VReg(off), RegAllocOperand::VReg(base)],
            "the tied AddRR [off, base] reads both registers"
        );
    }

    /// A spilled jump target must be reloaded BEFORE the indirect jump. With
    /// `JmpR` modelled as a def, spill materialization emitted no reload (the
    /// jump read an unwritten scratch register) and appended a store AFTER the
    /// terminator.
    #[test]
    fn spill_materialization_reloads_a_spilled_indirect_jump_target() {
        let (mut func, _base, off) = jump_table_dispatch_fixture();
        func.stack_slots.push(StackSlotInfo::new(8, 8));

        let installed_spills = HashMap::from([(off, 0)]);
        materialize_x86_spills(&mut func, &installed_spills, X86CallAbi::SystemV).unwrap();

        let insts = entry_insts(&func);
        let jump = insts.last().expect("block keeps its terminator");
        assert_eq!(
            jump.opcode,
            X86Opcode::JmpR,
            "nothing may follow the indirect jump: {insts:#?}"
        );
        let [X86ISelOperand::PReg(target)] = jump.operands.as_slice() else {
            panic!("the spilled target is rewritten to a scratch register: {jump:?}");
        };
        let reload = &insts[insts.len() - 2];
        assert_eq!(
            reload.opcode,
            X86Opcode::MovRM,
            "the jump must be preceded by a reload of its target: {insts:#?}"
        );
        assert_eq!(
            reload.operands,
            vec![X86ISelOperand::PReg(*target), x86_spill_stack_mem(0)]
        );
    }

    /// `opcode_has_def` agrees with the shared exhaustive classifier
    /// `trust_cg_opt::effects::x86_produces_value`, including the control
    /// transfers and trap carriers the old `_ => true` default answered
    /// wrongly, and `StackAlloc`, which the two used to disagree on.
    #[test]
    fn opcode_has_def_matches_the_shared_classifier() {
        for opcode in [
            X86Opcode::JmpR,
            X86Opcode::Jmp,
            X86Opcode::CallR,
            X86Opcode::TrapBoundsCheckExact,
            X86Opcode::TrapNullIfZeroExact,
            X86Opcode::TrapDivZeroExact,
            X86Opcode::TrapShiftRangeExact,
        ] {
            assert!(!opcode_has_def(opcode), "{opcode:?} defines no register");
        }
        for opcode in [
            X86Opcode::JmpR,
            X86Opcode::StackAlloc,
            X86Opcode::TrapDivZeroExact,
            X86Opcode::AddRR,
            X86Opcode::MovMR,
        ] {
            assert_eq!(
                opcode_has_def(opcode),
                trust_cg_opt::effects::x86_produces_value(opcode),
                "{opcode:?}"
            );
        }
        assert!(opcode_has_def(X86Opcode::StackAlloc));
    }

    /// The in-place immediate shifts and rotates `[d, imm]` read `d` (the
    /// encoder emits `op d, imm`), exactly like `ShlRI [d, imm]`; the
    /// three-address `[d, s, imm]` form only writes `d`.
    #[test]
    fn regalloc_ties_every_in_place_immediate_shift() {
        for opcode in [
            X86Opcode::ShlRI,
            X86Opcode::ShrRI,
            X86Opcode::SarRI,
            X86Opcode::RolRI,
            X86Opcode::Pslld,
            X86Opcode::Psrld,
            X86Opcode::Psrad,
            X86Opcode::Psllq,
            X86Opcode::Psrlq,
        ] {
            let d = X86ISelOperand::VReg(VReg::new(0, RegClass::Gpr64));
            let s = X86ISelOperand::VReg(VReg::new(1, RegClass::Gpr64));
            let tied = X86ISelInst::new(opcode, vec![d.clone(), X86ISelOperand::Imm(3)]);
            let access = x86_operand_access(&tied, 0);
            assert!(access.is_def && access.is_use, "{opcode:?} [d, imm]");
            let three = X86ISelInst::new(opcode, vec![d, s, X86ISelOperand::Imm(3)]);
            let access = x86_operand_access(&three, 0);
            assert!(access.is_def && !access.is_use, "{opcode:?} [d, s, imm]");
        }
    }

    /// Every form the allocator ties is a may-read for the machine passes:
    /// `trust_cg_opt::effects::x86_operand0_may_be_read` over-approximates
    /// this tie, so no x86 pass treats as dead a value the allocator keeps
    /// live through a tied operand 0. The list is every opcode with a
    /// non-constant or `true` arm in `first_operand_is_def_and_use`.
    #[test]
    fn every_regalloc_tie_is_a_machine_pass_may_read() {
        use X86Opcode::*;

        let mut ties = 0;
        for opcode in [
            AddRR, SubRR, AdcRR, SbbRR, AndRR, OrRR, XorRR, ImulRR, Addsd, Subsd, Mulsd, Divsd,
            Andpd, Addss, Subss, Mulss, Divss, Andps, Minsd, Maxsd, Minss, Maxss, Cmpsd, Cmpss,
            Pand, Pandn, Por, Pxor, Pcmpeqb, Pcmpeqw, Pcmpgtb, Pcmpgtw, Pcmpeqd, Pcmpgtd, Paddb,
            Paddw, Paddd, Psubb, Psubw, Psubd, Paddq, Psubq, Pmullw, Pmuludq, Punpcklbw, Punpckldq,
            Packuswb, Punpckhbw, Punpcklqdq, Pmulld, Psadbw, Pcmpeqq, Pcmpgtq, Addps, Subps, Mulps,
            Divps, Addpd, Subpd, Mulpd, Divpd, AddRI, SubRI, AndRI, OrRI, XorRI, ShlRI, ShrRI,
            SarRI, RolRI, Pslld, Psrld, Psrad, Psllq, Psrlq, AddRM, SubRM, ImulRM, ImulRMSib,
            Pinsrd, Pinsrq, Neg, Not, ShlRR, ShrRR, SarRR, RolRCl, Inc, Dec, Bswap, Cmovcc,
            Cmovcc32, Pblendvb, Xchg, Cmpxchg, Cmpxchg8, Cmpxchg16,
        ] {
            for operand_count in 0..=4u32 {
                let inst = X86ISelInst::new(
                    opcode,
                    (0..operand_count)
                        .map(|id| X86ISelOperand::VReg(VReg::new(id, RegClass::Gpr64)))
                        .collect(),
                );
                if opcode_has_def(opcode) && first_operand_is_def_and_use(&inst) {
                    ties += 1;
                    assert!(
                        trust_cg_opt::effects::x86_operand0_may_be_read(&inst),
                        "{opcode:?} with {operand_count} operands is tied for regalloc"
                    );
                }
            }
        }
        assert!(ties > 90, "only {ties} tied forms checked");
    }

    // -----------------------------------------------------------------------
    // Post-RA redundant spill-reload elision
    // -----------------------------------------------------------------------

    /// Build the shape the spiller produces for two consecutive instructions
    /// that each read ONE spilled vreg: `mov R10,[slot]` in front of each. The
    /// function is run through the REAL `materialize_x86_spills`, so the test
    /// pins what the spiller actually emits rather than a hand-written guess.
    fn reload_elide_fixture(
        extra: Vec<X86ISelInst>,
    ) -> (X86ISelFunction, HashMap<VReg, u32>, HashMap<VReg, X86PReg>) {
        use trust_cg_ir::x86_64_regs::{RAX, RCX, RDX};

        let mut func = minimal_func("reload_elide");
        let entry = Block(0);
        let spilled = VReg::new(0, RegClass::Gpr64);
        let a = VReg::new(1, RegClass::Gpr64);
        let b = VReg::new(2, RegClass::Gpr64);
        func.next_vreg = 3;
        func.stack_slots.push(StackSlotInfo::new(8, 8));

        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::AddRR,
                vec![X86ISelOperand::VReg(a), X86ISelOperand::VReg(spilled)],
            ),
        );
        for inst in extra {
            func.push_inst(entry, inst);
        }
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::AddRR,
                vec![X86ISelOperand::VReg(b), X86ISelOperand::VReg(spilled)],
            ),
        );
        func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));

        let installed = HashMap::from([(spilled, 0u32)]);
        // A COMPLETE allocation: rule 1b clears the map on any def this pass
        // cannot resolve, so an incomplete map would make every test vacuous.
        let alloc = HashMap::from([(spilled, RAX), (a, RCX), (b, RDX)]);
        materialize_x86_spills(&mut func, &installed, X86CallAbi::SystemV).unwrap();
        (func, installed, alloc)
    }

    /// The canonical win: the spiller emitted two reloads of one slot into the
    /// SAME scratch with nothing between that touches either, and the second is
    /// deleted.
    #[test]
    fn x86_reload_elide_deletes_a_second_reload_of_one_slot() {
        let (mut func, installed, alloc) = reload_elide_fixture(vec![]);
        assert_eq!(
            entry_opcodes(&func),
            vec![
                X86Opcode::MovRM,
                X86Opcode::AddRR,
                X86Opcode::MovRM,
                X86Opcode::AddRR,
                X86Opcode::Ret
            ],
            "the spiller must emit two reloads for this shape"
        );

        let evidence = elide_redundant_x86_spill_reloads(&mut func, &installed, &alloc);
        assert_eq!(evidence.deleted, 1);
        assert_eq!(evidence.rewritten, 0);
        assert_eq!(
            entry_opcodes(&func),
            vec![
                X86Opcode::MovRM,
                X86Opcode::AddRR,
                X86Opcode::AddRR,
                X86Opcode::Ret
            ]
        );
    }

    /// Rule 1: an instruction that CLOBBERS the holder between the two reloads
    /// keeps the second. Without this the pass would read a stale scratch.
    #[test]
    fn x86_reload_elide_refuses_across_a_clobber_of_the_holder() {
        use trust_cg_ir::x86_64_regs::R10;
        let clobber = X86ISelInst::new(
            X86Opcode::MovRI,
            vec![X86ISelOperand::PReg(R10), X86ISelOperand::Imm(7)],
        );
        let (mut func, installed, alloc) = reload_elide_fixture(vec![clobber]);
        let before = entry_opcodes(&func);
        let evidence = elide_redundant_x86_spill_reloads(&mut func, &installed, &alloc);
        assert_eq!(evidence.total(), 0, "a clobbered holder must not be reused");
        assert_eq!(entry_opcodes(&func), before);
    }

    /// Rule 3: a CALL clears everything — it clobbers the scratch registers and
    /// may write any slot whose address escaped.
    #[test]
    fn x86_reload_elide_refuses_across_a_call() {
        let call = X86ISelInst::new(
            X86Opcode::Call,
            vec![X86ISelOperand::Symbol("callee".to_string())],
        );
        let (mut func, installed, alloc) = reload_elide_fixture(vec![call]);
        let before = entry_opcodes(&func);
        let evidence = elide_redundant_x86_spill_reloads(&mut func, &installed, &alloc);
        assert_eq!(evidence.total(), 0);
        assert_eq!(entry_opcodes(&func), before);
    }

    /// Rule 4: a store this pass does not recognise could have written the slot,
    /// so everything goes.
    #[test]
    fn x86_reload_elide_refuses_across_an_unrecognized_store() {
        use trust_cg_ir::x86_64_regs::{RCX, RSI};
        let store = X86ISelInst::new(
            X86Opcode::MovMR,
            vec![
                X86ISelOperand::MemAddr {
                    base: Box::new(X86ISelOperand::PReg(RSI)),
                    disp: 0,
                },
                X86ISelOperand::PReg(RCX),
            ],
        );
        let (mut func, installed, alloc) = reload_elide_fixture(vec![store]);
        let before = entry_opcodes(&func);
        let evidence = elide_redundant_x86_spill_reloads(&mut func, &installed, &alloc);
        assert_eq!(evidence.total(), 0);
        assert_eq!(entry_opcodes(&func), before);
    }

    /// Rule 1b: a def this pass cannot resolve to a physical register clears the
    /// map. An incomplete allocation must not read as "clobbers nothing" —
    /// that is the difference between fail-closed and a wrong-value reuse.
    #[test]
    fn x86_reload_elide_fails_closed_on_an_unresolvable_def() {
        let (mut func, installed, alloc) = reload_elide_fixture(vec![]);
        let mut partial = alloc.clone();
        partial.remove(&VReg::new(1, RegClass::Gpr64));
        let before = entry_opcodes(&func);
        let evidence = elide_redundant_x86_spill_reloads(&mut func, &installed, &partial);
        assert_eq!(
            evidence.total(),
            0,
            "an unmapped def must clear the map, not be treated as harmless"
        );
        assert_eq!(entry_opcodes(&func), before);

        // The same function under the COMPLETE allocation DOES fire, so the
        // refusal above is about the allocation and not about the shape.
        let evidence = elide_redundant_x86_spill_reloads(&mut func, &installed, &alloc);
        assert_eq!(evidence.deleted, 1);
    }

    /// Nothing crosses a block boundary: physical-register liveness across edges
    /// is exactly the reasoning this pass declines to do.
    #[test]
    fn x86_reload_elide_does_not_cross_a_block_boundary() {
        use trust_cg_ir::x86_64_regs::{RAX, RCX};

        let mut func = minimal_func("reload_elide_blocks");
        let entry = Block(0);
        let next = Block(1);
        func.ensure_block(next);
        let spilled = VReg::new(0, RegClass::Gpr64);
        let a = VReg::new(1, RegClass::Gpr64);
        func.next_vreg = 2;
        func.stack_slots.push(StackSlotInfo::new(8, 8));
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::AddRR,
                vec![X86ISelOperand::VReg(a), X86ISelOperand::VReg(spilled)],
            ),
        );
        func.push_inst(
            entry,
            X86ISelInst::new(X86Opcode::Jmp, vec![X86ISelOperand::Block(next)]),
        );
        func.push_inst(
            next,
            X86ISelInst::new(
                X86Opcode::AddRR,
                vec![X86ISelOperand::VReg(a), X86ISelOperand::VReg(spilled)],
            ),
        );
        func.push_inst(next, X86ISelInst::new(X86Opcode::Ret, vec![]));

        let installed = HashMap::from([(spilled, 0u32)]);
        let alloc = HashMap::from([(spilled, RAX), (a, RCX)]);
        materialize_x86_spills(&mut func, &installed, X86CallAbi::SystemV).unwrap();
        let evidence = elide_redundant_x86_spill_reloads(&mut func, &installed, &alloc);
        assert_eq!(evidence.total(), 0);
        assert_eq!(
            func.blocks[&next].insts[0].opcode,
            X86Opcode::MovRM,
            "the second block's reload must survive"
        );
    }

    #[test]
    fn test_materialize_spills_reloads_two_operand_add_lhs() {
        use trust_cg_ir::x86_64_regs::R10;

        let mut func = minimal_func("two_operand_spill_reload");
        let entry = Block(0);
        let v0 = VReg::new(0, RegClass::Gpr64);
        let v1 = VReg::new(1, RegClass::Gpr64);
        func.next_vreg = 2;
        func.stack_slots.push(StackSlotInfo::new(8, 8));

        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::AddRR,
                vec![X86ISelOperand::VReg(v0), X86ISelOperand::VReg(v1)],
            ),
        );
        func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));

        let installed_spills = HashMap::from([(v0, 0)]);
        materialize_x86_spills(&mut func, &installed_spills, X86CallAbi::SystemV).unwrap();

        let insts = &func.blocks[&entry].insts;
        assert_eq!(
            entry_opcodes(&func),
            vec![
                X86Opcode::MovRM,
                X86Opcode::AddRR,
                X86Opcode::MovMR,
                X86Opcode::Ret
            ]
        );
        assert_eq!(insts[0].operands[0], X86ISelOperand::PReg(R10));
        assert_eq!(insts[0].operands[1], x86_spill_stack_mem(0));
        assert_eq!(
            insts[1].operands,
            vec![X86ISelOperand::PReg(R10), X86ISelOperand::VReg(v1)]
        );
        assert_eq!(insts[2].operands[0], x86_spill_stack_mem(0));
        assert_eq!(insts[2].operands[1], X86ISelOperand::PReg(R10));
    }

    #[test]
    fn test_two_address_spilled_pair_declines_dst_rhs_alias() {
        // The s31226 shape: `AddRR vX, vY, vX` (copy coalescing merged the
        // result with the RHS source) with everything spilled. Aliasing
        // dst with LHS would force the rhs reload into the same scratch,
        // clobbering the lhs value (`movl p3->r10d; movl p2->r10d;
        // addl r10d,r10d` computed p2+p2 where p3+p2 was required).
        let vx = VReg::new(0, RegClass::Gpr64);
        let vy = VReg::new(1, RegClass::Gpr64);
        let inst = X86ISelInst::new(
            X86Opcode::AddRR,
            vec![
                X86ISelOperand::VReg(vx),
                X86ISelOperand::VReg(vy),
                X86ISelOperand::VReg(vx),
            ],
        );
        let installed = HashMap::from([(vx, 0u32), (vy, 1u32)]);
        assert!(
            x86_two_address_spilled_pair(&inst, &installed).is_none(),
            "dst==rhs must decline the dst/lhs scratch aliasing"
        );
        // The healthy three-address shape still aliases.
        let vz = VReg::new(2, RegClass::Gpr64);
        let healthy = X86ISelInst::new(
            X86Opcode::AddRR,
            vec![
                X86ISelOperand::VReg(vx),
                X86ISelOperand::VReg(vy),
                X86ISelOperand::VReg(vz),
            ],
        );
        assert_eq!(
            x86_two_address_spilled_pair(&healthy, &installed),
            Some((vx, vy))
        );
    }

    #[test]
    fn test_materialize_spills_dst_rhs_alias_uses_two_scratches() {
        use trust_cg_ir::x86_64_regs::{R10, R11};
        // Function-level pin of the s31226 fix: the all-spilled
        // `AddRR vX, vY, vX` must reload vY into a DIFFERENT scratch than
        // vX so the add reads both true values. fixup_two_address then
        // repairs the preg-level dst/rhs alias downstream (commutative
        // swap) — here we only pin the materializer's scratch assignment.
        let mut func = minimal_func("dst_rhs_alias_spill");
        let entry = Block(0);
        let vx = VReg::new(0, RegClass::Gpr64);
        let vy = VReg::new(1, RegClass::Gpr64);
        func.next_vreg = 2;
        func.stack_slots.push(StackSlotInfo::new(8, 8));
        func.stack_slots.push(StackSlotInfo::new(8, 8));
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::AddRR,
                vec![
                    X86ISelOperand::VReg(vx),
                    X86ISelOperand::VReg(vy),
                    X86ISelOperand::VReg(vx),
                ],
            ),
        );
        func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));
        let installed = HashMap::from([(vx, 0u32), (vy, 1u32)]);
        materialize_x86_spills(&mut func, &installed, X86CallAbi::SystemV).unwrap();

        let insts = &func.blocks[&entry].insts;
        let reload_dsts: Vec<X86PReg> = insts
            .iter()
            .take_while(|i| i.opcode == X86Opcode::MovRM)
            .map(|i| match &i.operands[0] {
                X86ISelOperand::PReg(p) => *p,
                other => panic!("reload dst must be a preg, got {other:?}"),
            })
            .collect();
        assert_eq!(
            reload_dsts.len(),
            2,
            "both source values need a reload: {insts:?}"
        );
        assert_ne!(
            reload_dsts[0], reload_dsts[1],
            "the two reloads must not share a scratch (the s31226 clobber)"
        );
        assert!(reload_dsts.contains(&R10) && reload_dsts.contains(&R11));
        let add = insts
            .iter()
            .find(|i| i.opcode == X86Opcode::AddRR)
            .expect("the add survives");
        let ops: Vec<&X86ISelOperand> = add.operands.iter().collect();
        assert!(
            matches!(
                (ops[0], ops[1], ops[2]),
                (
                    X86ISelOperand::PReg(d),
                    X86ISelOperand::PReg(l),
                    X86ISelOperand::PReg(r)
                ) if d == r && *l != *d
            ),
            "add must read two distinct scratches with dst==rhs: {add:?}"
        );
    }

    /// Concrete x86-64 execution of the closed post-spill subset the
    /// materialized `Icmp` bool sequence uses. Registers are keyed by hardware
    /// encoding so `r10d`/`r10b`/`r10` alias exactly as on hardware; `setcc`
    /// writes only bits 7:0 and a 32-bit write zero-extends. Anything outside
    /// the subset panics (fail-closed: an unknown instruction cannot pass).
    fn run_setcc_spill_subset(
        insts: &[X86ISelInst],
        vregs: &HashMap<VReg, u64>,
        slots: &mut HashMap<u32, u64>,
    ) {
        use trust_cg_ir::x86_64_regs::{X86RegClass, x86_hw_encoding, x86_preg_class};
        let mut gpr = [0xA5A5_A5A5_A5A5_A5A5u64; 16];
        let mut vregs = vregs.clone();
        let mut signed_less: Option<bool> = None;
        let width = |op: &X86ISelOperand| match op {
            X86ISelOperand::PReg(p) => match x86_preg_class(*p) {
                X86RegClass::Gpr64 => 64,
                X86RegClass::Gpr32 => 32,
                other => panic!("register class {other:?} outside the subset"),
            },
            X86ISelOperand::VReg(v) => match v.class {
                RegClass::Gpr64 => 64,
                RegClass::Gpr32 => 32,
                other => panic!("vreg class {other:?} outside the subset"),
            },
            other => panic!("operand {other:?} outside the subset"),
        };
        let slot_of = |op: &X86ISelOperand| match op {
            X86ISelOperand::MemAddr { base, disp: 0 } => match base.as_ref() {
                X86ISelOperand::StackSlot(s) => *s,
                other => panic!("memory base {other:?} outside the subset"),
            },
            other => panic!("memory operand {other:?} outside the subset"),
        };
        let read = |gpr: &[u64; 16], vregs: &HashMap<VReg, u64>, op: &X86ISelOperand| {
            let full = match op {
                X86ISelOperand::PReg(p) => gpr[usize::from(x86_hw_encoding(*p))],
                X86ISelOperand::VReg(v) => vregs[v],
                other => panic!("operand {other:?} outside the subset"),
            };
            if width(op) == 32 {
                full & 0xFFFF_FFFF
            } else {
                full
            }
        };
        // A 32-bit or 64-bit register write: x86-64 zero-extends a 32-bit
        // destination into the full register.
        let write = |gpr: &mut [u64; 16],
                     vregs: &mut HashMap<VReg, u64>,
                     op: &X86ISelOperand,
                     value: u64| {
            let value = if width(op) == 32 {
                value & 0xFFFF_FFFF
            } else {
                value
            };
            match op {
                X86ISelOperand::PReg(p) => gpr[usize::from(x86_hw_encoding(*p))] = value,
                X86ISelOperand::VReg(v) => {
                    vregs.insert(*v, value);
                }
                other => panic!("operand {other:?} outside the subset"),
            }
        };
        for inst in insts {
            let ops = inst.operands.as_slice();
            match (inst.opcode, ops) {
                (X86Opcode::MovRM32 | X86Opcode::MovRM, [dst, mem]) => {
                    let value = slots[&slot_of(mem)];
                    write(&mut gpr, &mut vregs, dst, value);
                }
                (X86Opcode::MovMR32, [mem, src]) => {
                    let slot = slot_of(mem);
                    let old = slots[&slot];
                    let low = read(&gpr, &vregs, src);
                    slots.insert(slot, (old & !0xFFFF_FFFF) | low);
                }
                (X86Opcode::MovMR, [mem, src]) => {
                    let value = read(&gpr, &vregs, src);
                    slots.insert(slot_of(mem), value);
                }
                (X86Opcode::XorRR, [dst, src]) => {
                    let value = read(&gpr, &vregs, dst) ^ read(&gpr, &vregs, src);
                    write(&mut gpr, &mut vregs, dst, value);
                    signed_less = None;
                }
                (X86Opcode::CmpRR, [lhs, rhs]) => {
                    assert_eq!(width(lhs), 64, "the fixture compares 64-bit values");
                    let (l, r) = (read(&gpr, &vregs, lhs), read(&gpr, &vregs, rhs));
                    signed_less = Some((l as i64) < (r as i64));
                }
                (X86Opcode::Setcc, [dst, X86ISelOperand::CondCode(X86CondCode::L)]) => {
                    let bit = u64::from(signed_less.expect("setcc reads live CMP flags"));
                    // SETcc r8 writes bits 7:0 only; bits 63:8 keep their value.
                    match dst {
                        X86ISelOperand::PReg(p) => {
                            let r = &mut gpr[usize::from(x86_hw_encoding(*p))];
                            *r = (*r & !0xFF) | bit;
                        }
                        X86ISelOperand::VReg(v) => {
                            let r = vregs.entry(*v).or_insert(0xA5A5_A5A5_A5A5_A5A5);
                            *r = (*r & !0xFF) | bit;
                        }
                        other => panic!("setcc destination {other:?} outside the subset"),
                    }
                }
                (X86Opcode::Movzx, [dst, src]) => {
                    let byte = read(&gpr, &vregs, src) & 0xFF;
                    write(&mut gpr, &mut vregs, dst, byte);
                }
                (X86Opcode::Ret, []) => return,
                _ => panic!("instruction {inst:?} outside the subset"),
            }
        }
        panic!("the fixture block must end in ret");
    }

    /// The default-on peephole followed by spill materialization must leave a
    /// materialized `a < b` bool equal to 0 or 1 in its stack slot.
    ///
    /// The retired setcc-hoist rewrote `cmp a,b; setl d; movzx d,d` into
    /// `xor d,d; cmp a,b; setl d`, relying on `setl` keeping the xor's zero in
    /// bits 31:8. Every register model (`x86_operand_access`,
    /// `effects::x86_operand0_may_be_read`, the post-RA dataflow check) treats
    /// `Setcc` as a pure def of operand 0, so the xor's value was dead there:
    /// with `d` and `a` spilled the `setl` got a fresh scratch (`r10d`, still
    /// holding `a` from the compare's reload) and stored
    /// `(a & !0xff) | cc` instead of `cc`.
    #[test]
    fn setcc_bool_survives_peephole_and_spill_materialization() {
        const GARBAGE: u64 = 0xDEAD_BEEF_CAFE_F00D;
        for (a, b) in [
            (0x1234_5678_i64, 0x7FFF_FFFF_i64),
            (0x7FFF_FF00, -1),
            (-0x100, 0x100),
            (0x100, 0x100),
        ] {
            let mut func = minimal_func("setcc_bool_spilled");
            let entry = Block(0);
            let va = VReg::new(0, RegClass::Gpr64);
            let vb = VReg::new(1, RegClass::Gpr64);
            let vd = VReg::new(2, RegClass::Gpr32);
            func.next_vreg = 3;
            func.stack_slots.push(StackSlotInfo::new(4, 4));
            func.stack_slots.push(StackSlotInfo::new(8, 8));
            func.push_inst(
                entry,
                X86ISelInst::new(
                    X86Opcode::CmpRR,
                    vec![X86ISelOperand::VReg(va), X86ISelOperand::VReg(vb)],
                ),
            );
            func.push_inst(
                entry,
                X86ISelInst::new(
                    X86Opcode::Setcc,
                    vec![
                        X86ISelOperand::VReg(vd),
                        X86ISelOperand::CondCode(X86CondCode::L),
                    ],
                ),
            );
            func.push_inst(
                entry,
                X86ISelInst::new(
                    X86Opcode::Movzx,
                    vec![X86ISelOperand::VReg(vd), X86ISelOperand::VReg(vd)],
                ),
            );
            func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));

            trust_cg_opt::X86Peephole::default().run_on_function(&mut func);

            let insts = func.blocks[&entry].insts.clone();

            // Value check: spill `d` and `a`, materialize, and execute.
            let installed = HashMap::from([(vd, 0u32), (va, 1u32)]);
            materialize_x86_spills(&mut func, &installed, X86CallAbi::SystemV).unwrap();
            let mut slots = HashMap::from([(0u32, GARBAGE), (1u32, a as u64)]);
            let vregs = HashMap::from([(vb, b as u64)]);
            run_setcc_spill_subset(&func.blocks[&entry].insts, &vregs, &mut slots);
            let expected = u64::from(a < b);
            assert_eq!(
                slots[&0] & 0xFFFF_FFFF,
                expected,
                "a={a:#x} b={b:#x}: the spilled bool must be exactly a<b; \
                 materialized block: {:?}",
                func.blocks[&entry].insts
            );

            // Model check: a `Setcc` whose destination is not immediately
            // zero-extended exposes bits 31:8, so a register model that reads
            // it as a pure def must never see one.
            for (i, inst) in insts.iter().enumerate() {
                if inst.opcode == X86Opcode::Setcc {
                    let dst = inst.operands[0].clone();
                    assert!(
                        matches!(
                            insts.get(i + 1),
                            Some(next) if next.opcode == X86Opcode::Movzx
                                && next.operands == vec![dst.clone(), dst.clone()]
                        ),
                        "Setcc at {i} is not zero-extended, but every register model \
                         reads it as a pure def: {insts:?}"
                    );
                }
            }
        }
    }

    #[test]
    fn test_materialize_dst_rhs_alias_noncommutative_fixup_end_to_end() {
        use trust_cg_ir::x86_64_regs::{R10, R11};
        // The non-commutative sibling of the s31226 shape: `SubRR vX,vY,vX`
        // (x = y - x) all-spilled. The materializer gives dst/rhs one
        // scratch and lhs another; fixup_two_address must then repair the
        // preg-level dst==rhs alias via its scratch-copy path, and its
        // scratch selector must avoid both spill scratches (it avoids the
        // operand set AND every allocated preg — pinned here end-to-end).
        let mut func = minimal_func("dst_rhs_alias_noncommutative");
        let entry = Block(0);
        let vx = VReg::new(0, RegClass::Gpr64);
        let vy = VReg::new(1, RegClass::Gpr64);
        func.next_vreg = 2;
        func.stack_slots.push(StackSlotInfo::new(8, 8));
        func.stack_slots.push(StackSlotInfo::new(8, 8));
        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::SubRR,
                vec![
                    X86ISelOperand::VReg(vx),
                    X86ISelOperand::VReg(vy),
                    X86ISelOperand::VReg(vx),
                ],
            ),
        );
        func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));
        let installed = HashMap::from([(vx, 0u32), (vy, 1u32)]);
        materialize_x86_spills(&mut func, &installed, X86CallAbi::SystemV).unwrap();

        // The materializer itself keeps the values apart (two scratches):
        let reloads: Vec<X86PReg> = func.blocks[&entry]
            .insts
            .iter()
            .take_while(|i| i.opcode == X86Opcode::MovRM)
            .filter_map(|i| match i.operands.first() {
                Some(X86ISelOperand::PReg(p)) => Some(*p),
                _ => None,
            })
            .collect();
        assert!(reloads.contains(&R10) && reloads.contains(&R11));

        // Downstream, fixup_two_address FAIL-CLOSES on this shape: its
        // scratch candidate pool is exactly the reserved spill scratches,
        // and both are operands here — so it refuses loudly instead of
        // picking a live register. Sound (no silent wrong code is
        // reachable); a completeness gap only if a real program ever hits
        // an all-spilled non-commutative dst==rhs, in which case this
        // pinned error message says exactly what to widen.
        let alloc: HashMap<VReg, X86PReg> = HashMap::new();
        let err = fixup_two_address(&mut func, &alloc, X86CallAbi::SystemV)
            .expect_err("all-spilled non-commutative dst/rhs alias fail-closes");
        assert!(
            format!("{err:?}").contains("cannot repair dst/rhs alias"),
            "unexpected error: {err:?}"
        );
    }

    #[test]
