    #[test]
    fn test_materialize_spills_reloads_and_stores_fpr128_packed_lhs() {
        let mut func = minimal_func("fpr128_packed_spill_reload");
        let entry = Block(0);
        let v0 = VReg::new(0, RegClass::Fpr128);
        let v1 = VReg::new(1, RegClass::Fpr128);
        func.next_vreg = 2;
        func.stack_slots.push(StackSlotInfo::new(16, 16));

        func.push_inst(
            entry,
            X86ISelInst::new(
                X86Opcode::Pand,
                vec![X86ISelOperand::VReg(v0), X86ISelOperand::VReg(v1)],
            ),
        );
        func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));

        let installed_spills = HashMap::from([(v0, 0)]);
        materialize_x86_spills(&mut func, &installed_spills, X86CallAbi::SystemV).unwrap();

        let insts = &func.blocks[&entry].insts;
        assert_eq!(
            entry_opcodes(&func),
            vec![
                X86Opcode::MovdquRM,
                X86Opcode::Pand,
                X86Opcode::MovdquMR,
                X86Opcode::Ret
            ]
        );
        assert_eq!(insts[0].operands[0], X86ISelOperand::PReg(XMM14));
        assert_eq!(insts[0].operands[1], x86_spill_stack_mem(0));
        assert_eq!(
            insts[1].operands,
            vec![X86ISelOperand::PReg(XMM14), X86ISelOperand::VReg(v1)]
        );
        assert_eq!(insts[2].operands[0], x86_spill_stack_mem(0));
        assert_eq!(insts[2].operands[1], X86ISelOperand::PReg(XMM14));
    }

    #[test]
    fn test_materialize_spills_folds_single_use_packed_rhs_reload() {
        for opcode in [
            X86Opcode::Paddb,
            X86Opcode::Paddw,
            X86Opcode::Paddd,
            X86Opcode::Psubb,
            X86Opcode::Psubw,
            X86Opcode::Psubd,
            X86Opcode::Pmullw,
            X86Opcode::Pand,
            X86Opcode::Por,
            X86Opcode::Pxor,
            X86Opcode::Pcmpgtb,
            X86Opcode::Pcmpgtw,
            X86Opcode::Pcmpeqd,
            X86Opcode::Pcmpgtd,
            X86Opcode::Pmuludq,
            X86Opcode::Pmulld,
            X86Opcode::Pcmpeqq,
            X86Opcode::Pcmpgtq,
        ] {
            let mut func = minimal_func("fpr128_packed_rhs_fold");
            let entry = Block(0);
            let acc = VReg::new(0, RegClass::Fpr128);
            let rhs = VReg::new(1, RegClass::Fpr128);
            func.next_vreg = 2;
            func.stack_slots.push(StackSlotInfo::new(16, 16));

            func.push_inst(
                entry,
                X86ISelInst::new(
                    opcode,
                    vec![
                        X86ISelOperand::VReg(acc),
                        X86ISelOperand::VReg(acc),
                        X86ISelOperand::VReg(rhs),
                    ],
                ),
            );
            func.push_inst(entry, X86ISelInst::new(X86Opcode::Ret, vec![]));

            let installed_spills = HashMap::from([(rhs, 0)]);
            let evidence =
                materialize_x86_spills(&mut func, &installed_spills, X86CallAbi::SystemV).unwrap();

            let insts = &func.blocks[&entry].insts;
            assert_eq!(entry_opcodes(&func), vec![opcode, X86Opcode::Ret]);
            assert_eq!(
                evidence.reload_count, 0,
                "{opcode:?} should fold the RHS reload"
            );
            assert_eq!(evidence.store_count, 0);
            assert_eq!(
                insts[0].operands,
                vec![
                    X86ISelOperand::VReg(acc),
                    X86ISelOperand::VReg(acc),
                    x86_spill_stack_mem(0),
                ],
                "{opcode:?} folding must preserve the explicit dst/lhs tie"
            );
        }
    }

